-- ==========================================================================
-- FILE 14/79  20261005000014_014_realtime_and_grants.sql
-- ==========================================================================

-- Campus+ migration 014 — realtime and grants
-- Supabase CLI filename: 20261005000014_014_realtime_and_grants.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 014 — realtime authorization and API grants
-- =============================================================================
-- Messaging strategy (spec §23):
--
--   DMs / group chat → Postgres Changes on `messages`, `conversations` and
--     `message_reads`. Realtime applies the table's RLS policies per subscriber,
--     so a student can only ever receive rows they are allowed to SELECT.
--
--   Random → Private Broadcast channels, because the `random_messages` table is
--     deliberately NOT readable by participants. Channel authorization is the
--     `realtime.messages` policy below, which requires session membership.
--
--   Notifications → Postgres Changes on `notifications` (own rows only).
--
-- No Socket.io, no custom WebSocket server, no presence (spec §90, §102).
-- =============================================================================

-- ----------------------------------------------------------------------------
-- Safe uuid parsing for channel topics
-- ----------------------------------------------------------------------------

create or replace function public.safe_uuid(p_value text)
returns uuid
language plpgsql
immutable
as $$
begin
  return p_value::uuid;
exception when others then
  return null;
end;
$$;

comment on function public.safe_uuid(text) is
  'Casts a topic fragment to uuid without raising. Used by realtime channel authorization.';

-- ----------------------------------------------------------------------------
-- Realtime publication
-- ----------------------------------------------------------------------------

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    begin
      alter publication supabase_realtime add table public.messages;
    exception when duplicate_object then null;
    end;
    begin
      alter publication supabase_realtime add table public.conversations;
    exception when duplicate_object then null;
    end;
    begin
      alter publication supabase_realtime add table public.message_reads;
    exception when duplicate_object then null;
    end;
    begin
      alter publication supabase_realtime add table public.notifications;
    exception when duplicate_object then null;
    end;
  end if;
end;
$$;

-- ----------------------------------------------------------------------------
-- Private channel authorization (realtime.messages policies)
-- ----------------------------------------------------------------------------
-- Topics used by the application:
--   conversation:<conversation uuid>  — DM / group chat rooms
--   random:<session uuid>             — anonymous Random rooms
--   user:<profile uuid>               — per-user fan-out (notification badges)

do $$
begin
  if to_regclass('realtime.messages') is null then
    raise notice 'realtime.messages not present (plain Postgres). Skipping channel policies.';
    return;
  end if;

  -- Read (subscribe/receive)
  execute $policy$
    drop policy if exists campus_channels_read on realtime.messages;
  $policy$;
  execute $policy$
    create policy campus_channels_read on realtime.messages
      for select to authenticated
      using (
        case split_part(realtime.topic(), ':', 1)
          when 'conversation' then
            public.can_access_conversation(public.safe_uuid(split_part(realtime.topic(), ':', 2)))
          when 'random' then
            public.can_access_random_session(public.safe_uuid(split_part(realtime.topic(), ':', 2)))
          when 'user' then
            public.safe_uuid(split_part(realtime.topic(), ':', 2)) = public.current_profile_id()
          else false
        end
      );
  $policy$;

  -- Write (broadcast/send)
  execute $policy$
    drop policy if exists campus_channels_write on realtime.messages;
  $policy$;
  execute $policy$
    create policy campus_channels_write on realtime.messages
      for insert to authenticated
      with check (
        case split_part(realtime.topic(), ':', 1)
          when 'conversation' then
            public.can_access_conversation(public.safe_uuid(split_part(realtime.topic(), ':', 2)))
          when 'random' then
            public.can_access_random_session(public.safe_uuid(split_part(realtime.topic(), ':', 2)))
          when 'user' then
            public.safe_uuid(split_part(realtime.topic(), ':', 2)) = public.current_profile_id()
          else false
        end
      );
  $policy$;
end;
$$;

-- ----------------------------------------------------------------------------
-- Grants — least privilege for the two API roles
-- ----------------------------------------------------------------------------
-- `anon` keeps no access to Campus+ data: every policy in this schema targets
-- `authenticated`. These statements are belt-and-braces on top of that.

do $$
declare
  v_table text;
begin
  foreach v_table in array array[
    'colleges', 'profiles', 'profile_private', 'username_history', 'roles', 'permissions',
    'role_permissions', 'user_roles', 'blocks', 'mutes', 'communities', 'community_members',
    'community_join_requests', 'posts', 'comments', 'reactions', 'mentions', 'poll_options',
    'poll_votes', 'conversations', 'conversation_members', 'messages', 'message_edits',
    'message_reads', 'marketplace_categories', 'marketplace_listings', 'marketplace_interactions',
    'gigs', 'campus_deals', 'ratings', 'events', 'event_registrations', 'notices',
    'campus_locations', 'campus_services', 'transport_information', 'cafeteria_information',
    'academic_calendar', 'official_links', 'help_contacts', 'official_resources',
    'opportunities', 'lost_found', 'housing_posts', 'ride_posts', 'projects', 'team_posts',
    'team_post_requests', 'achievements', 'user_achievements', 'random_queue', 'random_sessions',
    'random_session_participants', 'random_messages', 'random_reports', 'reports',
    'moderation_actions', 'audit_logs', 'notifications', 'platform_settings', 'feature_flags',
    'reserved_usernames'
  ]
  loop
    execute format('revoke all on public.%I from anon', v_table);
  end loop;
end;
$$;

grant select on public.public_profiles to authenticated;
grant select on public.random_session_view to authenticated;
grant select on public.random_messages_view to authenticated;

-- ----------------------------------------------------------------------------
-- RPC surface — explicitly granted, explicitly revoked from anon
-- ----------------------------------------------------------------------------

do $$
declare
  v_fn text;
begin
  foreach v_fn in array array[
    'public.consume_rate_limit(text, text, integer, integer)',
    'public.notify_user(uuid, public.notification_type, text, text, text, text, text)',
    'public.mark_notification_read(uuid)',
    'public.mark_all_notifications_read()',
    'public.log_audit(text, text, text, jsonb, boolean, text, public.moderation_visibility)',
    'public.record_mentions(text, uuid, text[])',
    'public.global_search(text, text, integer, integer)',
    'public.trending_posts(integer, integer)',
    'public.campus_feed(integer, integer, text)',
    'public.evaluate_achievements(uuid)',
    'public.get_or_create_direct_conversation(uuid)',
    'public.mark_conversation_read(uuid)',
    'public.can_access_conversation(uuid, uuid)',
    'public.conversation_member_ids(uuid)',
    'public.open_community_chat(uuid)',
    'public.join_random_queue()',
    'public.leave_random_queue()',
    'public.random_queue_state()',
    'public.random_session_state(uuid)',
    'public.send_random_message(uuid, text, jsonb)',
    'public.report_random_session(uuid, text, text)',
    'public.end_random_session(uuid, text)',
    'public.sweep_random_state()',
    'public.purge_random_data(integer)',
    'public.complete_profile(text, text, text, text, text, text, boolean)',
    'public.change_username(text)',
    'public.username_change_available_at()',
    'public.touch_last_seen()',
    'public.lift_expired_suspensions()',
    'public.is_blocked(uuid, uuid)',
    'public.feature_enabled(text)',
    'public.setting(text, jsonb)',
    'public.setting_int(text, integer)'
  ]
  loop
    execute format('grant execute on function %s to authenticated', v_fn);
    execute format('revoke execute on function %s from anon', v_fn);
  end loop;
end;
$$;

-- ==========================================================================
-- FILE 15/79  20261005000015_015_column_privileges.sql
-- ==========================================================================

-- Campus+ migration 015 — column privileges
-- Supabase CLI filename: 20261005000015_015_column_privileges.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 015 — field-level write control (column privileges)
-- =============================================================================
-- Row Level Security answers "whose rows may I touch?". Column privileges answer
-- "which fields may I write?" — and PostgreSQL enforces them before RLS or any
-- trigger runs, so a student who PATCHes `account_status`, `is_official`,
-- `reputation_score`, `status` or a counter receives a permission error.
--
-- Privileged transitions (suspend an account, hide a post, mark a listing
-- removed, award achievements) are performed by SECURITY DEFINER functions in
-- migration 016 — one explicit, audited code path each.
--
-- The `authenticated` role keeps full INSERT/SELECT/DELETE where the policies
-- allow it; only UPDATE is narrowed here.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- identity
-- ---------------------------------------------------------------------------

revoke update on public.profiles from authenticated, anon;
grant update (display_name, bio, branch, year, division, show_branch_year, allow_dms_from_everyone)
  on public.profiles to authenticated;

-- Private identity is never client-writable: onboarding and account lifecycle
-- changes run through complete_profile() / admin_set_account_status().
revoke update on public.profile_private from authenticated, anon;

-- ---------------------------------------------------------------------------
-- social
-- ---------------------------------------------------------------------------

revoke update on public.posts from authenticated, anon;
grant update (body, title, gif, visibility) on public.posts to authenticated;

revoke update on public.comments from authenticated, anon;
grant update (body, gif) on public.comments to authenticated;

revoke update on public.reactions from authenticated, anon;
grant update (kind) on public.reactions to authenticated;

-- Poll options are immutable once published: a poll must not be rewritten after
-- students have voted (edit the poll by closing it and posting a new one).
revoke update on public.poll_options from authenticated, anon;

-- ---------------------------------------------------------------------------
-- communities
-- ---------------------------------------------------------------------------

revoke update on public.communities from authenticated, anon;
grant update (name, description, subject, branch, year, meeting_info,
              recruitment_info, contact_info, external_url, visibility, join_policy)
  on public.communities to authenticated;

revoke update on public.community_members from authenticated, anon;
grant update (role, status) on public.community_members to authenticated;

revoke update on public.community_join_requests from authenticated, anon;
grant update (status, decided_by, decided_at) on public.community_join_requests to authenticated;

-- ---------------------------------------------------------------------------
-- messaging
-- ---------------------------------------------------------------------------

-- A conversation's own fields (title, status, membership bookkeeping) are
-- maintained by the database; members never patch a thread directly.
revoke update on public.conversations from authenticated, anon;

revoke update on public.conversation_members from authenticated, anon;
grant update (last_read_at, last_read_message_id, is_muted) on public.conversation_members to authenticated;

revoke update on public.messages from authenticated, anon;
grant update (body, gif) on public.messages to authenticated;

revoke update on public.message_reads from authenticated, anon;
grant update (last_read_at, last_message_id) on public.message_reads to authenticated;

-- ---------------------------------------------------------------------------
-- marketplace
-- ---------------------------------------------------------------------------

revoke update on public.marketplace_listings from authenticated, anon;
grant update (title, description, price, is_free, is_negotiable, condition,
              location, contact_note, category_id, status, reserved_for)
  on public.marketplace_listings to authenticated;

-- Contact details are released only through record_listing_interest() (buyer)
-- and get_listing_contact_note() (seller/moderator). Without this column grant
-- list, a client could scrape every seller's phone number straight off the
-- base table and the interest funnel would be decoration.
revoke select on public.marketplace_listings from authenticated, anon;
grant select (id, seller_id, category_id, title, description, price, is_free,
              is_negotiable, condition, location, status, reserved_for, sold_at,
              sold_to, view_count, contact_count, is_official, moderated_by,
              moderated_at, moderation_reason, created_at, updated_at,
              search_vector)
  on public.marketplace_listings to authenticated;

revoke update on public.gigs from authenticated, anon;
grant update (title, description, category, compensation, availability, category_id)
  on public.gigs to authenticated;

revoke update on public.campus_deals from authenticated, anon;
-- Deals are official content: every change goes through the staff RPCs.

revoke update on public.ratings from authenticated, anon;
grant update (score, comment) on public.ratings to authenticated;

-- ---------------------------------------------------------------------------
-- campus
-- ---------------------------------------------------------------------------

revoke update on public.events from authenticated, anon;
-- Staff manage events through the official-content actions (migration 016).

revoke update on public.event_registrations from authenticated, anon;
grant update (status, note) on public.event_registrations to authenticated;

revoke update on public.notices from authenticated, anon;

revoke update on public.official_resources from authenticated, anon;
grant update (title, description, url, branch, year, semester, subject, type)
  on public.official_resources to authenticated;

revoke update on public.opportunities from authenticated, anon;
grant update (title, organization, description, eligibility, deadline, url, location, mode)
  on public.opportunities to authenticated;

revoke update on public.lost_found from authenticated, anon;
grant update (title, description, location, occurred_on, status, resolved_at, resolved_by)
  on public.lost_found to authenticated;

revoke update on public.housing_posts from authenticated, anon;
grant update (title, description, area, budget, room_type, available_from, status)
  on public.housing_posts to authenticated;

revoke update on public.ride_posts from authenticated, anon;
grant update (origin, destination, ride_date, ride_time, description, seats, status)
  on public.ride_posts to authenticated;

revoke update on public.projects from authenticated, anon;
grant update (title, description, technologies, repo_url, live_url, team_members, status)
  on public.projects to authenticated;

revoke update on public.team_posts from authenticated, anon;
grant update (project_name, description, required_skills, team_size, deadline, status)
  on public.team_posts to authenticated;

revoke update on public.team_post_requests from authenticated, anon;
grant update (status, decided_at) on public.team_post_requests to authenticated;

-- Official content: the RLS policy already requires the matching permission
-- (manage_notices / manage_events / manage_official_content / manage_deals), so
-- granting the write columns to `authenticated` is safe — the policy is what
-- restricts who may use them.
grant update (title, body, category, importance, pinned, expires_at, status,
              published_at, updated_by) on public.notices to authenticated;

grant update (title, description, starts_on, ends_on, start_time, end_time, location,
              organizer, registration_info, registration_url, club_id, capacity,
              show_attendees, status, published_at, discussion_post_id, updated_by)
  on public.events to authenticated;

grant update (title, description, merchant, discount_details, valid_from, valid_until,
              contact_info, status, published_at, updated_by)
  on public.campus_deals to authenticated;

grant update (name, description, block, category, external_map_url, sort_order, status, updated_by)
  on public.campus_locations to authenticated;

grant update (title, description, category, location, hours, contact_info, external_url, status, updated_by)
  on public.campus_services to authenticated;

grant update (route_name, description, timings, pickup_locations, service_status, status, updated_by)
  on public.transport_information to authenticated;

grant update (title, description, menu_text, offers, hours, location, contact_info, status, updated_by)
  on public.cafeteria_information to authenticated;

grant update (title, description, entry_type, starts_on, ends_on, audience, status, updated_by)
  on public.academic_calendar to authenticated;

grant update (title, description, purpose, audience, url, deadline, status, updated_by)
  on public.official_links to authenticated;

grant update (title, category, description, contact_info, location, availability, sort_order, status, updated_by)
  on public.help_contacts to authenticated;

-- ---------------------------------------------------------------------------
-- moderation & system
-- ---------------------------------------------------------------------------

-- A report is never UPDATEd by a client: status changes go through
-- resolve_report(), triage through assign_report() (migration 016). Both are
-- permission-checked, audited and notify the reporter.
revoke update on public.reports from authenticated, anon;

-- The moderation trail and the audit trail are append-only: they are written by
-- log_audit() (SECURITY DEFINER) and never edited or deleted by any client.
revoke insert, update, delete on public.audit_logs from authenticated, anon;
revoke insert, update, delete on public.moderation_actions from authenticated, anon;

revoke update on public.random_sessions from authenticated, anon;
revoke update on public.random_reports from authenticated, anon;
grant update (status, resolution, reviewed_by, reviewed_at) on public.random_reports to authenticated;

-- Notifications: a user may only set read_at (the guard trigger enforces the rest).
revoke update on public.notifications from authenticated, anon;
grant update (read_at) on public.notifications to authenticated;

-- Identity/config tables are never client-updatable; use the admin actions.
revoke update on public.user_roles from authenticated, anon;
revoke update on public.roles from authenticated, anon;
revoke update on public.role_permissions from authenticated, anon;
revoke update on public.platform_settings from authenticated, anon;
revoke update on public.feature_flags from authenticated, anon;
revoke update on public.reserved_usernames from authenticated, anon;

-- Service role and operators keep full access (they are the maintenance path).
grant all on all tables in schema public to service_role;

-- ==========================================================================
-- FILE 16/79  20261005000016_016_staff_actions.sql
-- ==========================================================================

-- Campus+ migration 016 — staff actions
-- Supabase CLI filename: 20261005000016_016_staff_actions.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 016 — privileged actions (moderation, roles, account lifecycle)
-- =============================================================================
-- Every privileged transition is a single SECURITY DEFINER function that:
--   1. checks the caller's permission (the same `has_permission()` used by RLS),
--   2. checks the staffing hierarchy (nobody acts on a peer or a senior),
--   3. performs the change,
--   4. writes a moderation action and an audit entry (spec §59, §105),
--   5. notifies the affected student where that is appropriate.
--
-- Because column privileges (015) make these columns unwritable by clients, this
-- file is the ONLY way privileged state changes happen.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- Role assignment
-- ----------------------------------------------------------------------------

create or replace function public.grant_role(p_user uuid, p_role text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_rank integer;
  v_username text;
begin
  -- Operator context (secret key / maintenance script) may always assign roles.
  if not (public.has_permission('assign_roles') or public.is_trusted_writer()) then
    raise exception 'You do not have permission to assign roles.' using errcode = '42501';
  end if;
  select p.username into v_username from public.profiles p where p.id = p_user;
  if v_username is null then
    raise exception 'That student could not be found.' using errcode = '22023';
  end if;

  select r.rank into v_rank from public.roles r where r.key = p_role;
  if v_rank is null then
    raise exception 'That role does not exist.' using errcode = '22023';
  end if;
  if not public.is_trusted_writer() then
    if p_role = 'super_admin'
       and not (public.has_role('super_admin') and public.has_permission('manage_role_authority')) then
      raise exception 'Only a Super Admin can grant the Super Admin role.' using errcode = '42501';
    end if;
    if v_rank >= public.current_role_rank() then
      raise exception 'You cannot grant a role at or above your own level.' using errcode = '42501';
    end if;
  end if;

  insert into public.user_roles (user_id, role_key, granted_by)
  values (p_user, p_role, public.current_profile_id())
  on conflict (user_id, role_key) do nothing;

  perform public.log_audit('admin.role_granted', 'user', p_user::text,
    jsonb_build_object('role', p_role, 'username', v_username), true, null, 'admin');

  perform public.notify_user(p_user, 'moderation_notice',
    'Your Campus+ role changed',
    'You now have the ' || p_role || ' role on Campus+.',
    'profile', p_user::text, '/profile');

  return jsonb_build_object('ok', true, 'role', p_role);
end;
$$;

create or replace function public.revoke_role(p_user uuid, p_role text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_rank integer;
begin
  if not (public.has_permission('assign_roles') or public.is_trusted_writer()) then
    raise exception 'You do not have permission to change roles.' using errcode = '42501';
  end if;
  if p_role = 'student' then
    raise exception 'The student role is assigned automatically.' using errcode = '22023';
  end if;
  if p_user = public.current_profile_id() then
    raise exception 'You cannot remove your own role.' using errcode = '42501';
  end if;

  select r.rank into v_rank from public.roles r where r.key = p_role;
  if v_rank is null then
    raise exception 'That role does not exist.' using errcode = '22023';
  end if;
  if not public.is_trusted_writer() and v_rank >= public.current_role_rank() then
    raise exception 'You cannot revoke a role at or above your own level.' using errcode = '42501';
  end if;

  delete from public.user_roles where user_id = p_user and role_key = p_role;

  perform public.log_audit('admin.role_revoked', 'user', p_user::text,
    jsonb_build_object('role', p_role), true, null, 'admin');

  return jsonb_build_object('ok', true);
end;
$$;

-- ----------------------------------------------------------------------------
-- Account lifecycle
-- ----------------------------------------------------------------------------

create or replace function public.admin_set_account_status(
  p_user uuid,
  p_status public.account_status,
  p_reason text default null,
  p_duration_days integer default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_target_rank integer;
  v_until timestamptz;
  v_username text;
begin
  if p_user is null then
    raise exception 'Choose a student.' using errcode = '22023';
  end if;
  if p_user = v_actor then
    raise exception 'You cannot change your own account status here.' using errcode = '22023';
  end if;
  if not (public.is_trusted_writer() or public.is_active_profile(v_actor)) then
    raise exception 'Your account cannot perform moderation actions.' using errcode = '42501';
  end if;

  if not public.is_trusted_writer() then
    if p_status in ('suspended', 'banned') then
      if not public.has_permission('suspend_users') then
        raise exception 'You do not have permission to suspend accounts.' using errcode = '42501';
      end if;
    elsif not public.has_permission('manage_users') then
      raise exception 'You do not have permission to change account status.' using errcode = '42501';
    end if;

    v_target_rank := public.role_rank(p_user);
    if public.current_role_rank() <= v_target_rank then
      raise exception 'You cannot act on a student at or above your own level.' using errcode = '42501';
    end if;
  end if;

  if p_status = 'suspended' then
    v_until := now() + make_interval(days => greatest(coalesce(p_duration_days, 7), 1));
  end if;

  select p.username into v_username from public.profiles p where p.id = p_user;
  if v_username is null then
    raise exception 'That student could not be found.' using errcode = '22023';
  end if;

  update public.profile_private
     set account_status = p_status,
         status_reason = left(nullif(btrim(coalesce(p_reason, '')), ''), 500),
         suspended_until = v_until
   where profile_id = p_user;

  perform public.log_audit(
    case p_status
      when 'suspended' then 'moderation.user_suspended'
      when 'banned' then 'moderation.user_banned'
      when 'active' then 'moderation.user_reinstated'
      else 'admin.user_status_changed'
    end,
    'user', p_user::text,
    jsonb_build_object('status', p_status, 'duration_days', p_duration_days, 'username', v_username),
    true, p_reason, 'staff');

  if p_status in ('suspended', 'banned') then
    perform public.notify_user(p_user, 'moderation_notice',
      case when p_status = 'banned' then 'Your Campus+ account has been banned' else 'Your Campus+ account has been suspended' end,
      coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'Contact the Campus+ moderators if you believe this is a mistake.'),
      'profile', p_user::text, '/account-status');
  end if;

  return jsonb_build_object('ok', true, 'status', p_status, 'until', v_until);
end;
$$;

comment on function public.admin_set_account_status is
  'Suspend, ban, reinstate or deactivate an account. Rank-checked, audited and notified.';

create or replace function public.deactivate_own_account(p_reason text default null)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  update public.profile_private
     set account_status = 'deactivated',
         status_reason = left(nullif(btrim(coalesce(p_reason, '')), ''), 500)
   where profile_id = v_me;

  perform public.log_audit('account.deactivated', 'user', v_me::text,
    jsonb_build_object('reason', p_reason), false, null, 'private');

  return jsonb_build_object('ok', true);
end;
$$;

create or replace function public.reactivate_own_account()
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  update public.profile_private
     set account_status = 'active', status_reason = null, suspended_until = null
   where profile_id = v_me and account_status in ('deactivated', 'active');

  perform public.log_audit('account.reactivated', 'user', v_me::text, '{}'::jsonb, false, null, 'private');
  return jsonb_build_object('ok', true);
end;
$$;

-- ----------------------------------------------------------------------------
-- Content moderation
-- ----------------------------------------------------------------------------

create or replace function public.content_moderation_permission(p_target_type text)
returns text
language sql
immutable
as $$
  select case p_target_type
    when 'post' then 'remove_posts'
    when 'comment' then 'remove_comments'
    when 'marketplace_listing' then 'moderate_marketplace'
    when 'gig' then 'moderate_marketplace'
    when 'community' then 'moderate_communities'
    when 'club' then 'moderate_communities'
    when 'deal' then 'manage_deals'
    when 'event' then 'manage_events'
    when 'notice' then 'manage_notices'
    when 'resource' then 'manage_official_content'
    when 'opportunity' then 'manage_official_content'
    when 'project' then 'moderate_all'
    when 'lost_found' then 'moderate_all'
    when 'housing_post' then 'moderate_all'
    when 'ride_post' then 'moderate_all'
    else null
  end;
$$;

create or replace function public.moderate_content(
  p_target_type text,
  p_target_id uuid,
  p_action text,
  p_reason text default null,
  p_report_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_permission text;
  v_new_status text;
  v_author uuid;
  v_label text;
begin
  v_permission := public.content_moderation_permission(p_target_type);
  if v_permission is null then
    raise exception 'That content type cannot be moderated.' using errcode = '22023';
  end if;

  if not public.is_trusted_writer() then
    if not public.is_active_profile(public.current_profile_id()) then
      raise exception 'Your account cannot moderate content.' using errcode = '42501';
    end if;
    if not (public.has_permission(v_permission) or public.has_permission('moderate_all')) then
      raise exception 'You do not have permission to moderate this content.' using errcode = '42501';
    end if;
  end if;

  v_new_status := case p_action
    when 'hide' then 'hidden'
    when 'remove' then 'removed'
    when 'restore' then 'published'
    when 'approve' then 'published'
    when 'reject' then 'removed'
    else null
  end;

  if p_target_type in ('post', 'comment', 'marketplace_listing', 'gig', 'community', 'club',
                       'project', 'lost_found', 'housing_post', 'ride_post')
     and v_new_status is null then
    raise exception 'Unsupported action for this content type.' using errcode = '22023';
  end if;
  if p_target_type = 'marketplace_listing' and p_action = 'approve' then
    v_new_status := 'active';
  end if;

  if p_target_type = 'post' then
    update public.posts
       set status = v_new_status::public.content_status, moderated_by = public.current_profile_id(),
           moderated_at = now(), moderation_reason = left(p_reason, 500)
     where id = p_target_id
     returning author_id into v_author;
  elsif p_target_type = 'comment' then
    update public.comments
       set status = v_new_status::public.content_status, moderated_by = public.current_profile_id(),
           moderated_at = now(), moderation_reason = left(p_reason, 500)
     where id = p_target_id
     returning author_id into v_author;
  elsif p_target_type = 'marketplace_listing' then
    update public.marketplace_listings
       set status = v_new_status::public.listing_status, moderated_by = public.current_profile_id(),
           moderated_at = now(), moderation_reason = left(p_reason, 500)
     where id = p_target_id
     returning seller_id into v_author;
  elsif p_target_type = 'gig' then
    update public.gigs
       set status = v_new_status::public.content_status, moderated_by = public.current_profile_id(),
           moderated_at = now(), moderation_reason = left(p_reason, 500)
     where id = p_target_id
     returning creator_id into v_author;
  elsif p_target_type in ('community', 'club') then
    update public.communities
       set status = v_new_status::public.content_status
     where id = p_target_id
     returning created_by into v_author;
  elsif p_target_type = 'project' then
    update public.projects
       set status = v_new_status::public.content_status, moderated_by = public.current_profile_id(),
           moderated_at = now(), moderation_reason = left(p_reason, 500)
     where id = p_target_id
     returning creator_id into v_author;
  elsif p_target_type = 'lost_found' then
    update public.lost_found set status = v_new_status::public.content_status
     where id = p_target_id returning creator_id into v_author;
  elsif p_target_type = 'housing_post' then
    update public.housing_posts set status = v_new_status::public.content_status
     where id = p_target_id returning creator_id into v_author;
  elsif p_target_type = 'ride_post' then
    update public.ride_posts set status = v_new_status::public.content_status
     where id = p_target_id returning creator_id into v_author;
  elsif p_target_type in ('notice', 'event', 'resource', 'opportunity', 'deal') then
    -- Official content: staff already own these rows through RLS-managed updates.
    update public.audit_logs set id = id where false;  -- no-op keeps the branch explicit
    v_author := null;
  end if;

  perform public.log_audit('moderation.content_' || p_action, p_target_type, p_target_id::text,
    jsonb_build_object('report_id', p_report_id, 'status', v_new_status), true, p_reason, 'staff');

  if v_author is not null and p_action in ('hide', 'remove', 'reject') then
    v_label := replace(p_target_type, '_', ' ');
    perform public.notify_user(v_author, 'moderation_notice',
      'Your ' || v_label || ' was ' || case when p_action = 'hide' then 'hidden' else 'removed' end,
      coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'Review the Campus+ rules and post again.'),
      p_target_type, p_target_id::text, null);
  end if;

  return jsonb_build_object('ok', true, 'status', v_new_status);
end;
$$;

comment on function public.moderate_content is
  'Single moderation action path: permission check → status change → moderation action → audit log → author notification.';

-- ----------------------------------------------------------------------------
-- Reports
-- ----------------------------------------------------------------------------

create or replace function public.resolve_report(
  p_report_id uuid,
  p_status public.report_status,
  p_resolution text default null,
  p_target_action text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_report public.reports;
  v_actor uuid := public.current_profile_id();
begin
  if not (public.has_permission('review_reports') or public.has_permission('moderate_all') or public.is_trusted_writer()) then
    raise exception 'You do not have permission to review reports.' using errcode = '42501';
  end if;

  select * into v_report from public.reports where id = p_report_id;
  if v_report.id is null then
    raise exception 'That report could not be found.' using errcode = '22023';
  end if;

  if p_target_action is not null and p_target_action not in ('none') then
    perform public.moderate_content(v_report.target_type::text, v_report.target_id, p_target_action,
                                    p_resolution, p_report_id);
  end if;

  update public.reports
     set status = p_status,
         resolution = left(nullif(btrim(coalesce(p_resolution, '')), ''), 1000),
         reviewed_by = case when p_status in ('resolved', 'dismissed') then v_actor else reviewed_by end,
         reviewed_at = case when p_status in ('resolved', 'dismissed') then now() else reviewed_at end
   where id = p_report_id;

  update public.random_reports
     set status = p_status,
         resolution = left(nullif(btrim(coalesce(p_resolution, '')), ''), 1000),
         reviewed_by = case when p_status in ('resolved', 'dismissed') then v_actor else reviewed_by end,
         reviewed_at = case when p_status in ('resolved', 'dismissed') then now() else reviewed_at end
   where session_id = v_report.random_session_id;

  -- Tell the reporter the outcome (spec §53: report result).
  if p_status in ('resolved', 'dismissed') then
    perform public.notify_user(v_report.reporter_id, 'report_result',
      'Your report was ' || case when p_status = 'dismissed' then 'reviewed and dismissed' else 'actioned' end,
      coalesce(nullif(btrim(coalesce(p_resolution, '')), ''), 'Thanks for helping keep Campus+ usable.'),
      v_report.target_type::text, v_report.target_id::text, null);
  end if;

  return jsonb_build_object('ok', true, 'status', p_status);
end;
$$;

create or replace function public.assign_report(
  p_report uuid,
  p_to uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_target uuid := coalesce(p_to, v_me);
begin
  if not (public.has_permission('review_reports') or public.has_permission('moderate_all')) then
    raise exception 'You do not have permission to review reports.' using errcode = '42501';
  end if;
  if not public.is_active_profile(v_target) then
    raise exception 'That moderator cannot take reports right now.' using errcode = '22023';
  end if;

  update public.reports
     set assigned_to = v_target,
         status = case when status = 'pending' then 'reviewing'::public.report_status else status end
   where id = p_report and status in ('pending', 'reviewing');

  if not found then
    raise exception 'That report is not open for triage.' using errcode = '22023';
  end if;

  perform public.log_audit('moderation.report_assigned', 'report', p_report::text,
    jsonb_build_object('assigned_to', v_target), true, null, 'staff');

  return jsonb_build_object('ok', true, 'assigned_to', v_target);
end;
$$;

comment on function public.assign_report is
  'Claims an open report for a moderator. The only path that changes reports.assigned_to or moves pending → reviewing.';

-- ----------------------------------------------------------------------------
-- Self-service content deletion (soft delete keeps moderation evidence)
-- ----------------------------------------------------------------------------

create or replace function public.delete_own_content(p_target_type text, p_target_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_owner uuid;
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if p_target_type = 'post' then
    update public.posts set status = 'deleted', deleted_at = now()
     where id = p_target_id and author_id = v_me returning author_id into v_owner;
  elsif p_target_type = 'comment' then
    update public.comments set status = 'deleted', deleted_at = now()
     where id = p_target_id and author_id = v_me returning author_id into v_owner;
  elsif p_target_type = 'marketplace_listing' then
    update public.marketplace_listings set status = 'removed'
     where id = p_target_id and seller_id = v_me returning seller_id into v_owner;
  elsif p_target_type = 'gig' then
    update public.gigs set status = 'deleted'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'housing_post' then
    update public.housing_posts set status = 'deleted'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'ride_post' then
    update public.ride_posts set status = 'deleted'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'project' then
    update public.projects set status = 'deleted'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'team_post' then
    update public.team_posts set status = 'deleted'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'lost_found' then
    update public.lost_found set status = 'deleted'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'message' then
    update public.messages set deleted_at = now(), deleted_by = v_me
     where id = p_target_id and sender_id = v_me returning sender_id into v_owner;
  else
    raise exception 'That content type cannot be deleted here.' using errcode = '22023';
  end if;

  if v_owner is null then
    raise exception 'That content could not be found, or is not yours.' using errcode = '42501';
  end if;

  perform public.log_audit('content.self_deleted', p_target_type, p_target_id::text, '{}'::jsonb, false, null, 'private');
  return jsonb_build_object('ok', true);
end;
$$;

create or replace function public.restore_own_content(p_target_type text, p_target_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_owner uuid;
begin
  if p_target_type = 'post' then
    update public.posts set status = 'published', deleted_at = null
     where id = p_target_id and author_id = v_me and status = 'deleted' returning author_id into v_owner;
  elsif p_target_type = 'comment' then
    update public.comments set status = 'published', deleted_at = null
     where id = p_target_id and author_id = v_me and status = 'deleted' returning author_id into v_owner;
  elsif p_target_type = 'marketplace_listing' then
    update public.marketplace_listings set status = 'active'
     where id = p_target_id and seller_id = v_me and status = 'removed' returning seller_id into v_owner;
  elsif p_target_type = 'housing_post' then
    update public.housing_posts set status = 'published'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'ride_post' then
    update public.ride_posts set status = 'published'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'project' then
    update public.projects set status = 'published'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'gig' then
    update public.gigs set status = 'published'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'lost_found' then
    update public.lost_found set status = 'published'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  else
    raise exception 'That content type cannot be restored here.' using errcode = '22023';
  end if;

  if v_owner is null then
    raise exception 'That content could not be found, or is not yours.' using errcode = '42501';
  end if;
  return jsonb_build_object('ok', true);
end;
$$;

-- ----------------------------------------------------------------------------
-- Platform configuration
-- ----------------------------------------------------------------------------
-- Clients cannot UPDATE `platform_settings` (015 revokes the column privilege);
-- this function is the only in-app path. It validates the value against the
-- key's documented shape, so a mistyped setting cannot take the platform down,
-- and writes the change to the audit trail.
create or replace function public.admin_set_platform_setting(p_key text, p_value jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_old jsonb;
  v_text text;
  v_number numeric;
  v_item text;
begin
  if not public.has_permission('manage_platform_settings') then
    raise exception 'You do not have permission to change platform settings.' using errcode = '42501';
  end if;
  if p_value is null then
    raise exception 'A platform setting needs a value.' using errcode = '22023';
  end if;

  select value into v_old from public.platform_settings where key = p_key;
  if not found then
    raise exception 'That platform setting does not exist.' using errcode = '22023';
  end if;

  if p_key = 'allowed_email_domains' then
    if jsonb_typeof(p_value) <> 'array' or jsonb_array_length(p_value) = 0 then
      raise exception 'allowed_email_domains must be a non-empty list of domains.' using errcode = '22023';
    end if;
    -- Every entry must look like a domain (lowercase, at least one dot, no
    -- wildcards) so the sign-in gate can never be opened accidentally.
    for v_item in select jsonb_array_elements_text(p_value) loop
      if v_item <> lower(v_item)
         or v_item !~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$' then
        raise exception 'Invalid email domain: %', v_item using errcode = '22023';
      end if;
    end loop;

  elsif p_key = 'marketplace_approval_mode' then
    if jsonb_typeof(p_value) <> 'string'
       or (p_value #>> '{}') not in ('post_moderation', 'pre_moderation') then
      raise exception 'marketplace_approval_mode must be post_moderation or pre_moderation.' using errcode = '22023';
    end if;

  elsif p_key in ('username_change_cooldown_days', 'random_session_max_minutes',
                  'random_rematch_cooldown_seconds', 'random_retention_days') then
    if jsonb_typeof(p_value) <> 'number' then
      raise exception '% must be a number.', p_key using errcode = '22023';
    end if;
    v_number := (p_value #>> '{}')::numeric;
    if v_number <> trunc(v_number) or v_number < 0 then
      raise exception '% must be a whole number of zero or more.', p_key using errcode = '22023';
    end if;
    if p_key = 'username_change_cooldown_days' and v_number > 365 then
      raise exception 'The username change cooldown cannot exceed a year.' using errcode = '22023';
    elsif p_key = 'random_session_max_minutes' and v_number < 5 then
      raise exception 'A Random session must last at least five minutes.' using errcode = '22023';
    elsif p_key = 'random_retention_days' and v_number < 1 then
      raise exception 'Random sessions must be retained for at least one day.' using errcode = '22023';
    elsif p_key = 'random_rematch_cooldown_seconds' and v_number > 3600 then
      raise exception 'The rematch cooldown cannot exceed an hour.' using errcode = '22023';
    end if;

  elsif p_key in ('community_creation_open', 'student_opportunity_submission',
                  'feed_marketplace_highlights', 'show_event_attendees') then
    if jsonb_typeof(p_value) <> 'boolean' then
      raise exception '% must be true or false.', p_key using errcode = '22023';
    end if;

  elsif p_key = 'moderate_community_submissions' then
    if jsonb_typeof(p_value) <> 'object'
       or jsonb_typeof(p_value -> 'resource') <> 'boolean'
       or jsonb_typeof(p_value -> 'opportunity') <> 'boolean' then
      raise exception 'moderate_community_submissions needs resource and opportunity booleans.' using errcode = '22023';
    end if;

  elsif p_key = 'feed_ranking' then
    if p_value <> '"deterministic_v1"'::jsonb then
      raise exception 'Campus+ only supports deterministic feed ranking.' using errcode = '22023';
    end if;

  else
    -- Branding text values: short strings only.
    if jsonb_typeof(p_value) <> 'string' then
      raise exception '% must be text.', p_key using errcode = '22023';
    end if;
    v_text := p_value #>> '{}';
    if length(v_text) > 200 then
      raise exception '% cannot be longer than 200 characters.', p_key using errcode = '22023';
    end if;
    if p_key in ('platform_name', 'institution_name') and btrim(v_text) = '' then
      raise exception '% cannot be empty.', p_key using errcode = '22023';
    end if;
  end if;

  update public.platform_settings
     set value = p_value, updated_by = public.current_profile_id()
   where key = p_key;

  perform public.log_audit('admin.setting_changed', 'platform_settings', p_key,
    jsonb_build_object('old', v_old, 'new', p_value), true, null, 'admin');

  return jsonb_build_object('ok', true, 'key', p_key, 'value', p_value);
end;
$$;

comment on function public.admin_set_platform_setting(text, jsonb) is
  'Admin/Super Admin entry point for platform configuration. Validates the value per key and writes an audit entry.';

-- ==========================================================================
-- FILE 17/79  20261005000017_017_marketplace_hardening.sql
-- ==========================================================================

-- Campus+ migration 017 — marketplace hardening
-- Supabase CLI filename: 20261005000017_017_marketplace_hardening.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 017 — marketplace: interest → contact → completion
-- =============================================================================
-- One explicit funnel, all of it server-side:
--
--   browse (no contact details) → "I'm interested"  → contact details + DM
--                               → seller marks the item sold → ratings allowed
--
-- Blocking is respected at every step, and the seller is notified once.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- Express interest: records the interaction, notifies the seller, and only then
-- hands back the contact note.
-- ----------------------------------------------------------------------------

create or replace function public.record_listing_interest(p_listing uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_listing public.marketplace_listings;
  v_interaction uuid;
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if not public.is_active_user() then
    raise exception 'Your account cannot use the marketplace.' using errcode = '42501';
  end if;
  if not public.feature_enabled('marketplace') then
    raise exception 'The marketplace is disabled.' using errcode = '42501';
  end if;

  select * into v_listing from public.marketplace_listings where id = p_listing;
  if v_listing.id is null or v_listing.status not in ('active', 'reserved') then
    raise exception 'That listing is no longer available.' using errcode = '22023';
  end if;
  if v_listing.seller_id = v_me then
    raise exception 'That is your own listing.' using errcode = '22023';
  end if;
  if public.is_blocked(v_me, v_listing.seller_id) or public.is_blocked(v_listing.seller_id, v_me) then
    raise exception 'You cannot contact this seller.' using errcode = '42501';
  end if;

  -- One 'contact' row per student per listing. A repeated tap returns the
  -- contact note again but must not notify the seller twice.
  insert into public.marketplace_interactions (listing_id, user_id, kind)
  values (p_listing, v_me, 'contact')
  on conflict do nothing
  returning id into v_interaction;

  if v_interaction is not null then
    perform public.notify_user(
      v_listing.seller_id, 'marketplace_status',
      'Someone is interested in your listing',
      'A student asked about "' || left(v_listing.title, 80) || '".',
      'marketplace_listing', p_listing::text, '/market/listing/' || p_listing::text
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'seller_id', v_listing.seller_id,
    'contact_note', v_listing.contact_note
  );
end;
$$;

comment on function public.record_listing_interest(uuid) is
  'The only path that reveals a listing''s contact details. Records the interaction and notifies the seller.';

-- ----------------------------------------------------------------------------
-- The seller (and moderators) keep access to the contact note they own.
-- ----------------------------------------------------------------------------
-- Clients lost SELECT on `contact_note` in migration 015, so the seller's edit
-- form reads it through here instead of the base table.
create or replace function public.get_listing_contact_note(p_listing uuid)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_note text;
  v_seller uuid;
begin
  select l.contact_note, l.seller_id into v_note, v_seller
  from public.marketplace_listings l
  where l.id = p_listing;
  if v_seller is null then
    raise exception 'That listing could not be found.' using errcode = '22023';
  end if;
  if not (v_seller = public.current_profile_id()
          or public.has_permission('moderate_marketplace')
          or public.is_trusted_writer()) then
    raise exception 'Contact details are released only through the interest flow.' using errcode = '42501';
  end if;
  return v_note;
end;
$$;

comment on function public.get_listing_contact_note(uuid) is
  'Owner/moderator read of a listing contact note; buyers get it from record_listing_interest().';

-- ----------------------------------------------------------------------------
-- The seller closes the loop. `sold_to` is what unlocks buyer ratings, so it is
-- set here rather than by the client.
-- ----------------------------------------------------------------------------

create or replace function public.mark_listing_completed(p_listing uuid, p_buyer uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_buyer uuid := p_buyer;
  v_seller uuid;
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  select seller_id into v_seller from public.marketplace_listings where id = p_listing;
  if v_seller is null then
    raise exception 'That listing could not be found.' using errcode = '22023';
  end if;
  if v_seller <> v_me and not public.has_permission('moderate_marketplace') then
    raise exception 'Only the seller can mark a listing as sold.' using errcode = '42501';
  end if;

  if v_buyer is null then
    -- Default to the student who most recently showed interest.
    select i.user_id into v_buyer
    from public.marketplace_interactions i
    where i.listing_id = p_listing and i.kind = 'contact'
    order by i.created_at desc
    limit 1;
  end if;
  if v_buyer is null then
    raise exception 'Choose the student the item was handed to.' using errcode = '22023';
  end if;
  if v_buyer = v_seller then
    raise exception 'The buyer cannot be the seller.' using errcode = '22023';
  end if;

  update public.marketplace_listings
     set status = 'sold', sold_to = v_buyer, sold_at = now()
   where id = p_listing;

  perform public.notify_user(
    v_buyer, 'marketplace_rating',
    'You can now rate this trade',
    'The seller marked "' || left(coalesce((select title from public.marketplace_listings where id = p_listing), 'a listing'), 80)
      || '" as completed. Leave a rating to help other students.',
    'marketplace_listing', p_listing::text, '/market/listing/' || p_listing::text
  );

  perform public.log_audit('marketplace.completed', 'marketplace_listing', p_listing::text,
    jsonb_build_object('buyer_id', v_buyer), false, null, 'private');

  return jsonb_build_object('ok', true, 'buyer_id', v_buyer);
end;
$$;

-- ----------------------------------------------------------------------------
-- The seller's own view of who is interested (RLS already restricts this to the
-- seller and staff; this view adds the student's public identity in one read).
-- ----------------------------------------------------------------------------

create or replace view public.listing_interests_view
with (security_invoker = true) as
select
  i.id,
  i.listing_id,
  i.user_id,
  pr.username,
  pr.display_name,
  i.created_at
from public.marketplace_interactions i
join public.public_profiles pr on pr.id = i.user_id
where i.kind = 'contact';

comment on view public.listing_interests_view is
  'Students who expressed interest in a listing. Visible only to the seller and staff (security_invoker + base-table RLS).';

-- ==========================================================================
-- FILE 18/79  20261005000018_018_function_grants.sql
-- ==========================================================================

-- =============================================================================
-- Campus+ migration 018 — final function grants
-- =============================================================================
-- This file runs last so that every function defined by earlier migrations is
-- reachable by `authenticated` and unreachable by `anon`.
--
-- Two layers matter:
--
--   1. PostgreSQL grants EXECUTE on every new function to PUBLIC by default, so
--      `anon` inherits the whole RPC surface unless it is revoked explicitly.
--      Campus+ has no anonymous features, so PUBLIC loses EXECUTE entirely and
--      the default is changed for functions created by future migrations too.
--
--   2. Every function that changes state validates the caller itself
--      (has_permission, ownership, rank, or is_trusted_writer). Granting
--      EXECUTE is therefore not a privilege escalation: it only makes the
--      audited entry point callable.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- 1. Remove the PostgreSQL default (EXECUTE to PUBLIC) from existing functions
-- ----------------------------------------------------------------------------

do $$
declare
  v_fn record;
begin
  for v_fn in
    select p.oid::regprocedure as signature
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.prokind = 'f'
  loop
    -- Explicit, not inherited: authenticated and service_role only.
    execute format('revoke all on function %s from public', v_fn.signature);
    execute format('revoke all on function %s from anon', v_fn.signature);
    execute format('grant execute on function %s to authenticated', v_fn.signature);
    execute format('grant execute on function %s to service_role', v_fn.signature);
  end loop;
end;
$$;

-- Same rule for anything a future migration adds. `alter default privileges`
-- applies to objects created by the role running it (postgres, the migration
-- owner), which is exactly the CLI's role.
alter default privileges in schema public revoke execute on functions from public;
alter default privileges in schema public grant execute on functions to service_role;
alter default privileges in schema public grant execute on functions to authenticated;

-- ----------------------------------------------------------------------------
-- 2. Tables, sequences and views
-- ----------------------------------------------------------------------------

-- NOTE: this loop only removes access from anon/PUBLIC. It deliberately does not
-- touch `authenticated`: the two-dimensional grant matrix (which *rows* via RLS,
-- which *columns* via migration 015) is authoritative there, and a blanket
-- `grant update` here would silently undo 015's column privileges.
do $$
declare
  v_rel record;
begin
  for v_rel in
    select c.oid::regclass as name, c.relkind
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind in ('r', 'p', 'v', 'm', 'S')
  loop
    execute format('revoke all on %s from anon', v_rel.name);
    execute format('revoke all on %s from public', v_rel.name);
    execute format('grant all on %s to service_role', v_rel.name);
    if v_rel.relkind = 'S' then
      execute format('grant usage, select on %s to authenticated', v_rel.name);
    elsif v_rel.relkind in ('v', 'm') then
      -- RLS of the base tables still applies (security_invoker) unless a definer
      -- view is intentionally whitelisted (see migration 010).
      execute format('grant select on %s to authenticated', v_rel.name);
    end if;
  end loop;
end;
$$;

-- Defaults for objects future migrations add: no anonymous access, no client
-- UPDATE unless a column grant says so. `authenticated` keeps SELECT/INSERT/DELETE
-- so a new table is usable immediately, with RLS as the row boundary.
alter default privileges in schema public revoke all on tables from public;
alter default privileges in schema public revoke all on tables from anon;
alter default privileges in schema public grant all on tables to service_role;
alter default privileges in schema public grant select, insert, delete on tables to authenticated;
alter default privileges in schema public grant usage, select on sequences to authenticated, service_role;

-- Schema usage: the API roles need to see the schema, but nothing else.
revoke all on schema public from anon, public;
grant usage on schema public to anon, authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 3. Explicitly public, pre-authentication helpers
-- ----------------------------------------------------------------------------
-- The sign-in screen checks a domain *before* a session exists. These two
-- functions are pure, read-only and harmless, so anon may call them:

grant execute on function public.allowed_email_domain(text) to anon;
grant execute on function public.is_reserved_username(text) to anon;
grant execute on function public.feature_enabled(text) to anon;
grant execute on function public.setting(text, jsonb) to anon;

-- Views that are intentionally readable by any signed-in student.
grant select on public.public_profiles to authenticated;
grant select on public.random_session_view to authenticated;
grant select on public.random_messages_view to authenticated;

-- ==========================================================================
-- FILE 19/79  20261005000019_019_staff_visibility.sql
-- ==========================================================================

-- =============================================================================
-- Campus+ migration 019 — staff visibility on the public projection
-- =============================================================================
-- Spec §13 requires a subtle staff marker next to a moderator's or admin's
-- username everywhere their content appears. `user_roles` is (correctly) not
-- readable for other students, so the application had no way to render that
-- marker: the badge was impossible without weakening a policy.
--
-- The fix is a single SECURITY DEFINER predicate plus one extra column on the
-- existing public projection. It answers exactly one boolean question — "does
-- this profile hold a moderator role or above?" — and reveals nothing else: not
-- which role, not when it was granted, not who granted it. Students have no row to show and
-- therefore see no marker, as the spec requires.
-- =============================================================================

create or replace function public.is_staff_profile(p_profile uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  -- `rank` is the role's level: student < moderator < admin < super admin.
  select exists (
    select 1
    from public.user_roles ur
    join public.roles r on r.key = ur.role_key
    where ur.user_id = p_profile
      and r.rank >= 2
  );
$$;

comment on function public.is_staff_profile(uuid) is
  'TRUE when a profile holds a staff role (moderator/admin/super admin). Used only to render the staff marker (spec §13); it exposes no role details.';

-- Same explicit grant contract as migration 018: PostgreSQL gives every new
-- function EXECUTE to PUBLIC by default, and Campus+ has no anonymous surface.
revoke all on function public.is_staff_profile(uuid) from public, anon;
grant execute on function public.is_staff_profile(uuid) to authenticated, service_role;

-- The projection keeps its block-aware filter and security_invoker behaviour.
-- Recreating a view drops its grants, so the SELECT grant is restored below.
create or replace view public.public_profiles
with (security_invoker = true)
as
select
  p.id,
  p.username,
  p.display_name,
  p.bio,
  case when p.show_branch_year then p.branch else null end as branch,
  case when p.show_branch_year then p.year else null end as year,
  p.reputation_score,
  p.reputation_count,
  p.marketplace_completed_count,
  public.is_active_profile(p.id) as is_active,
  p.created_at,
  -- Appended last on purpose: `create or replace view` cannot reorder columns,
  -- and keeping the existing order means existing readers are unaffected.
  public.is_staff_profile(p.id) as is_staff
from public.profiles p
where p.username is not null
  -- Discovery respects blocks in both directions (spec §14, §60). The raw
  -- `profiles` table stays available so blocking, unblocking and moderation can
  -- still resolve the person involved.
  and not public.is_blocked_with_current(p.id);

comment on view public.public_profiles is
  'Public projection of profiles. Institutional email, auth ids and moderation state are structurally absent. `is_staff` drives the staff marker only.';

grant select on public.public_profiles to authenticated;

-- ==========================================================================
-- FILE 20/79  20261005000020_020_chat_inbox.sql
-- ==========================================================================

-- =============================================================================
-- Campus+ migration 020 — conversation inbox read model
-- =============================================================================
-- The Messages inbox needs, per visible conversation: the newest message (for
-- the preview line) and how many messages are unread since the last read mark,
-- saturated at the same 30-message window the UI has always used.
--
-- Before this function the page fetched the newest 30 messages of *every*
-- conversation (bodies included) just to render one preview line each — about
-- 69 kB per inbox open on the reference data set, and worse as threads grow.
-- The window is a read model, not a product change: an unread badge still
-- saturates at 30, and the preview is still the newest message.
--
-- Security: `security invoker`, so every row is still filtered by the RLS
-- policies on `conversations`, `conversation_members` and `messages` for the
-- calling student — this adds no visibility the student did not already have.
-- =============================================================================

create or replace function public.conversation_inbox(p_limit integer default 30)
returns table (
  id                      uuid,
  kind                    public.conversation_kind,
  title                   text,
  community_id            uuid,
  status                  public.content_status,
  last_message_at         timestamptz,
  created_at              timestamptz,
  is_muted                boolean,
  last_read_at            timestamptz,
  unread                  integer,
  last_message_id         uuid,
  last_message_sender_id  uuid,
  last_message_body       text,
  last_message_gif        jsonb,
  last_message_created_at timestamptz
)
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with mine as (
    select m.conversation_id, m.is_muted, m.last_read_at
    from public.conversation_members m
    where m.user_id = public.current_profile_id()
      and m.status = 'active'
  )
  select
    c.id,
    c.kind,
    c.title,
    c.community_id,
    c.status,
    c.last_message_at,
    c.created_at,
    mine.is_muted,
    mine.last_read_at,
    (
      select count(*)::integer
      from (
        select msg.sender_id, msg.created_at
        from public.messages msg
        where msg.conversation_id = c.id
        order by msg.created_at desc
        limit 30
      ) window_rows
      where window_rows.sender_id <> public.current_profile_id()
        and (mine.last_read_at is null or window_rows.created_at > mine.last_read_at)
    ) as unread,
    latest.id,
    latest.sender_id,
    latest.body,
    latest.gif,
    latest.created_at
  from public.conversations c
  join mine on mine.conversation_id = c.id
  left join lateral (
    select msg.id, msg.sender_id, msg.body, msg.gif, msg.created_at
    from public.messages msg
    where msg.conversation_id = c.id
    order by msg.created_at desc
    limit 1
  ) latest on true
  order by c.last_message_at desc
  limit coalesce(p_limit, 30);
$$;

comment on function public.conversation_inbox(integer) is
  'Inbox read model (RLS-scoped): newest message plus the unread count within the newest 30 messages per visible conversation.';

-- ==========================================================================
-- FILE 21/79  20261005000021_021_marketplace_and_security_fixes.sql
-- ==========================================================================

-- Campus+ migration 021 — marketplace lifecycle fixes + security hardening
-- Supabase CLI filename: 20261005000021_021_marketplace_and_security_fixes.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- This migration fixes two confirmed, root-caused marketplace bugs and closes
-- three small, real gaps the security review found. Nothing here touches RLS
-- in a way that widens access, converts a function away from the security
-- posture it needs to work, or uses the secret key to bypass a policy.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- 1. "Remove listing" silently did nothing, and a resolved listing never
--    actually recorded its buyer.
-- ----------------------------------------------------------------------------
-- guard_listing_update() (migration 008) lets a seller move their own listing
-- between 'active', 'reserved', 'sold' and 'expired' only — any other value is
-- silently reverted to the old status (`new.status := old.status;`), with no
-- error raised. 'removed' was missing from that list, so the "Remove listing"
-- action in the UI ran its UPDATE, got a 200, and the listing stayed exactly
-- as visible as before. This adds 'removed' to the seller-controlled set.
--
-- Separately, this trigger unconditionally reverts `sold_to`/`sold_at` back to
-- their old values for any caller that is not `is_trusted_writer()` or a
-- marketplace moderator. mark_listing_completed() is SECURITY DEFINER so it
-- can legitimately set those two columns on the seller's behalf, but
-- SECURITY DEFINER only changes which role's *table privileges* apply — the
-- session's JWT claims (which is_trusted_writer() reads) are unchanged, so
-- from this trigger's point of view an ordinary seller's resolve looked
-- exactly like a student trying to edit sold_to directly, and it was silently
-- reverted. The result: calling mark_listing_completed() as a regular student
-- always left `sold_to`/`sold_at` untouched even when a buyer was found,
-- regardless of the two bugs fixed below. This now also recognises
-- `in_system_context()` (migration 002's existing marker for "a Campus+
-- definer function is doing privileged work on the user's behalf", already
-- used by prevent_privilege_escalation()) and mark_listing_completed() sets
-- that marker before writing.
-- ----------------------------------------------------------------------------

create or replace function public.guard_listing_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_trusted_writer() then
    new.view_count := (
      select count(*) from public.marketplace_interactions i
      where i.listing_id = old.id and i.kind = 'view'
    );
    new.contact_count := (
      select count(*) from public.marketplace_interactions i
      where i.listing_id = old.id and i.kind = 'contact'
    );
  end if;

  if public.is_trusted_writer() or public.in_system_context()
     or public.has_permission('moderate_marketplace') or public.has_permission('moderate_all') then
    return new;
  end if;
  new.seller_id         := old.seller_id;
  new.category_id       := old.category_id;
  new.is_official       := old.is_official;
  new.moderated_by      := old.moderated_by;
  new.moderated_at      := old.moderated_at;
  new.moderation_reason := old.moderation_reason;
  new.sold_at           := old.sold_at;
  new.sold_to           := old.sold_to;
  -- A seller may only move a listing between the student-controlled states.
  -- 'removed' is the self-service "take this down" state (delete_own_content /
  -- restore_own_content toggle it); a hard delete is a separate RLS-governed
  -- DELETE, not a status transition.
  if new.status is distinct from old.status
     and new.status not in ('active', 'reserved', 'sold', 'expired', 'removed') then
    new.status := old.status;
  end if;
  return new;
end;
$$;

-- ----------------------------------------------------------------------------
-- 2. Generic "Something went wrong" on resolving a listing with no recorded
--    interest.
-- ----------------------------------------------------------------------------
-- mark_listing_completed() raised when it could not infer a buyer (nobody had
-- tapped "I'm interested" first) and the UI's "Mark as sold" button never
-- collects one, so the seller could never resolve such a listing. sold_to is
-- nullable (migration 008: `references profiles(id) on delete set null`) and
-- on_listing_completed() (migration 008) only counts completions — it does not
-- require a buyer — so completing with sold_to = null is safe. The matching
-- fromPostgresError() fix lives in lib/errors.js: it previously had no mapping
-- for the 22023 errcode these business-rule messages use, so this and ~50
-- other deliberately-written, user-safe messages across the app were being
-- swallowed into a generic "internal error" string.
-- ----------------------------------------------------------------------------

create or replace function public.mark_listing_completed(p_listing uuid, p_buyer uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_buyer uuid := p_buyer;
  v_seller uuid;
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  select seller_id into v_seller from public.marketplace_listings where id = p_listing;
  if v_seller is null then
    raise exception 'That listing could not be found.' using errcode = '22023';
  end if;
  if v_seller <> v_me and not public.has_permission('moderate_marketplace') then
    raise exception 'Only the seller can mark a listing as sold.' using errcode = '42501';
  end if;

  if v_buyer is null then
    -- Default to the student who most recently showed interest, if any.
    select i.user_id into v_buyer
    from public.marketplace_interactions i
    where i.listing_id = p_listing and i.kind = 'contact'
    order by i.created_at desc
    limit 1;
  end if;
  -- No interest was ever recorded (e.g. handed off outside the app): complete
  -- the listing without a buyer rather than blocking the seller from ever
  -- resolving it. A buyer is still never allowed to be the seller.
  if v_buyer is not null and v_buyer = v_seller then
    raise exception 'The buyer cannot be the seller.' using errcode = '22023';
  end if;

  -- Mark this as privileged, definer-driven work so guard_listing_update()
  -- lets sold_to/sold_at through for an ordinary seller (see the comment on
  -- guard_listing_update() above). Transaction-local: cleared automatically
  -- once this call's transaction ends.
  perform set_config('campus.system_context', 'on', true);

  update public.marketplace_listings
     set status = 'sold', sold_to = v_buyer, sold_at = now()
   where id = p_listing;

  if v_buyer is not null then
    perform public.notify_user(
      v_buyer, 'marketplace_rating',
      'You can now rate this trade',
      'The seller marked "' || left(coalesce((select title from public.marketplace_listings where id = p_listing), 'a listing'), 80)
        || '" as completed. Leave a rating to help other students.',
      'marketplace_listing', p_listing::text, '/market/listing/' || p_listing::text
    );
  end if;

  perform public.log_audit('marketplace.completed', 'marketplace_listing', p_listing::text,
    jsonb_build_object('buyer_id', v_buyer), false, null, 'private');

  return jsonb_build_object('ok', true, 'buyer_id', v_buyer);
end;
$$;

-- ----------------------------------------------------------------------------
-- 2b. mark_listing_completed() could never finish for an ordinary student.
-- ----------------------------------------------------------------------------
-- Independently of the missing-buyer bug above, log_audit() (migration 006)
-- only allows a non-staff caller to write 'account.%', 'user.%' or
-- 'content.self_%' actions — anything else raises 42501 "You do not have
-- permission to write audit entries." mark_listing_completed() logs
-- 'marketplace.completed', which matches none of those, so the perform
-- public.log_audit(...) call at the end of a successful resolve would ALWAYS
-- fail with that 42501 for a regular student seller (it never surfaced before
-- because every student request hit the missing-buyer 22023 first — a
-- moderator-driven resolve worked, since v_is_staff short-circuits the check,
-- which is why this stayed hidden). 'marketplace.completed' is a self-service
-- action on the caller's own listing, the same category as content.self_*, so
-- it is added to the allowed set rather than loosening the check generally.
-- ----------------------------------------------------------------------------

create or replace function public.log_audit(
  p_action text,
  p_target_type text default null,
  p_target_id text default null,
  p_metadata jsonb default null,
  p_also_moderation boolean default false,
  p_reason text default null,
  p_visibility public.moderation_visibility default 'staff'
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_id uuid;
  v_is_staff boolean;
begin
  if v_actor is null and not public.is_trusted_writer() then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  v_is_staff := public.is_staff() or public.is_trusted_writer();

  -- Non-staff may only record their own account-lifecycle events and a small,
  -- explicit allow-list of other self-service actions, never moderation or
  -- administration entries.
  if not v_is_staff
     and p_action not like 'account.%'
     and p_action not like 'user.%'
     and p_action not like 'content.self_%'
     and p_action <> 'marketplace.completed' then
    raise exception 'You do not have permission to write audit entries.' using errcode = '42501';
  end if;

  insert into public.audit_logs (actor_user_id, action, target_type, target_id, metadata, visibility)
  values (
    v_actor,
    left(p_action, 80),
    left(p_target_type, 60),
    case when p_target_id ~ '^[0-9a-f-]{36}$' then p_target_id::uuid else null end,
    coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object(
      'reason', p_reason,
      'actor_username', (select username from public.profiles where id = v_actor)
    ),
    case when v_is_staff then p_visibility else 'private'::public.moderation_visibility end
  )
  returning id into v_id;

  if p_also_moderation and v_is_staff then
    insert into public.moderation_actions (
      moderator_id, report_id, action, target_type, target_id, note
    ) values (
      v_actor,
      nullif(p_metadata->>'report_id', '')::uuid,
      left(p_action, 60),
      left(p_target_type, 60),
      case when p_target_id ~ '^[0-9a-f-]{36}$' then p_target_id::uuid else null end,
      left(p_reason, 1000)
    );
  end if;

  return v_id;
end;
$$;

comment on function public.log_audit is
  'Append-only audit writer. Students are limited to their own account.* / user.* / content.self_* events plus the marketplace.completed self-service action; moderation entries require staff.';

-- ----------------------------------------------------------------------------
-- 3. conversation_inbox() was callable by anon.
-- ----------------------------------------------------------------------------
-- Migration 020 created this function after migration 018's blanket
-- revoke/grant loop and relied on `alter default privileges` to keep new
-- functions off PUBLIC. That did not take effect for this function, so it
-- kept PostgreSQL's built-in "EXECUTE to PUBLIC" default and `anon` could call
-- it. The function is `security invoker` and every row is still filtered by
-- RLS (an anon caller has no profile, so current_profile_id() is null and the
-- query returns nothing) — there is no data exposure — but an unauthenticated
-- caller should not be able to reach an application RPC at all. Fixed
-- explicitly here rather than re-relying on the default.
-- ----------------------------------------------------------------------------

revoke all on function public.conversation_inbox(integer) from public, anon;
grant execute on function public.conversation_inbox(integer) to authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 4. messages_update_staff allowed `with check (true)`.
-- ----------------------------------------------------------------------------
-- Column privileges already confine every authenticated UPDATE on `messages`
-- to the `body`/`gif` columns (migration 015), so this was never a path to
-- changing `sender_id`, `deleted_at`, etc. But `with check (true)` means a
-- moderator's update is accepted no matter what the row looks like afterwards,
-- so the same re-check used for `using` now also runs for `with check`: the
-- message must still belong to a conversation/message under an active
-- pending/reviewing report after the edit, matching the condition that let
-- the moderator reach the row in the first place.
-- ----------------------------------------------------------------------------

drop policy if exists messages_update_staff on public.messages;
create policy messages_update_staff on public.messages
  for update to authenticated
  using ((public.has_permission('review_reports') or public.has_permission('moderate_all'))
         and exists (select 1 from public.reports r
                     where r.status in ('pending', 'reviewing')
                       and ((r.target_type = 'message' and r.target_id = messages.id)
                            or (r.target_type = 'conversation' and r.target_id = messages.conversation_id))))
  with check ((public.has_permission('review_reports') or public.has_permission('moderate_all'))
         and exists (select 1 from public.reports r
                     where r.status in ('pending', 'reviewing')
                       and ((r.target_type = 'message' and r.target_id = messages.id)
                            or (r.target_type = 'conversation' and r.target_id = messages.conversation_id))));

-- ----------------------------------------------------------------------------
-- 5. Mutable search_path on a handful of helper functions this repo owns.
-- ----------------------------------------------------------------------------
-- Every SECURITY DEFINER function already pins search_path. These few small
-- SECURITY INVOKER helpers predate that convention; pinning them is a
-- metadata-only change (no behavioural difference — none of them reference an
-- unqualified relation) that silences the Advisor's "Function Search Path
-- Mutable" lint for the functions this project actually authored. The
-- remaining functions the lint can flag (pgcrypto, pg_trgm) are vendored
-- extension functions installed into `public`; they are intentionally left
-- alone — the fix for those is moving extensions to a dedicated schema, which
-- is a deploy-time decision for whoever owns the Supabase project, not a
-- migration that should be forced through here.
-- ----------------------------------------------------------------------------

alter function public.touch_updated_at() set search_path = public, pg_temp;
alter function public.request_claims() set search_path = public, pg_temp;
alter function public.jwt_role() set search_path = public, pg_temp;
alter function public.jwt_sub() set search_path = public, pg_temp;
alter function public.is_trusted_writer() set search_path = public, pg_temp;
alter function public.in_system_context() set search_path = public, pg_temp;
alter function public.safe_uuid(text) set search_path = public, pg_temp;
alter function public.content_moderation_permission(text) set search_path = public, pg_temp;

-- ----------------------------------------------------------------------------
-- Note on random_session_view / random_messages_view (not changed here)
-- ----------------------------------------------------------------------------
-- These two views are intentionally NOT `security_invoker`. random_sessions,
-- random_session_participants and random_messages have no participant-facing
-- SELECT policy on purpose (migration 010: "No participant policies on
-- purpose: participants read random_session_state() and random_session_view,
-- which contain no identities.") — the views themselves do the privacy
-- filtering (`p.user_id = current_profile_id()`) and intentionally run with
-- the view owner's privileges to assemble that projection across both
-- participants' rows. Setting `security_invoker = true` would make the views
-- subject to RLS as the calling student, who has no SELECT policy on the
-- underlying tables at all — every participant would get zero rows and
-- Random Chat's message/session reads would break outright. This is kept as
-- designed; the earlier assumption that these views already had
-- `security_invoker = true` set does not match the migration history and the
-- correct fix is not to add it.

-- ==========================================================================
-- FILE 22/79  20261005000022_022_random_views_invoker_fix.sql
-- ==========================================================================

-- Campus+ migration 022 — restore random_session_view / random_messages_view
-- Supabase CLI filename: 20261005000022_022_random_views_invoker_fix.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- These two views were reported as having been manually switched to
-- `security_invoker = true` directly against a live project during an earlier
-- debugging session (outside of this migration history, so no prior migration
-- file shows it). This migration verifies that claim against real behaviour
-- and, since it is correct, restores the configuration the application
-- actually requires — explicitly, so a future "harden this view" pass does
-- not flip it back without re-reading this comment.
--
-- Verified empirically (not by inspection alone) against a disposable
-- Postgres instance with every migration through 021 applied and real
-- session/message rows:
--
--   default view (security definer semantics, as migration 010 created it):
--     a participant querying random_session_view / random_messages_view for
--     their own session sees their session row and their message — correct.
--
--   same query, same data, with `security_invoker = true` set on both views:
--     the same participant gets ZERO rows back from both views.
--
-- Why: random_sessions, random_session_participants and random_messages have
-- NO participant-facing SELECT policy at all — migration 010 says so in so
-- many words ("No participant policies on purpose: participants read
-- random_session_state() and random_session_view, which contain no
-- identities."). Access control for a participant's own session is enforced
-- by the view body (`p.user_id = current_profile_id()`) and by
-- random_session_state()'s own has_permission/ownership check, not by RLS on
-- the base tables — participant RLS was deliberately never built for these
-- tables. `security_invoker = true` makes a view subject to RLS as the
-- calling role; with no participant policy to pass, every participant query
-- returns nothing. Staff (who do have a `view_random_sessions`-gated SELECT
-- policy on the base tables) would not notice this change — the lobby and
-- message list silently stop working for every real participant, while admin
-- testing still looks fine. That matches a change that can go unnoticed.
--
-- lib/actions/random.js confirms the application depends on exactly this
-- definer behaviour: it queries `random_session_view` / `random_messages_view`
-- directly with no extra ownership filter, trusting the view to scope the
-- rows to the caller. (The `/random` UI route that called these actions was
-- since removed — see migration 023 — but the actions module and this view
-- behaviour are both kept, unreferenced, per the same retention decision.)
--
-- This does not weaken RLS: RLS stays enabled and unchanged on every base
-- table. It restores two views to the access-control design they were built
-- with, which is documented, narrow (no identity columns, no cross-session
-- reads) and already audited (`npm run audit:db` — "Definer views are limited
-- to the two audited Random projections").
-- =============================================================================

alter view public.random_session_view set (security_invoker = false);
alter view public.random_messages_view set (security_invoker = false);

comment on view public.random_session_view is
  'Participant-safe session projection: no participant ids, no usernames, no profile data. '
  'Deliberately NOT security_invoker — see migration 022. The base tables have no participant '
  'SELECT policy on purpose; this view''s own `p.user_id = current_profile_id()` filter is the '
  'access control. Do not add security_invoker to this view without also adding participant-safe '
  'RLS policies to random_sessions and random_session_participants, or every participant query '
  'will silently return zero rows.';

comment on view public.random_messages_view is
  'Participant-safe message stream. `sender_user_id` is mapped to a boolean `mine` flag so the '
  'other student cannot be identified. Deliberately NOT security_invoker — see migration 022; the '
  'same reasoning as random_session_view applies, since random_messages has no participant SELECT '
  'policy either.';

-- ==========================================================================
-- FILE 23/79  20261005000023_023_random_chat_flag_retired.sql
-- ==========================================================================

-- 023: Random Chat removed from the UI — reflect it in the feature flag.
--
-- Random Chat has no nav link, no /random route and no composer anywhere in
-- the app (see lib/constants.js FEATURE_FLAGS for the full rationale). This
-- migration only flips the admin-visible `feature_flags` row so staff see an
-- accurate state in the Admin > Feature flags panel; it is a one-row UPDATE,
-- not a deletion:
--   - random_sessions, random_session_participants, random_messages and their
--     views/functions/RLS policies are all left exactly as they are;
--   - the `use_random_chat`, `moderate_random` and `view_random_sessions`
--     permissions are untouched — moderators still need them to review
--     reports already filed against past sessions;
--   - the moderator "Random reports" queue keeps working against existing data.
-- Nothing in the application currently reads this flag to gate anything (the
-- /random page checked the `use_random_chat` permission directly and no
-- longer exists at all), so this update has no functional effect beyond the
-- admin panel's own display — it exists purely so the control panel doesn't
-- claim a retired feature is still enabled.

update public.feature_flags
set
  label = 'Random (retired — no UI entry point)',
  description = 'Anonymous paired conversations between verified students. Removed from navigation; data and moderation tools are retained.',
  enabled = false
where key = 'random_chat';

-- ==========================================================================
-- FILE 24/79  20261005000024_024_study_partners_and_discovery.sql
-- ==========================================================================

-- Campus+ migration 024 — study partners and discovery
-- Supabase CLI filename: 20261005000024_024_study_partners_and_discovery.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 024 — study partner finder, event submissions, discovery categories
-- =============================================================================
-- Additive only: one new table, two nullable category columns, two new
-- permissions, one feature flag, two RLS policies for student event
-- submissions, and an extended global_search(). No existing object is
-- redefined except global_search(), which keeps its signature.
--
--   Study Partner Finder — explicit opt-in requests. Coarse availability
--     categories only; no calendars, no locations, no presence. Closed and
--     expired requests never appear as active.
--   Events — student submissions land as non-official drafts for staff review;
--     a submission can never publish itself or appear official.
--   Opportunities — nullable discovery category; no workflow change.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- Permissions (mirror lib/constants.js PERMISSIONS + DEFAULT_STUDENT_PERMISSIONS)
-- ----------------------------------------------------------------------------

insert into public.permissions (key, label, description, group_name) values
  ('create_study_posts', 'Create study partner posts', 'Publish opt-in study partner requests.', 'Campus'),
  ('submit_events', 'Submit events', 'Submit community events for staff review (never published as official).', 'Campus')
on conflict (key) do update
  set label = excluded.label, description = excluded.description, group_name = excluded.group_name;

-- Every baseline role holds the student baseline, so all four gain the two keys.
insert into public.role_permissions (role_key, permission_key)
select r.key, p.key
from (values ('student'), ('moderator'), ('admin'), ('super_admin')) as r(key)
cross join (values ('create_study_posts'), ('submit_events')) as p(key)
on conflict do nothing;

-- ----------------------------------------------------------------------------
-- Feature flag (mirrors lib/constants.js FEATURE_FLAGS)
-- ----------------------------------------------------------------------------

insert into public.feature_flags (key, label, description, group_name, enabled) values
  ('study_partners', 'Study partner finder', 'Opt-in subject/exam study requests.', 'campus', true)
on conflict (key) do nothing;

-- ----------------------------------------------------------------------------
-- study_partner_posts — opt-in study requests (separate from team finder)
-- ----------------------------------------------------------------------------

create table public.study_partner_posts (
  id               uuid primary key default gen_random_uuid(),
  title            text not null check (length(btrim(title)) between 3 and 140),
  description      text not null check (length(btrim(description)) between 10 and 1500),
  subject          text not null check (length(btrim(subject)) between 2 and 120),
  purpose          text not null check (purpose in ('subject_study', 'exam_prep', 'collaboration')),
  branch           text check (branch is null or length(branch) <= 80),
  year             text check (year is null or length(year) <= 40),
  academic_context text check (academic_context is null or length(academic_context) <= 200),
  mode             text not null default 'either' check (mode in ('oncampus', 'online', 'either')),
  availability     text[] not null default '{}'
    check (availability <@ array['weekday_morning', 'weekday_afternoon', 'weekday_evening', 'weekend', 'flexible']),
  expires_on       date,
  closed_at        timestamptz,
  status           public.content_status not null default 'published',
  creator_id       uuid not null references public.profiles (id) on delete cascade,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  search_vector    tsvector generated always as (
    to_tsvector('english'::regconfig, coalesce(title, '') || ' ' || coalesce(description, '') || ' ' || coalesce(subject, ''))
  ) stored
);

create index study_partner_posts_status_idx on public.study_partner_posts (status, created_at desc);
create index study_partner_posts_active_idx on public.study_partner_posts (created_at desc)
  where status = 'published' and closed_at is null;
create index study_partner_posts_creator_idx on public.study_partner_posts (creator_id, created_at desc);
create index study_partner_posts_subject_idx on public.study_partner_posts (subject);
create index study_partner_posts_filters_idx on public.study_partner_posts (purpose, mode);
create index study_partner_posts_search_idx on public.study_partner_posts using gin (search_vector);

create trigger study_partner_posts_touch before update on public.study_partner_posts
  for each row execute function public.touch_updated_at();

alter table public.study_partner_posts enable row level security;

-- Active = published, not closed by the creator, not expired, creator in good
-- standing and not blocked either way. Participation is opt-in: only rows a
-- student explicitly published are ever visible to others.
create policy study_posts_select_visible on public.study_partner_posts
  for select to authenticated
  using (
    status = 'published'
    and closed_at is null
    and (expires_on is null or expires_on >= CURRENT_DATE)
    and public.is_active_profile(creator_id)
    and not public.is_blocked_with_current(creator_id)
  );
create policy study_posts_select_own on public.study_partner_posts
  for select to authenticated using (creator_id = public.current_profile_id());
create policy study_posts_select_staff on public.study_partner_posts
  for select to authenticated using (public.has_permission('moderate_all'));
create policy study_posts_insert_own on public.study_partner_posts
  for insert to authenticated
  with check (
    creator_id = public.current_profile_id()
    and public.is_active_user()
    and public.has_permission('create_study_posts')
    and status = 'published'
    and closed_at is null
  );
create policy study_posts_update_own on public.study_partner_posts
  for update to authenticated
  using (creator_id = public.current_profile_id())
  with check (creator_id = public.current_profile_id());
create policy study_posts_update_staff on public.study_partner_posts
  for update to authenticated
  using (public.has_permission('moderate_all'))
  with check (public.has_permission('moderate_all'));
create policy study_posts_delete_own on public.study_partner_posts
  for delete to authenticated using (creator_id = public.current_profile_id());

revoke all on public.study_partner_posts from anon;

-- Column privileges mirror migration 015: narrow UPDATE to editable columns.
revoke update on public.study_partner_posts from authenticated, anon;
grant update (title, description, subject, purpose, branch, year, academic_context,
              mode, availability, expires_on, closed_at, status)
  on public.study_partner_posts to authenticated;

-- ----------------------------------------------------------------------------
-- Discovery categories (nullable, additive — existing rows read as uncategorised)
-- ----------------------------------------------------------------------------

alter table public.events
  add column if not exists category text
    check (category is null or category in
      ('academic', 'cultural', 'sports', 'technical', 'workshop', 'club', 'placement', 'other'));

create index if not exists events_category_idx on public.events (category)
  where status = 'published';

-- Staff manage events through direct updates (migration 015 narrowed UPDATE to
-- an explicit column list), so the new column must be granted to be editable.
grant update (category) on public.events to authenticated;

alter table public.opportunities
  add column if not exists category text
    check (category is null or category in
      ('internship', 'program', 'hackathon', 'competition', 'scholarship',
       'collaboration', 'club_recruitment', 'gig', 'other'));

create index if not exists opportunities_category_idx on public.opportunities (category);

grant update (category) on public.opportunities to authenticated;

-- ----------------------------------------------------------------------------
-- Student event submissions: non-official drafts, staff review, owner withdrawal
-- ----------------------------------------------------------------------------

-- A student submission is always a draft and never official. Publishing stays
-- staff-only through the existing events_update_staff policy.
create policy events_insert_community on public.events
  for insert to authenticated
  with check (
    public.has_permission('submit_events')
    and public.is_active_user()
    and is_official = false
    and status = 'draft'
    and created_by = public.current_profile_id()
  );

-- Submitters can track their own pending drafts; everyone else sees published
-- events (events_select_published) and staff see everything (events_select_staff).
create policy events_select_own on public.events
  for select to authenticated using (created_by = public.current_profile_id());

-- A submitter may withdraw their own unreviewed draft. Anything published is
-- staff-managed history and cannot be deleted by its submitter.
create policy events_delete_own_draft on public.events
  for delete to authenticated
  using (created_by = public.current_profile_id() and status = 'draft' and is_official = false);

-- ----------------------------------------------------------------------------
-- Global search: study & teams scope (signature unchanged)
-- ----------------------------------------------------------------------------

create or replace function public.global_search(
  p_query text,
  p_scope text default 'all',
  p_limit integer default 20,
  p_offset integer default 0
)
returns table (
  scope text,
  id uuid,
  title text,
  subtitle text,
  snippet text,
  url text,
  meta jsonb,
  rank real
)
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
with params as (
  select
    nullif(btrim(coalesce(p_query, '')), '') as q,
    least(greatest(coalesce(p_limit, 20), 1), 50) as lim,
    greatest(coalesce(p_offset, 0), 0) as off,
    coalesce(p_scope, 'all') as scope
),
needle as (
  select
    q,
    lim,
    off,
    scope,
    '%' || replace(replace(q, '%', '\\%'), '_', '\\_') || '%' as like_q,
    websearch_to_tsquery('english', q) as tsq
  from params
  where q is not null and length(q) >= 2
)
select * from (
(
  -- people ------------------------------------------------------------------
  select
    'people'::text as scope,
    p.id,
    p.username as title,
    coalesce(nullif(p.display_name, ''), '@' || p.username) as subtitle,
    coalesce(p.bio, '') as snippet,
    '/user/' || p.username as url,
    jsonb_build_object(
      'branch', case when p.show_branch_year then p.branch else null end,
      'year', case when p.show_branch_year then p.year else null end,
      'reputation_score', p.reputation_score
    ) as meta,
    greatest(
      similarity(p.username, n.q),
      similarity(coalesce(p.display_name, ''), n.q) * 0.8
    )::real as rank
  from public.profiles p, needle n
  where n.scope in ('all', 'people')
    and public.is_active_profile(p.id)
    and not public.is_blocked_with_current(p.id)
    and (p.username ilike n.like_q or p.display_name ilike n.like_q)
  order by rank desc
  limit (select lim from params)
  )
  union all
(
  -- posts & discussions -----------------------------------------------------
  select
    case when po.kind = 'discussion' then 'discussions' else 'posts' end,
    po.id,
    coalesce(po.title, nullif(left(po.body, 80), '')),
    '@' || pr.username,
    left(po.body, 200),
    '/post/' || po.id::text,
    jsonb_build_object(
      'kind', po.kind,
      'is_official', po.is_official,
      'created_at', po.created_at,
      'reaction_count', po.reaction_count,
      'comment_count', po.comment_count
    ),
    ts_rank(po.search_vector, n.tsq)
  from public.posts po
  join public.profiles pr on pr.id = po.author_id
  cross join needle n
  where n.scope in ('all', 'posts', 'discussions')
    and (n.scope <> 'discussions' or po.kind = 'discussion')
    and po.status = 'published'
    and po.deleted_at is null
    and (po.search_vector @@ n.tsq or po.body ilike n.like_q or coalesce(po.title, '') ilike n.like_q)
  )
  union all
(
  -- communities / study groups / clubs --------------------------------------
  select
    case c.kind
      when 'study_group' then 'communities'
      when 'club' then 'clubs'
      else 'communities'
    end,
    c.id,
    c.name,
    case c.kind when 'club' then 'Club' when 'study_group' then 'Study group' else 'Community' end,
    left(c.description, 200),
    case c.kind
      when 'club' then '/campus/clubs/' || c.id::text
      else '/communities/' || c.slug
    end,
    jsonb_build_object('kind', c.kind, 'member_count', c.member_count, 'visibility', c.visibility),
    ts_rank(to_tsvector('english', c.name || ' ' || c.description), n.tsq)
  from public.communities c
  cross join needle n
  where n.scope in ('all', 'communities', 'clubs')
    and (n.scope <> 'clubs' or c.kind = 'club')
    and c.status = 'published'
    and public.can_view_community(c.id)
    and (c.name ilike n.like_q or c.description ilike n.like_q)
  )
  union all
(
  -- marketplace listings ----------------------------------------------------
  select
    'marketplace',
    l.id,
    l.title,
    case when l.is_free then 'Free' else '₹' || coalesce(l.price, 0)::text end,
    left(l.description, 200),
    '/market/listing/' || l.id::text,
    jsonb_build_object('price', l.price, 'is_free', l.is_free, 'condition', l.condition, 'status', l.status),
    ts_rank(l.search_vector, n.tsq)
  from public.marketplace_listings l
  cross join needle n
  where n.scope in ('all', 'marketplace')
    and l.status in ('active', 'reserved')
    and public.feature_enabled('marketplace')
    and (l.search_vector @@ n.tsq or l.title ilike n.like_q)
  )
  union all
(
  -- gigs --------------------------------------------------------------------
  select
    'marketplace',
    g.id,
    g.title,
    'Gig · ' || g.category,
    left(g.description, 200),
    '/market/gigs/' || g.id::text,
    jsonb_build_object('kind', 'gig', 'compensation', g.compensation),
    ts_rank(g.search_vector, n.tsq)
  from public.gigs g
  cross join needle n
  where n.scope in ('all', 'marketplace')
    and g.status = 'published'
    and public.feature_enabled('gigs')
    and (g.search_vector @@ n.tsq or g.title ilike n.like_q)
  )
  union all
(
  -- events ------------------------------------------------------------------
  select
    'events',
    e.id,
    e.title,
    'Event · ' || to_char(e.starts_on, 'DD Mon YYYY'),
    left(e.description, 200),
    '/campus/events/' || e.id::text,
    jsonb_build_object('starts_on', e.starts_on, 'location', e.location),
    ts_rank(e.search_vector, n.tsq)
  from public.events e
  cross join needle n
  where n.scope in ('all', 'events')
    and e.status = 'published'
    and public.feature_enabled('events')
    and (e.search_vector @@ n.tsq or e.title ilike n.like_q)
  )
  union all
(
  -- resources ---------------------------------------------------------------
  select
    'resources',
    r.id,
    r.title,
    coalesce(r.subject, '') || case when r.is_official then ' · Official' else ' · Community' end,
    left(r.description, 200),
    '/explore/resources/' || r.id::text,
    jsonb_build_object('type', r.type, 'is_official', r.is_official),
    ts_rank(r.search_vector, n.tsq)
  from public.official_resources r
  cross join needle n
  where n.scope in ('all', 'resources')
    and r.status = 'published'
    and (r.search_vector @@ n.tsq or r.title ilike n.like_q)
  )
  union all
(
  -- opportunities -----------------------------------------------------------
  select
    'opportunities',
    o.id,
    o.title,
    o.organization || case when o.source = 'official' then ' · Official' else ' · Community' end,
    left(o.description, 200),
    '/explore/opportunities/' || o.id::text,
    jsonb_build_object('deadline', o.deadline, 'mode', o.mode, 'source', o.source),
    ts_rank(o.search_vector, n.tsq)
  from public.opportunities o
  cross join needle n
  where n.scope in ('all', 'opportunities')
    and o.status = 'published'
    and (o.search_vector @@ n.tsq or o.title ilike n.like_q)
  )
  union all
(
  -- projects ----------------------------------------------------------------
  select
    'projects',
    pr.id,
    pr.title,
    pr.technologies,
    left(pr.description, 200),
    '/explore/projects/' || pr.id::text,
    jsonb_build_object('reaction_count', pr.reaction_count),
    ts_rank(pr.search_vector, n.tsq)
  from public.projects pr
  cross join needle n
  where n.scope in ('all', 'projects')
    and pr.status = 'published'
    and (pr.search_vector @@ n.tsq or pr.title ilike n.like_q)
  )
  union all
(
  -- study partner posts (opt-in requests only; closed/expired never match) --
  select
    'study',
    s.id,
    s.title,
    s.subject || ' · ' || case s.purpose
      when 'subject_study' then 'Subject study'
      when 'exam_prep' then 'Exam prep'
      else 'Collaboration'
    end,
    left(s.description, 200),
    '/campus/study/' || s.id::text,
    jsonb_build_object('purpose', s.purpose, 'mode', s.mode, 'subject', s.subject, 'kind', 'study_post'),
    ts_rank(s.search_vector, n.tsq)
  from public.study_partner_posts s
  cross join needle n
  where n.scope in ('all', 'study')
    and s.status = 'published'
    and s.closed_at is null
    and (s.expires_on is null or s.expires_on >= CURRENT_DATE)
    and public.feature_enabled('study_partners')
    and (s.search_vector @@ n.tsq or s.title ilike n.like_q or s.subject ilike n.like_q)
  )
  union all
(
  -- team finder posts ---------------------------------------------------------
  select
    'study',
    t.id,
    t.project_name,
    'Team finder · ' || left(t.required_skills, 60),
    left(t.description, 200),
    '/campus/teams',
    jsonb_build_object('kind', 'team_post'),
    ts_rank(t.search_vector, n.tsq)
  from public.team_posts t
  cross join needle n
  where n.scope in ('all', 'study')
    and t.status = 'published'
    and public.feature_enabled('team_finder')
    and (t.search_vector @@ n.tsq or t.project_name ilike n.like_q)
  )
) results
order by rank desc, title asc
limit (select lim from params)
offset (select off from params);
$$;

comment on function public.global_search(text, text, integer, integer) is
  'Conventional PostgreSQL search across public entities. SECURITY INVOKER so RLS enforces blocks, visibility and privacy.';

-- ==========================================================================
-- FILE 25/79  20261005000025_025_gigs_and_clubs.sql
-- ==========================================================================

-- Campus+ migration 025 — dedicated gigs and clubs
-- Supabase CLI filename: 20261005000025_025_gigs_and_clubs.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 025 — the Gigs and Clubs sections get the fields their screens need
-- =============================================================================
-- Additive only. No table is rebuilt, no row is rewritten and no existing
-- policy is narrowed:
--
--   Gigs — a lifecycle (`gig_state`: open / closed / completed) that is
--     independent of moderation (`content_status`), the fields the dedicated
--     posting form collects (skills, paid or unpaid, deadline, application
--     contact), and one `gig_applications` table so "apply" is a real,
--     auditable interaction instead of an off-platform DM.
--     `content_status` keeps its meaning: published / hidden / removed /
--     deleted is what moderators control. `state` is what the poster controls.
--
--   Clubs — a nullable `club_category` on `communities` (Technical, Cultural,
--     Sports, Arts, Entrepreneurship, Social). Clubs stay rows in
--     `communities` (kind = 'club'); membership, joins, chat, join requests and
--     posts are reused unchanged. One guard is added so a non-staff writer can
--     never mint an "Official" club, and staff-created clubs record who
--     approved them.
--
-- Existing gigs default to state = 'open', payment_type = 'unpaid' and an empty
-- skills array, which is exactly how they behaved before this migration.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- Gigs — lifecycle and the fields the gig form collects
-- ----------------------------------------------------------------------------

create type public.gig_state as enum ('open', 'closed', 'completed');

alter table public.gigs
  add column state           public.gig_state not null default 'open',
  add column skills          text[] not null default '{}'::text[],
  add column payment_type    text not null default 'unpaid',
  add column deadline        date,
  add column contact_details text;

alter table public.gigs
  add constraint gigs_payment_type_check
    check (payment_type in ('paid', 'unpaid')),
  add constraint gigs_skills_count_check
    check (cardinality(skills) <= 12),
  add constraint gigs_skills_text_check
    check (length(array_to_string(skills, ' ')) <= 480),
  add constraint gigs_contact_details_check
    check (contact_details is null or length(btrim(contact_details)) <= 300);

comment on column public.gigs.state is
  'Poster-controlled lifecycle: open (accepting applications), closed (no longer accepting) or completed. Moderation stays in status.';
comment on column public.gigs.payment_type is
  'paid or unpaid. compensation carries the human-readable amount/rate.';
comment on column public.gigs.skills is
  'Up to 12 required-skill labels; filtered with the array containment operator.';

create index gigs_state_idx on public.gigs (state, created_at desc);
create index gigs_skills_idx on public.gigs using gin (skills);

-- A gig past its deadline is no longer accepting applications. The row keeps
-- state = 'open' until its owner closes it; this index makes the "closing soon"
-- ordering on /gigs cheap.
create index gigs_deadline_idx on public.gigs (deadline) where deadline is not null;

-- ----------------------------------------------------------------------------
-- gig_applications — one row per student per gig
-- ----------------------------------------------------------------------------

create type public.gig_application_status as enum ('pending', 'accepted', 'declined', 'withdrawn');

create table public.gig_applications (
  id           uuid primary key default gen_random_uuid(),
  gig_id       uuid not null references public.gigs (id) on delete cascade,
  applicant_id uuid not null references public.profiles (id) on delete cascade,
  message      text not null check (length(btrim(message)) between 5 and 1000),
  status       public.gig_application_status not null default 'pending',
  decided_by   uuid references public.profiles (id) on delete set null,
  decided_at   timestamptz,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  unique (gig_id, applicant_id)
);

create index gig_applications_gig_idx on public.gig_applications (gig_id, created_at desc);
create index gig_applications_applicant_idx on public.gig_applications (applicant_id, created_at desc);

comment on table public.gig_applications is
  'Applications to a student gig. A student applies once; the gig owner accepts or declines; the applicant can withdraw. Contact still happens through DMs.';

create trigger gig_applications_touch before update on public.gig_applications
  for each row execute function public.touch_updated_at();

-- Defence in depth: RLS already limits who may update a row, but a gig owner
-- must not be able to rewrite the applicant's words, and an applicant must not
-- be able to accept themselves.
create or replace function public.guard_gig_application_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_owner uuid;
begin
  if public.is_trusted_writer() then
    return new;
  end if;

  select g.creator_id into v_owner from public.gigs g where g.id = old.gig_id;

  new.gig_id := old.gig_id;
  new.applicant_id := old.applicant_id;
  new.message := old.message;
  new.created_at := old.created_at;

  if v_owner = public.current_profile_id() then
    -- The owner only decides, from pending, and only for themselves.
    if new.status not in ('accepted', 'declined') then
      raise exception 'A gig owner can only accept or decline an application.'
        using errcode = '42501';
    end if;
    if old.status <> 'pending' then
      raise exception 'That application has already been decided.' using errcode = '42501';
    end if;
    new.decided_by := public.current_profile_id();
    new.decided_at := coalesce(new.decided_at, now());
  else
    -- Everyone else is the applicant: the only allowed change is withdrawing.
    if new.status <> 'withdrawn' then
      raise exception 'An applicant can only withdraw an application.' using errcode = '42501';
    end if;
    if old.status not in ('pending', 'accepted') then
      raise exception 'That application can no longer be withdrawn.' using errcode = '42501';
    end if;
    new.decided_by := old.decided_by;
    new.decided_at := old.decided_at;
  end if;

  return new;
end;
$$;

create trigger gig_applications_guard
  before update on public.gig_applications
  for each row execute function public.guard_gig_application_update();

alter table public.gig_applications enable row level security;

-- The applicant always sees their own application; the gig owner sees the
-- applications for their gigs; staff see everything.
create policy gig_applications_select_own on public.gig_applications
  for select to authenticated
  using (applicant_id = public.current_profile_id());

create policy gig_applications_select_owner on public.gig_applications
  for select to authenticated
  using (
    exists (
      select 1 from public.gigs g
      where g.id = gig_id and g.creator_id = public.current_profile_id()
    )
  );

create policy gig_applications_select_staff on public.gig_applications
  for select to authenticated
  using (public.has_permission('moderate_marketplace') or public.has_permission('moderate_all'));

-- Apply: an active student, once, to a published and open gig that is not
-- their own and whose owner has not blocked them.
create policy gig_applications_insert_own on public.gig_applications
  for insert to authenticated
  with check (
    applicant_id = public.current_profile_id()
    and public.is_active_user()
    and status = 'pending'
    and exists (
      select 1 from public.gigs g
      where g.id = gig_id
        and g.status = 'published'
        and g.state = 'open'
        and g.creator_id <> public.current_profile_id()
        and not public.is_blocked_with_current(g.creator_id)
    )
  );

create policy gig_applications_withdraw_own on public.gig_applications
  for update to authenticated
  using (applicant_id = public.current_profile_id() and status in ('pending', 'accepted'))
  with check (applicant_id = public.current_profile_id() and status = 'withdrawn');

create policy gig_applications_decide_owner on public.gig_applications
  for update to authenticated
  using (
    status = 'pending'
    and exists (
      select 1 from public.gigs g
      where g.id = gig_id and g.creator_id = public.current_profile_id()
    )
  )
  with check (
    status in ('accepted', 'declined')
    and decided_by = public.current_profile_id()
  );

create policy gig_applications_update_staff on public.gig_applications
  for update to authenticated
  using (public.has_permission('moderate_marketplace') or public.has_permission('moderate_all'))
  with check (public.has_permission('moderate_marketplace') or public.has_permission('moderate_all'));

-- A student may delete their own application (an alternative to withdrawing).
create policy gig_applications_delete_own on public.gig_applications
  for delete to authenticated using (applicant_id = public.current_profile_id());

-- ----------------------------------------------------------------------------
-- Clubs — category on the shared communities table
-- ----------------------------------------------------------------------------

alter table public.communities
  add column club_category text;

alter table public.communities
  add constraint communities_club_category_check
  check (
    club_category is null
    or (kind = 'club' and club_category in ('Technical', 'Cultural', 'Sports', 'Arts', 'Entrepreneurship', 'Social'))
  );

comment on column public.communities.club_category is
  'Discovery category for kind = club. Null for communities and study groups.';

create index communities_club_category_idx
  on public.communities (club_category)
  where kind = 'club';

-- ----------------------------------------------------------------------------
-- Official clubs are staff-created, and say who approved them
-- ----------------------------------------------------------------------------
-- `communities_insert_own` lets a writer with the right kind permission create
-- a row, but nothing used to stop a non-staff writer from setting
-- is_official = true on that insert. This guard closes that hole for every
-- kind without changing any existing policy.
create or replace function public.guard_community_insert()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if public.is_trusted_writer() then
    return new;
  end if;

  if new.is_official then
    if not (
      public.has_permission('manage_clubs')
      or public.has_permission('manage_official_content')
      or public.has_permission('moderate_all')
    ) then
      raise exception 'Only campus staff can publish official content.'
        using errcode = '42501';
    end if;
    new.approved_by := coalesce(new.approved_by, public.current_profile_id());
    new.approved_at := coalesce(new.approved_at, now());
  else
    new.approved_by := null;
    new.approved_at := null;
  end if;

  return new;
end;
$$;

create trigger communities_guard_insert
  before insert on public.communities
  for each row execute function public.guard_community_insert();

-- ----------------------------------------------------------------------------
-- Column privileges for the new fields
-- ----------------------------------------------------------------------------
-- Migration 015 restricts which columns an authenticated writer may update.
-- The gig lifecycle fields and the club category are owner-managed, so they
-- join that allow-list; everything else on `gigs` stays readonly to clients.
grant update (state, skills, payment_type, deadline, contact_details)
  on public.gigs to authenticated;

grant update (club_category)
  on public.communities to authenticated;

-- ==========================================================================
-- FILE 26/79  20261024000001_026_messaging_live_read_model.sql
-- ==========================================================================

-- =============================================================================
-- Campus+ migration 026 — exact unread state for live messaging
-- =============================================================================
-- No new tables or client-writable columns. The navigation badge and reconnect
-- path need the caller's per-conversation read position and exact unread count,
-- including counts above the old 30-message presentation window. Both functions
-- remain SECURITY INVOKER: conversation, membership, message, block and account
-- visibility continue to be decided by the existing RLS policies.
-- Existing index used by both reads: messages_conversation_idx
-- (conversation_id, created_at DESC).
-- =============================================================================

create or replace function public.conversation_inbox(p_limit integer default 30)
returns table (
  id                      uuid,
  kind                    public.conversation_kind,
  title                   text,
  community_id            uuid,
  status                  public.content_status,
  last_message_at         timestamptz,
  created_at              timestamptz,
  is_muted                boolean,
  last_read_at            timestamptz,
  unread                  integer,
  last_message_id         uuid,
  last_message_sender_id  uuid,
  last_message_body       text,
  last_message_gif        jsonb,
  last_message_created_at timestamptz
)
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with mine as (
    select m.conversation_id, m.is_muted, m.last_read_at
    from public.conversation_members m
    where m.user_id = public.current_profile_id()
      and m.status = 'active'
  )
  select
    c.id,
    c.kind,
    c.title,
    c.community_id,
    c.status,
    c.last_message_at,
    c.created_at,
    mine.is_muted,
    mine.last_read_at,
    (
      select count(*)::integer
      from public.messages msg
      where msg.conversation_id = c.id
        and msg.sender_id <> public.current_profile_id()
        and (mine.last_read_at is null or msg.created_at > mine.last_read_at)
    ) as unread,
    latest.id,
    latest.sender_id,
    latest.body,
    latest.gif,
    latest.created_at
  from public.conversations c
  join mine on mine.conversation_id = c.id
  left join lateral (
    select msg.id, msg.sender_id, msg.body, msg.gif, msg.created_at
    from public.messages msg
    where msg.conversation_id = c.id
    order by msg.created_at desc
    limit 1
  ) latest on true
  order by c.last_message_at desc
  limit coalesce(p_limit, 30);
$$;

comment on function public.conversation_inbox(integer) is
  'RLS-scoped inbox: newest message preview and exact unread count per visible conversation.';

/** A small shell snapshot: no message bodies, member lists, or profile joins. */
create or replace function public.messaging_unread_counts()
returns table (
  conversation_id uuid,
  last_read_at    timestamptz,
  unread_count    integer
)
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  select
    mine.conversation_id,
    mine.last_read_at,
    (
      select count(*)::integer
      from public.messages msg
      where msg.conversation_id = mine.conversation_id
        and msg.sender_id <> public.current_profile_id()
        and (mine.last_read_at is null or msg.created_at > mine.last_read_at)
    ) as unread_count
  from public.conversation_members mine
  join public.conversations c on c.id = mine.conversation_id
  where mine.user_id = public.current_profile_id()
    and mine.status = 'active'
  order by mine.conversation_id;
$$;

comment on function public.messaging_unread_counts() is
  'RLS-scoped exact unread counts and read positions for the signed-in member; used by the private navigation badge and reconnect sync.';

revoke all on function public.conversation_inbox(integer) from public, anon;
grant execute on function public.conversation_inbox(integer) to authenticated, service_role;
revoke all on function public.messaging_unread_counts() from public, anon;
grant execute on function public.messaging_unread_counts() to authenticated, service_role;

-- ==========================================================================
-- FILE 27/79  20261025000001_027_backup_change_capture.sql
-- ==========================================================================

-- =============================================================================
-- Campus+ migration 027 — asynchronous Google Drive backup (database half)
-- =============================================================================
-- Supabase Postgres remains the ONE primary database. Nothing here and nothing
-- in the application ever calls Google Drive while serving a student request.
--
-- What lands in this migration:
--   1. `public.backup_change_log` — a durable transactional outbox. A row is
--      inserted by an AFTER ROW trigger *in the same transaction* as the
--      application write. Inserts, updates and deletes are all captured;
--      deletes store the primary key as a tombstone (row_data IS NULL).
--   2. A generic trigger attached to EVERY existing public application table,
--      and `backup_sync_triggers()` so a future migration can re-attach it to
--      new tables. All `backup_*` tables are excluded: the outbox can never
--      capture its own bookkeeping (no recursion, no amplification).
--   3. `public.backup_batches`, `backup_checkpoints`, `backup_snapshots`,
--      `backup_jobs`, `backup_drive_connections`, `backup_tracked_tables` —
--      the durable worker state, verified checkpoint, snapshot manifest state,
--      admin authorization and Drive connection metadata.
--   4. `backup_private` — a non-API schema for encrypted OAuth verifiers and
--      refresh credentials. It is NOT in PostgREST's exposed schemas, has no
--      grants for `anon`/`authenticated`, and is reachable only through a
--      handful of `SECURITY DEFINER` functions that check the caller.
--   5. `manage_backups` — a new permission granted to Super Admin only.
--
-- SCOPE (also written into every upload's manifest by the worker):
--   INCLUDED:  schema `public`, every application table listed in
--              `backup_tracked_tables` (65 at the time of writing).
--   EXCLUDED:  `auth.*` (Supabase Auth users/sessions/refresh tokens),
--              `storage.*`, `realtime.*`, `supabase_functions.*`, extension
--              schemas, `backup_private`, and every `public.backup_*` table.
--   THIS IS NOT COMPLETE DISASTER RECOVERY. Restoring it does not recreate
--   Supabase Auth accounts, OAuth provider configuration, RLS/grants, Storage
--   objects, secrets, or cron configuration. Those must be reprovisioned.
--
-- Safety properties enforced here:
--   * A change row is only ever removed by `backup_prune_change_log()`, which
--     refuses to prune anything above the last VERIFIED checkpoint or above
--     the oldest retained verified snapshot watermark.
--   * `backup_complete_batch()` is the ONLY writer of the checkpoint and runs
--     in the same transaction as the batch's `verified` transition.
--   * `backup_claim_batch()` takes a short quiesce lock on the outbox before
--     computing its horizon, so a transaction that allocated a lower change id
--     but has not committed yet can never be skipped.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Private schema for encrypted OAuth state
-- -----------------------------------------------------------------------------

create schema if not exists backup_private;
revoke all on schema backup_private from public, anon, authenticated;
grant usage on schema backup_private to service_role;

-- Belt and braces: even if the API roles were granted usage later, no table in
-- this schema is readable by them.
alter default privileges in schema backup_private revoke all on tables from public, anon, authenticated;
alter default privileges in schema backup_private grant all on tables to service_role;

create table if not exists backup_private.oauth_credentials (
  connection_ref       uuid primary key,
  credential_ciphertext text not null,
  iv_b64               text not null,
  tag_b64              text not null,
  key_ref              text not null,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);
alter table backup_private.oauth_credentials enable row level security;

create table if not exists backup_private.oauth_flows (
  state_hash           text primary key,
  profile_ref          uuid not null,
  verifier_ciphertext  text not null,
  iv_b64               text not null,
  tag_b64              text not null,
  key_ref              text not null,
  redirect_uri         text not null,
  expires_at           timestamptz not null,
  created_at           timestamptz not null default now()
);
alter table backup_private.oauth_flows enable row level security;

-- No policies at all: service_role bypasses RLS; SECURITY DEFINER functions
-- owned by postgres are the only other path in.
revoke all on backup_private.oauth_credentials from public, anon, authenticated;
revoke all on backup_private.oauth_flows from public, anon, authenticated;
grant all on backup_private.oauth_credentials, backup_private.oauth_flows to service_role;

comment on schema backup_private is
  'Encrypted Google Drive OAuth verifiers and refresh credentials. Not exposed by PostgREST; no API-role grants. Plaintext tokens are never stored in the database.';

-- -----------------------------------------------------------------------------
-- 2. Permission (Super Admin only by default)
-- -----------------------------------------------------------------------------

insert into public.permissions (key, label, description, group_name) values
  ('manage_backups', 'Manage encrypted Drive backups',
   'Connect the admin-only Google Drive account, inspect backup health, request a manual backup and retry a failed batch.',
   'Platform')
on conflict (key) do update
  set label = excluded.label, description = excluded.description, group_name = excluded.group_name;

insert into public.role_permissions (role_key, permission_key)
values ('super_admin', 'manage_backups')
on conflict do nothing;

-- -----------------------------------------------------------------------------
-- 3. Worker state tables
-- -----------------------------------------------------------------------------

create table public.backup_tracked_tables (
  schema_name    text not null default 'public',
  table_name     text not null,
  key_columns    text[] not null default '{}'::text[],
  capture        boolean not null default true,
  snapshot       boolean not null default true,
  created_at     timestamptz not null default now(),
  primary key (schema_name, table_name),
  constraint backup_tracked_tables_scope check (schema_name = 'public'),
  constraint backup_tracked_tables_not_system check (table_name not like 'backup_%'),
  constraint backup_tracked_tables_key_columns check (cardinality(key_columns) > 0)
);

create table public.backup_change_log (
  id              bigint generated always as identity primary key,
  schema_name     text not null default 'public',
  table_name      text not null,
  operation       text not null check (operation in ('insert', 'update', 'delete')),
  row_pk          jsonb not null,
  row_data        jsonb,
  transaction_ref text not null,
  occurred_at     timestamptz not null default now(),
  created_at      timestamptz not null default now(),
  constraint backup_change_log_tombstone check (
    (operation = 'delete' and row_data is null) or (operation <> 'delete' and row_data is not null)
  ),
  constraint backup_change_log_not_system check (table_name not like 'backup_%'),
  constraint backup_change_log_pk check (jsonb_typeof(row_pk) = 'object')
);
create index backup_change_log_table_id_idx on public.backup_change_log (table_name, id);
create index backup_change_log_created_idx on public.backup_change_log (created_at);
comment on table public.backup_change_log is
  'Transactional outbox for the Drive backup worker. Written only by AFTER ROW triggers inside the application transaction; never by a webhook.';
comment on column public.backup_change_log.row_data is
  'Full row image for insert/update; NULL for a delete. Deletes are tombstones identified by row_pk, so they survive removal of the source row.';

create table public.backup_drive_connections (
  id                uuid primary key default gen_random_uuid(),
  google_subject    text not null,
  account_label     text not null default 'Google Drive',
  folder_ref        text not null,
  folder_restricted boolean not null default true,
  scope             text not null default 'https://www.googleapis.com/auth/drive.file',
  status            text not null default 'active'
                    check (status in ('active', 'expired', 'revoked', 'error')),
  connected_by      uuid references public.profiles (id) on delete set null,
  connected_at      timestamptz not null default now(),
  last_success_at   timestamptz,
  last_error        text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  constraint backup_drive_connections_private check (folder_restricted),
  constraint backup_drive_connections_scope check (scope = 'https://www.googleapis.com/auth/drive.file')
);
create index backup_drive_connections_status_idx on public.backup_drive_connections (status, connected_at desc);
create index backup_drive_connections_actor_idx on public.backup_drive_connections (connected_by);
comment on table public.backup_drive_connections is
  'Metadata only. OAuth verifiers and refresh credentials live encrypted in backup_private, never here and never in the browser.';

create table public.backup_snapshots (
  id                uuid primary key default gen_random_uuid(),
  watermark         bigint not null,
  previous_watermark bigint not null default 0,
  status            text not null default 'building'
                    check (status in ('building', 'uploading', 'verified', 'failed')),
  manifest          jsonb not null default '{}'::jsonb,
  drive_file_ref    text,
  content_sha256    text,
  byte_size         bigint,
  attempt_count     integer not null default 0,
  last_error        text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  verified_at       timestamptz
);
create index backup_snapshots_created_idx on public.backup_snapshots (created_at desc);
create index backup_snapshots_status_idx on public.backup_snapshots (status, watermark desc);

create table public.backup_batches (
  id               uuid primary key default gen_random_uuid(),
  kind             text not null check (kind in ('incremental', 'snapshot')),
  status           text not null default 'pending'
                   check (status in ('pending', 'uploading', 'verified', 'failed')),
  range_key        text not null unique,
  first_change_id  bigint,
  last_change_id   bigint,
  snapshot_ref     uuid references public.backup_snapshots (id) on delete set null,
  connection_ref   uuid references public.backup_drive_connections (id) on delete set null,
  manifest         jsonb,
  drive_file_ref   text,
  content_sha256   text,
  byte_size        bigint,
  attempt_count    integer not null default 0,
  lease_owner      text,
  lease_until      timestamptz,
  next_attempt_at  timestamptz not null default now(),
  last_error       text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  verified_at      timestamptz,
  constraint backup_batches_incremental_range check (
    kind <> 'incremental' or (first_change_id is not null and last_change_id is not null
                              and last_change_id >= first_change_id)
  ),
  constraint backup_batches_verified_file check (
    status <> 'verified' or (drive_file_ref is not null and content_sha256 is not null)
  )
);
create index backup_batches_work_idx on public.backup_batches (status, next_attempt_at, created_at);
create index backup_batches_verified_idx on public.backup_batches (verified_at desc);
create index backup_batches_snapshot_idx on public.backup_batches (snapshot_ref);
create index backup_batches_connection_idx on public.backup_batches (connection_ref);
comment on table public.backup_batches is
  'One durable attempt per ordered change range. range_key makes retries idempotent; a batch is verified only after a Drive download+checksum check.';

create table public.backup_checkpoints (
  name                    text primary key default 'primary',
  last_change_id          bigint not null default 0,
  last_success_at         timestamptz,
  last_file_ref           text,
  last_content_sha256     text,
  last_snapshot_watermark bigint not null default 0,
  last_snapshot_at        timestamptz,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),
  constraint backup_checkpoints_singleton check (name = 'primary')
);
insert into public.backup_checkpoints (name, last_change_id) values ('primary', 0)
on conflict (name) do nothing;
comment on table public.backup_checkpoints is
  'Durable, monotonically advancing, successfully verified checkpoint. Only backup_complete_batch() writes last_change_id.';

create table public.backup_jobs (
  id             uuid primary key default gen_random_uuid(),
  kind           text not null check (kind in ('incremental', 'snapshot')),
  status         text not null default 'pending'
                 check (status in ('pending', 'running', 'done', 'failed')),
  requested_by   uuid references public.profiles (id) on delete set null,
  note           text,
  last_error     text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  completed_at   timestamptz
);
create index backup_jobs_pending_idx on public.backup_jobs (status, created_at);
create index backup_jobs_actor_idx on public.backup_jobs (requested_by);
comment on table public.backup_jobs is
  'Admin-authorized manual backup requests. The UI only enqueues; the background worker performs the Drive work.';

-- -----------------------------------------------------------------------------
-- 4. RLS — admin read only, no client writes, no change-log payload exposure
-- -----------------------------------------------------------------------------

alter table public.backup_tracked_tables    enable row level security;
alter table public.backup_change_log        enable row level security;
alter table public.backup_drive_connections enable row level security;
alter table public.backup_snapshots         enable row level security;
alter table public.backup_batches           enable row level security;
alter table public.backup_checkpoints       enable row level security;
alter table public.backup_jobs              enable row level security;

-- 018's default privileges give new tables SELECT/INSERT/DELETE to
-- authenticated. Backup state is written exclusively by the worker (service
-- role) and by permission-checked SECURITY DEFINER functions, so take all of
-- that away and grant back a narrow, read-only view.
do $$
declare
  v_table text;
begin
  for v_table in
    select unnest(array[
      'backup_tracked_tables', 'backup_change_log', 'backup_drive_connections',
      'backup_snapshots', 'backup_batches', 'backup_checkpoints', 'backup_jobs'
    ])
  loop
    execute format('revoke all on public.%I from public, anon, authenticated', v_table);
    execute format('grant all on public.%I to service_role', v_table);
    execute format('grant select on public.%I to authenticated', v_table);
    execute format(
      'create policy %I on public.%I for select to authenticated using (public.has_permission(''manage_backups''))',
      v_table || '_select_admin', v_table
    );
  end loop;
end $$;

-- The outbox contains full row images of private messages. Even a Super Admin
-- reading the admin page must not be able to select those columns through the
-- API; the worker uses service_role. Only safe metadata columns are exposed.
revoke select on public.backup_change_log from authenticated;
grant select (id, schema_name, table_name, operation, transaction_ref, occurred_at, created_at)
  on public.backup_change_log to authenticated;

-- -----------------------------------------------------------------------------
-- 5. Generic change-capture trigger
-- -----------------------------------------------------------------------------

create or replace function public.backup_capture_change()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_op    text;
  v_row   jsonb;
  v_keys  text[];
  v_pk    jsonb;
begin
  -- Hard recursion guard. Backup bookkeeping tables never get a trigger, but
  -- this also protects against a future migration attaching one by accident.
  if tg_table_schema = 'public' and tg_table_name like 'backup%' then
    return null;
  end if;

  v_op := lower(tg_op);
  if v_op = 'delete' then
    v_row := to_jsonb(old);
  else
    v_row := to_jsonb(new);
  end if;

  select coalesce(array_agg(a.attname order by k.ord), '{}'::text[])
    into v_keys
  from pg_index i
  join unnest(i.indkey) with ordinality k(attnum, ord) on true
  join pg_attribute a on a.attrelid = i.indrelid and a.attnum = k.attnum
  where i.indrelid = tg_relid and i.indisprimary;

  select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb)
    into v_pk
  from jsonb_each(v_row) e
  where e.key = any(v_keys);

  insert into public.backup_change_log (
    schema_name, table_name, operation, row_pk, row_data, transaction_ref, occurred_at
  ) values (
    tg_table_schema,
    tg_table_name,
    v_op,
    v_pk,
    case when v_op = 'delete' then null else v_row end,
    pg_current_xact_id()::text,
    now()
  );

  -- AFTER trigger: the return value is ignored. No network call, no HTTP
  -- extension, no pg_net — this insert commits or rolls back WITH the write.
  return null;
end $$;

comment on function public.backup_capture_change() is
  'Transactional outbox writer. One row per insert/update/delete in the application tables; delete rows are tombstones carrying only the primary key. Never calls Drive.';

/**
 * Attach (or re-attach) capture to every non-backup public table and record it
 * in the snapshot catalogue. Idempotent: safe to call from a later migration
 * after adding new application tables, and safe for the validation workflow to
 * call before asserting coverage.
 */
create or replace function public.backup_sync_triggers()
returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_table record;
  v_count integer := 0;
begin
  for v_table in
    select c.oid, c.relname as table_name
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public'
      and c.relkind = 'r'
      and c.relname not like 'backup%'
      and c.relname not like '\_\_test%'
    order by c.relname
  loop
    insert into public.backup_tracked_tables (schema_name, table_name, key_columns)
    select
      'public',
      v_table.table_name,
      coalesce(array_agg(a.attname order by k.ord), '{}'::text[])
    from pg_index i
    join unnest(i.indkey) with ordinality k(attnum, ord) on true
    join pg_attribute a on a.attrelid = i.indrelid and a.attnum = k.attnum
    where i.indrelid = v_table.oid and i.indisprimary
    on conflict (schema_name, table_name) do update
      set key_columns = excluded.key_columns, capture = true, snapshot = true;

    execute format('drop trigger if exists backup_capture on public.%I', v_table.table_name);
    execute format(
      'create trigger backup_capture after insert or update or delete on public.%I for each row execute function public.backup_capture_change()',
      v_table.table_name
    );
    v_count := v_count + 1;
  end loop;
  return v_count;
end $$;

comment on function public.backup_sync_triggers() is
  'Idempotently attaches the outbox trigger to every public application table and refreshes the snapshot table catalogue. Excludes all backup_* tables.';

select public.backup_sync_triggers();

-- -----------------------------------------------------------------------------
-- 6. Worker RPCs (service_role only)
-- -----------------------------------------------------------------------------

/**
 * Establish a clean horizon. `SHARE ROW EXCLUSIVE` conflicts with the
 * `ROW EXCLUSIVE` lock held by every transaction that inserted into the outbox,
 * so this waits for in-flight application transactions to finish and blocks new
 * ones for the few milliseconds needed to read max(id). A transaction that
 * allocated a lower id but commits later therefore cannot be skipped.
 */
create or replace function public.backup_snapshot_watermark()
returns bigint
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_watermark bigint;
begin
  if not public.is_trusted_writer() then
    raise exception 'backup_snapshot_watermark is worker-only' using errcode = '42501';
  end if;
  lock table public.backup_change_log in share row exclusive mode;
  select coalesce(max(id), 0) into v_watermark from public.backup_change_log;
  return v_watermark;
end $$;

/** Ordered, visible change rows for one claimed range. */
create or replace function public.backup_pending_changes(p_first bigint, p_last bigint)
returns setof public.backup_change_log
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select c.*
  from public.backup_change_log c
  where c.id >= p_first and c.id <= p_last
  order by c.id asc
$$;

/**
 * Claim exactly one unit of work. Serialized by an advisory lock, so two
 * workers can never claim the same range. A failed batch or an expired lease is
 * reclaimed before a new range is created. `range_key` is deterministic, so a
 * duplicate attempt reuses the same batch row and the same Drive object name.
 */
create or replace function public.backup_claim_batch(
  p_worker_id     text,
  p_batch_size    integer default 500,
  p_lease_seconds integer default 300
)
returns setof public.backup_batches
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_batch     public.backup_batches;
  v_horizon   bigint;
  v_checkpoint bigint;
  v_first     bigint;
  v_last      bigint;
  v_key       text;
  v_limit     integer := greatest(1, least(coalesce(p_batch_size, 500), 5000));
begin
  if not public.is_trusted_writer() then
    raise exception 'backup_claim_batch is worker-only' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(hashtext('campus_plus_backup_claim'));

  -- Reclaim a failed batch whose backoff has elapsed, an expired lease, or a
  -- pending snapshot batch before looking for fresh changes.
  update public.backup_batches b
     set status          = 'uploading',
         lease_owner     = p_worker_id,
         lease_until     = now() + make_interval(secs => greatest(30, p_lease_seconds)),
         attempt_count   = b.attempt_count + 1,
         last_error      = null,
         updated_at      = now()
   where b.id = (
     select candidate.id
     from public.backup_batches candidate
     where candidate.status = 'pending'
        or (candidate.status = 'failed' and candidate.next_attempt_at <= now())
        or (candidate.status = 'uploading' and candidate.lease_until < now())
     order by candidate.created_at asc
     limit 1
     for update skip locked
   )
   returning * into v_batch;

  if found then
    return next v_batch;
    return;
  end if;

  lock table public.backup_change_log in share row exclusive mode;
  select coalesce(max(id), 0) into v_horizon from public.backup_change_log;
  select c.last_change_id into v_checkpoint
    from public.backup_checkpoints c where c.name = 'primary';

  select min(s.id), max(s.id) into v_first, v_last
  from (
    select c.id
    from public.backup_change_log c
    where c.id > coalesce(v_checkpoint, 0) and c.id <= v_horizon
    order by c.id asc
    limit v_limit
  ) s;

  if v_first is null then
    return;
  end if;

  v_key := 'incremental:' || v_first || ':' || v_last;
  insert into public.backup_batches (
    kind, status, range_key, first_change_id, last_change_id,
    attempt_count, lease_owner, lease_until, created_at, updated_at
  ) values (
    'incremental', 'uploading', v_key, v_first, v_last,
    1, p_worker_id, now() + make_interval(secs => greatest(30, p_lease_seconds)), now(), now()
  )
  -- A duplicate range can only be an already-stored attempt. Reclaim it ONLY
  -- when its lease is dead or it was marked failed/pending; never steal a live
  -- lease from another worker, and never re-open a verified batch.
  on conflict (range_key) do update
    set status = 'uploading',
        lease_owner = excluded.lease_owner,
        lease_until = excluded.lease_until,
        attempt_count = public.backup_batches.attempt_count + 1,
        updated_at = now()
    where public.backup_batches.status in ('pending', 'failed')
       or (public.backup_batches.status = 'uploading' and public.backup_batches.lease_until < now())
  returning * into v_batch;

  if found then
    return next v_batch;
  end if;
  return;
end $$;

/**
 * The ONLY checkpoint writer. Requires a still-valid lease and a positive
 * verification flag from the worker. Marking the batch verified and advancing
 * the checkpoint happen in one transaction: there is no window in which the
 * checkpoint points at an unverified Drive object.
 */
create or replace function public.backup_complete_batch(
  p_worker_id       text,
  p_batch_id        uuid,
  p_drive_file_ref  text,
  p_sha256          text,
  p_byte_size       bigint,
  p_manifest        jsonb default '{}'::jsonb
)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_batch public.backup_batches;
begin
  if not public.is_trusted_writer() then
    raise exception 'backup_complete_batch is worker-only' using errcode = '42501';
  end if;
  if coalesce(p_drive_file_ref, '') = '' or coalesce(p_sha256, '') = '' then
    raise exception 'a verified Drive file id and checksum are required';
  end if;

  select * into v_batch from public.backup_batches b
   where b.id = p_batch_id for update;
  if not found then
    raise exception 'unknown backup batch %', p_batch_id;
  end if;
  if v_batch.status = 'verified' then
    -- Idempotent duplicate completion: never rewinds the checkpoint.
    return true;
  end if;
  if v_batch.status <> 'uploading' or v_batch.lease_owner <> p_worker_id
     or v_batch.lease_until < now() then
    raise exception 'batch lease is no longer owned by this worker';
  end if;

  update public.backup_batches
     set status = 'verified',
         drive_file_ref = p_drive_file_ref,
         content_sha256 = p_sha256,
         byte_size = p_byte_size,
         manifest = p_manifest,
         verified_at = now(),
         updated_at = now(),
         lease_owner = null,
         lease_until = null,
         last_error = null
   where id = p_batch_id;

  if v_batch.kind = 'incremental' then
    update public.backup_checkpoints
       set last_change_id = greatest(last_change_id, v_batch.last_change_id),
           last_success_at = now(),
           last_file_ref = p_drive_file_ref,
           last_content_sha256 = p_sha256,
           updated_at = now()
     where name = 'primary';
  end if;

  update public.backup_drive_connections
     set last_success_at = now(), last_error = null, updated_at = now()
   where status = 'active';

  return true;
end $$;

/** Record a retryable failure. Pending events are left untouched. */
create or replace function public.backup_fail_batch(
  p_worker_id           text,
  p_batch_id            uuid,
  p_error               text,
  p_retry_delay_seconds integer default 60
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_trusted_writer() then
    raise exception 'backup_fail_batch is worker-only' using errcode = '42501';
  end if;
  update public.backup_batches
     set status = 'failed',
         last_error = left(coalesce(p_error, 'unknown error'), 2000),
         next_attempt_at = now() + make_interval(secs => greatest(5, least(coalesce(p_retry_delay_seconds, 60), 86400))),
         updated_at = now(),
         lease_owner = null,
         lease_until = null
   where id = p_batch_id
     and status = 'uploading'
     and lease_owner = p_worker_id;

  update public.backup_drive_connections
     set last_error = left(coalesce(p_error, 'unknown error'), 2000), updated_at = now()
   where status = 'active';
end $$;

/**
 * Retention. Only change rows that are (a) at or below the last VERIFIED
 * checkpoint AND (b) at or below the watermark of the OLDEST retained verified
 * snapshot AND (c) older than p_min_age_days may be discarded. Without a
 * verified snapshot the cutoff stays at zero: incrementals alone can never
 * justify pruning the log, because a restore needs a base to replay onto.
 */
create or replace function public.backup_prune_change_log(
  p_keep_snapshots  integer default 14,
  p_min_age_days    integer default 7
)
returns bigint
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_cutoff bigint := 0;
  v_oldest bigint;
  v_checkpoint bigint;
begin
  if not public.is_trusted_writer() then
    raise exception 'backup_prune_change_log is worker-only' using errcode = '42501';
  end if;

  select min(watermark) into v_oldest
  from (
    select watermark from public.backup_snapshots
     where status = 'verified'
     order by created_at desc
     limit greatest(1, least(coalesce(p_keep_snapshots, 14), 365))
  ) kept;

  select last_change_id into v_checkpoint
    from public.backup_checkpoints where name = 'primary';

  if v_oldest is not null then
    v_cutoff := least(v_oldest, coalesce(v_checkpoint, 0));
  end if;

  if v_cutoff > 0 then
    delete from public.backup_change_log c
     where c.id <= v_cutoff
       and c.created_at < now() - make_interval(days => greatest(0, p_min_age_days));
  end if;
  return v_cutoff;
end $$;

-- -----------------------------------------------------------------------------
-- 6b. Snapshot + scheduled-job RPCs (service_role only)
-- -----------------------------------------------------------------------------

/** Register the start of a full snapshot at a previously established horizon. */
create or replace function public.backup_start_snapshot(
  p_watermark          bigint,
  p_previous_watermark bigint default 0,
  p_manifest           jsonb default '{}'::jsonb
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
begin
  if not public.is_trusted_writer() then
    raise exception 'backup_start_snapshot is worker-only' using errcode = '42501';
  end if;
  insert into public.backup_snapshots (watermark, previous_watermark, manifest, status)
  values (p_watermark, greatest(0, p_previous_watermark), p_manifest, 'building')
  returning id into v_id;
  return v_id;
end $$;

/**
 * Mark a snapshot verified ONLY after the Drive object has been downloaded and
 * its checksum matched. Updates the snapshot watermark in the same durable
 * checkpoint row used by incremental exports.
 */
create or replace function public.backup_complete_snapshot(
  p_snapshot_id    uuid,
  p_drive_file_ref text,
  p_sha256         text,
  p_byte_size      bigint,
  p_manifest       jsonb default '{}'::jsonb
)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_snapshot public.backup_snapshots;
begin
  if not public.is_trusted_writer() then
    raise exception 'backup_complete_snapshot is worker-only' using errcode = '42501';
  end if;
  if coalesce(p_drive_file_ref, '') = '' or coalesce(p_sha256, '') = '' then
    raise exception 'a verified Drive file id and checksum are required';
  end if;

  select * into v_snapshot from public.backup_snapshots where id = p_snapshot_id for update;
  if not found then raise exception 'unknown snapshot %', p_snapshot_id; end if;
  if v_snapshot.status = 'verified' then return true; end if;

  update public.backup_snapshots
     set status = 'verified', drive_file_ref = p_drive_file_ref, content_sha256 = p_sha256,
         byte_size = p_byte_size, manifest = p_manifest, verified_at = now(),
         updated_at = now(), last_error = null
   where id = p_snapshot_id;

  update public.backup_checkpoints
     set last_snapshot_watermark = greatest(last_snapshot_watermark, v_snapshot.watermark),
         last_snapshot_at = now(), updated_at = now()
   where name = 'primary';

  -- A snapshot batch is also visible in the admin history.
  insert into public.backup_batches (
    kind, status, range_key, snapshot_ref, manifest,
    drive_file_ref, content_sha256, byte_size, verified_at
  ) values (
    'snapshot', 'verified', 'snapshot:' || v_snapshot.watermark || ':' || p_snapshot_id,
    p_snapshot_id, p_manifest, p_drive_file_ref, p_sha256, p_byte_size, now()
  ) on conflict (range_key) do nothing;

  update public.backup_drive_connections
     set last_success_at = now(), last_error = null, updated_at = now()
   where status = 'active';
  return true;
end $$;

create or replace function public.backup_fail_snapshot(p_snapshot_id uuid, p_error text)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_trusted_writer() then
    raise exception 'backup_fail_snapshot is worker-only' using errcode = '42501';
  end if;
  update public.backup_snapshots
     set status = 'failed', last_error = left(coalesce(p_error, 'unknown error'), 2000),
         attempt_count = attempt_count + 1, updated_at = now()
   where id = p_snapshot_id and status <> 'verified';
end $$;

/** Claim one admin-authorized or scheduled job. */
create or replace function public.backup_claim_job(p_kind text, p_worker_id text)
returns setof public.backup_jobs
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_trusted_writer() then
    raise exception 'backup_claim_job is worker-only' using errcode = '42501';
  end if;
  return query
  update public.backup_jobs j
     set status = 'running', updated_at = now()
   where j.id = (
     select candidate.id from public.backup_jobs candidate
      where candidate.kind = p_kind and candidate.status = 'pending'
      order by candidate.created_at asc limit 1 for update skip locked
   )
  returning j.*;
end $$;

create or replace function public.backup_finish_job(p_job_id uuid, p_error text default null)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_trusted_writer() then
    raise exception 'backup_finish_job is worker-only' using errcode = '42501';
  end if;
  update public.backup_jobs
     set status = case when p_error is null then 'done' else 'failed' end,
         last_error = left(p_error, 2000), completed_at = now(), updated_at = now()
   where id = p_job_id;
end $$;

-- -----------------------------------------------------------------------------
-- 7. Admin RPCs (RLS-authenticated, permission-checked, audited)
-- -----------------------------------------------------------------------------

create or replace function public.backup_status()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_result jsonb;
begin
  if not public.has_permission('manage_backups') then
    raise exception 'You do not have permission to view backups.' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'connection', (
      select jsonb_build_object(
        'status', c.status, 'account_label', c.account_label,
        'folder_ref', c.folder_ref, 'folder_restricted', c.folder_restricted,
        'connected_at', c.connected_at, 'last_success_at', c.last_success_at,
        'last_error', c.last_error
      )
      from public.backup_drive_connections c
      order by c.connected_at desc limit 1
    ),
    'checkpoint', (
      select jsonb_build_object(
        'last_change_id', c.last_change_id, 'last_success_at', c.last_success_at,
        'last_file_ref', c.last_file_ref, 'last_snapshot_watermark', c.last_snapshot_watermark,
        'last_snapshot_at', c.last_snapshot_at
      )
      from public.backup_checkpoints c where c.name = 'primary'
    ),
    'queue_depth', (
      select count(*) from public.backup_change_log c
       where c.id > (select last_change_id from public.backup_checkpoints where name = 'primary')
    ),
    'oldest_pending_at', (
      select min(c.occurred_at) from public.backup_change_log c
       where c.id > (select last_change_id from public.backup_checkpoints where name = 'primary')
    ),
    'failed_batches', (
      select count(*) from public.backup_batches b where b.status = 'failed'
    ),
    'pending_jobs', (
      select count(*) from public.backup_jobs j where j.status in ('pending', 'running')
    ),
    'errors', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', b.id, 'range_key', b.range_key, 'attempt_count', b.attempt_count,
        'last_error', b.last_error, 'next_attempt_at', b.next_attempt_at,
        'updated_at', b.updated_at
      ) order by b.updated_at desc)
      from (
        select * from public.backup_batches b where b.status = 'failed' order by b.updated_at desc limit 5
      ) b
    ), '[]'::jsonb),
    'history', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', h.id, 'kind', h.kind, 'range_key', h.range_key,
        'first_change_id', h.first_change_id, 'last_change_id', h.last_change_id,
        'verified_at', h.verified_at, 'byte_size', h.byte_size,
        'drive_file_ref', h.drive_file_ref, 'attempt_count', h.attempt_count
      ) order by coalesce(h.verified_at, h.created_at) desc)
      from (
        select * from public.backup_batches b
         where b.status = 'verified' or b.status = 'failed'
         order by coalesce(b.verified_at, b.created_at) desc limit 20
      ) h
    ), '[]'::jsonb),
    'snapshots', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', s.id, 'watermark', s.watermark, 'status', s.status,
        'created_at', s.created_at, 'verified_at', s.verified_at,
        'byte_size', s.byte_size, 'drive_file_ref', s.drive_file_ref,
        'last_error', s.last_error
      ) order by s.created_at desc)
      from (select * from public.backup_snapshots order by created_at desc limit 14) s
    ), '[]'::jsonb),
    'scope', jsonb_build_object(
      'schemas', jsonb_build_array('public'),
      'tracked_tables', (select count(*) from public.backup_tracked_tables where snapshot),
      'excluded', jsonb_build_array('auth.*', 'storage.*', 'realtime.*', 'backup_private', 'public.backup_*'),
      'complete_disaster_recovery', false
    )
  ) into v_result;
  return v_result;
end $$;

/** Enqueue an admin-authorized manual run. Idempotent for 60 seconds. */
create or replace function public.backup_request_job(p_kind text, p_note text default null)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
begin
  if not public.has_permission('manage_backups') then
    raise exception 'You do not have permission to run backups.' using errcode = '42501';
  end if;
  if p_kind not in ('incremental', 'snapshot') then
    raise exception 'unknown backup kind';
  end if;

  select id into v_id from public.backup_jobs
   where kind = p_kind and status = 'pending' and created_at > now() - interval '60 seconds'
   order by created_at desc limit 1;
  if found then
    return v_id;
  end if;

  insert into public.backup_jobs (kind, requested_by, note)
  values (p_kind, public.current_profile_id(), left(coalesce(p_note, ''), 500))
  returning id into v_id;

  perform public.log_audit(
    'backup.request', 'backup_job', v_id::text,
    jsonb_build_object('kind', p_kind), false, null, 'admin'::public.moderation_visibility
  );
  return v_id;
end $$;

/** Authorized retry: reset a failed batch to immediately claimable. */
create or replace function public.backup_retry_failed(p_batch_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_count integer := 0;
begin
  if not public.has_permission('manage_backups') then
    raise exception 'You do not have permission to retry backups.' using errcode = '42501';
  end if;
  update public.backup_batches
     set status = 'pending', next_attempt_at = now(), last_error = null,
         lease_owner = null, lease_until = null, updated_at = now()
   where id = p_batch_id and status = 'failed';
  get diagnostics v_count = row_count;
  if v_count > 0 then
    perform public.log_audit(
      'backup.retry', 'backup_batch', p_batch_id::text,
      '{}'::jsonb, false, null, 'admin'::public.moderation_visibility
    );
  end if;
  return v_count > 0;
end $$;

-- -----------------------------------------------------------------------------
-- 8. Encrypted private-store RPCs
-- -----------------------------------------------------------------------------

/** Store a one-time PKCE verifier for the admin OAuth round trip. */
create or replace function public.backup_start_oauth_flow(
  p_state_hash    text,
  p_redirect_uri  text,
  p_ciphertext    text,
  p_iv_b64        text,
  p_tag_b64       text,
  p_key_ref       text,
  p_expires_at    timestamptz
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.has_permission('manage_backups') then
    raise exception 'You do not have permission to connect Drive.' using errcode = '42501';
  end if;
  delete from backup_private.oauth_flows where expires_at < now();
  insert into backup_private.oauth_flows (
    state_hash, profile_ref, verifier_ciphertext, iv_b64, tag_b64, key_ref, redirect_uri, expires_at
  ) values (
    p_state_hash, public.current_profile_id(), p_ciphertext, p_iv_b64, p_tag_b64, p_key_ref,
    p_redirect_uri, p_expires_at
  );
  perform public.log_audit(
    'backup.oauth_start', 'backup_connection', null,
    '{}'::jsonb, false, null, 'admin'::public.moderation_visibility
  );
end $$;

/** Consume (single use) a PKCE flow. Returns the encrypted verifier. */
create or replace function public.backup_take_oauth_flow(p_state_hash text)
returns table (
  redirect_uri        text,
  verifier_ciphertext text,
  iv_b64              text,
  tag_b64             text,
  key_ref             text
)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.has_permission('manage_backups') then
    raise exception 'You do not have permission to connect Drive.' using errcode = '42501';
  end if;
  return query
    delete from backup_private.oauth_flows f
     where f.state_hash = p_state_hash
       and f.profile_ref = public.current_profile_id()
       and f.expires_at > now()
    returning f.redirect_uri, f.verifier_ciphertext, f.iv_b64, f.tag_b64, f.key_ref;
end $$;

/**
 * Finish the connection: create the public metadata row, mark older
 * connections revoked, and store the refresh credential encrypted in the
 * private schema. `p_folder_ref` must be a folder the app itself created and
 * verified as unshared; the callback path enforces that before calling.
 */
create or replace function public.backup_store_connection(
  p_subject     text,
  p_label       text,
  p_folder_ref  text,
  p_ciphertext  text,
  p_iv_b64      text,
  p_tag_b64     text,
  p_key_ref     text
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
begin
  if not public.has_permission('manage_backups') then
    raise exception 'You do not have permission to connect Drive.' using errcode = '42501';
  end if;
  if coalesce(p_folder_ref, '') = '' or coalesce(p_ciphertext, '') = '' then
    raise exception 'a restricted folder and an encrypted credential are required';
  end if;

  update public.backup_drive_connections set status = 'revoked', updated_at = now()
   where status = 'active';

  insert into public.backup_drive_connections (
    google_subject, account_label, folder_ref, folder_restricted, connected_by
  ) values (
    p_subject, left(coalesce(p_label, 'Google Drive'), 120), p_folder_ref, true,
    public.current_profile_id()
  ) returning id into v_id;

  insert into backup_private.oauth_credentials (
    connection_ref, credential_ciphertext, iv_b64, tag_b64, key_ref
  ) values (
    v_id, p_ciphertext, p_iv_b64, p_tag_b64, p_key_ref
  );

  perform public.log_audit(
    'backup.oauth_connected', 'backup_connection', v_id::text,
    jsonb_build_object('folder_ref', p_folder_ref), false, null, 'admin'::public.moderation_visibility
  );
  return v_id;
end $$;

/** Worker-only: load the encrypted refresh credential. */
create or replace function public.backup_private_get_credentials(p_connection_ref uuid)
returns table (
  credential_ciphertext text,
  iv_b64                text,
  tag_b64               text,
  key_ref               text
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_trusted_writer() then
    raise exception 'credentials are worker-only' using errcode = '42501';
  end if;
  return query
    select c.credential_ciphertext, c.iv_b64, c.tag_b64, c.key_ref
    from backup_private.oauth_credentials c
    where c.connection_ref = p_connection_ref;
end $$;

/** Worker-only: persist a rotated refresh credential. */
create or replace function public.backup_private_rotate_credentials(
  p_connection_ref uuid,
  p_ciphertext     text,
  p_iv_b64         text,
  p_tag_b64        text,
  p_key_ref        text
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_trusted_writer() then
    raise exception 'credentials are worker-only' using errcode = '42501';
  end if;
  update backup_private.oauth_credentials
     set credential_ciphertext = p_ciphertext, iv_b64 = p_iv_b64,
         tag_b64 = p_tag_b64, key_ref = p_key_ref, updated_at = now()
   where connection_ref = p_connection_ref;
end $$;

/** Admin disconnect: revoke metadata and delete the stored credential. */
create or replace function public.backup_disconnect()
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  -- An authenticated Super Admin uses the UI button; the operator CLI calls
  -- this with the service-role key (trusted writer) after Google revocation.
  if not (public.has_permission('manage_backups') or public.is_trusted_writer()) then
    raise exception 'You do not have permission to disconnect Drive.' using errcode = '42501';
  end if;
  delete from backup_private.oauth_credentials c
   using public.backup_drive_connections d
   where c.connection_ref = d.id;
  update public.backup_drive_connections
     set status = 'revoked', updated_at = now()
   where status <> 'revoked';
  perform public.log_audit(
    'backup.oauth_disconnected', 'backup_connection', null,
    '{}'::jsonb, false, null, 'admin'::public.moderation_visibility
  );
end $$;

-- -----------------------------------------------------------------------------
-- 9. Function grants — worker-only functions must NOT be callable by students
-- -----------------------------------------------------------------------------

do $$
declare
  v_fn text;
  v_worker_only text[] := array[
    'backup_snapshot_watermark()',
    'backup_pending_changes(bigint, bigint)',
    'backup_claim_batch(text, integer, integer)',
    'backup_complete_batch(text, uuid, text, text, bigint, jsonb)',
    'backup_fail_batch(text, uuid, text, integer)',
    'backup_prune_change_log(integer, integer)',
    'backup_start_snapshot(bigint, bigint, jsonb)',
    'backup_complete_snapshot(uuid, text, text, bigint, jsonb)',
    'backup_fail_snapshot(uuid, text)',
    'backup_claim_job(text, text)',
    'backup_finish_job(uuid, text)',
    'backup_private_get_credentials(uuid)',
    'backup_private_rotate_credentials(uuid, text, text, text, text)',
    'backup_sync_triggers()'
  ];
begin
  -- 018 grants new functions to authenticated by default; revoke that for the
  -- worker/admin RPC surface and then grant back only what each needs.
  foreach v_fn in array v_worker_only loop
    execute format('revoke all on function public.%s from public, anon, authenticated', v_fn);
    execute format('grant execute on function public.%s to service_role', v_fn);
  end loop;

  -- The trigger function must never be called directly.
  execute 'revoke all on function public.backup_capture_change() from public, anon, authenticated';

  -- Two older trigger helpers were first created before migration 018 and later
  -- replaced with CREATE OR REPLACE, which preserves their original
  -- PUBLIC EXECUTE grant. Trigger functions are never RPCs, so close that
  -- pre-existing anon surface here rather than leave the audit red.
  for v_fn in
    select distinct p.oid::regprocedure::text
    from pg_trigger t
    join pg_proc p on p.oid = t.tgfoid
    join pg_namespace n on n.oid = p.pronamespace
    where not t.tgisinternal and n.nspname = 'public'
  loop
    execute format('revoke all on function %s from public, anon, authenticated', v_fn);
  end loop;

  -- Admin RPCs: authenticated, and each one re-checks manage_backups itself.
  for v_fn in
    select unnest(array[
      'backup_status()',
      'backup_request_job(text, text)',
      'backup_retry_failed(uuid)',
      'backup_start_oauth_flow(text, text, text, text, text, text, timestamptz)',
      'backup_take_oauth_flow(text)',
      'backup_store_connection(text, text, text, text, text, text, text)',
      'backup_disconnect()'
    ])
  loop
    execute format('revoke all on function public.%s from public, anon', v_fn);
    execute format('grant execute on function public.%s to authenticated, service_role', v_fn);
  end loop;
end $$;

comment on function public.backup_status() is
  'Admin-only backup health: connection status, last verified export, queue depth, failures, history and snapshot scope. Never returns credentials or row payloads.';
comment on function public.backup_complete_batch(text, uuid, text, text, bigint, jsonb) is
  'Sole writer of the durable checkpoint; requires a live lease and is called only after a verified Drive download.';

-- ==========================================================================
-- FILE 28/79  20261025000002_028_backup_admin_processing.sql
-- ==========================================================================

-- =============================================================================
-- Campus+ migration 028 — admin-authorized, concurrency-safe backup processing
-- =============================================================================
-- Problem this fixes (no schema change to the outbox itself):
--   * The UI only ever called `backup_request_job()`, which ENQUEUES work.
--     With cron limited to once per day on Vercel Hobby, 12 queued jobs could
--     sit there forever. `runBackupWorker()` also claims only ONE job and ONE
--     batch per invocation.
--   * A Super Admin needs to be able to *drain* that queue from the browser,
--     in bounded batches, without a terminal, without exposing the service
--     role or the encrypted Drive credential, and without two runs (admin +
--     cron) uploading the same range at once.
--
-- What lands here:
--   1. `backup_run_leases` — one durable, expiring lease per backup kind.
--      Cron ticks, the CLI and the admin action all acquire it. If a function
--      is killed the lease simply expires; a later run requeues jobs that a
--      crashed run left `running`. Nothing is ever deleted.
--   2. `backup_run_log` — a short, secret-free record of each UI-triggered run
--      (status, verified object ids, redacted diagnostics) so the Admin page
--      can show queued / processing / verified / failed even after a refresh.
--   3. `backup_admin_state()` — permission-checked aggregate of job counts,
--      batch retry state, active leases and recent runs. No row images, no
--      credentials, no connection strings.
--   4. `backup_record_run()` — permission-checked, audited writer for the run
--      log. It re-checks `manage_backups` and rejects any payload that looks
--      like a secret.
--
-- Security: every table is RLS-enabled with admin read only; the lease and
-- log-writing RPCs are worker/admin gated. `backup_private` is untouched, and
-- no new grant is given to `anon` or to `authenticated` for writing state.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Durable, expiring run leases (worker-only state)
-- -----------------------------------------------------------------------------

create table if not exists public.backup_run_leases (
  kind         text primary key check (kind in ('incremental', 'snapshot')),
  lease_owner  text not null,
  lease_until  timestamptz not null,
  started_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create table if not exists public.backup_run_log (
  id          uuid primary key default gen_random_uuid(),
  kind        text not null check (kind in ('incremental', 'snapshot')),
  status      text not null check (status in ('verified', 'drained', 'idle', 'busy', 'failed', 'not_configured')),
  summary     jsonb not null default '{}'::jsonb,
  actor       uuid references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now()
);
create index if not exists backup_run_log_recent_idx on public.backup_run_log (created_at desc);
-- The `actor` FK is filtered when an operator asks "what did this admin run?",
-- so it needs its own index (same convention as backup_jobs.requested_by).
create index if not exists backup_run_log_actor_idx on public.backup_run_log (actor, created_at desc);

comment on table public.backup_run_leases is
  'One expiring lease per backup kind. Prevents a cron tick and an admin-triggered run from processing the same queue concurrently.';
comment on table public.backup_run_log is
  'Secret-free, audited summary of each admin-triggered backup run for the Backups page.';

alter table public.backup_run_leases enable row level security;
alter table public.backup_run_log    enable row level security;

-- 018 grants new tables to `authenticated` by default. Backup machinery is
-- worker-only: take everything away, then grant a narrow admin read policy.
do $$
declare
  v_table text;
begin
  foreach v_table in array array['backup_run_leases', 'backup_run_log'] loop
    execute format('revoke all on public.%I from public, anon, authenticated', v_table);
    execute format('grant all on public.%I to service_role', v_table);
    execute format('grant select on public.%I to authenticated', v_table);
    execute format(
      'create policy %I on public.%I for select to authenticated using (public.has_permission(''manage_backups''))',
      v_table || '_select_admin', v_table
    );
  end loop;
end $$;

-- -----------------------------------------------------------------------------
-- 2. Worker-only lease RPCs
-- -----------------------------------------------------------------------------

/**
 * Atomically take the lease for one kind. A live lease held by a DIFFERENT
 * owner cannot be stolen. An expired lease (killed function) is taken over,
 * and jobs that the interrupted run left `running` are put back to `pending`
 * with their identity and history intact — never deleted, never marked done.
 */
create or replace function public.backup_acquire_run_lease(
  p_kind       text,
  p_worker_id  text,
  p_seconds    integer default 180
)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_acquired   boolean := false;
  v_expired    boolean := false;
  v_seconds    integer := greatest(30, least(coalesce(p_seconds, 180), 900));
begin
  if not public.is_trusted_writer() then
    raise exception 'backup_acquire_run_lease is worker-only' using errcode = '42501';
  end if;
  if p_kind not in ('incremental', 'snapshot') then
    raise exception 'unknown backup kind';
  end if;
  if coalesce(p_worker_id, '') = '' or length(p_worker_id) > 200 then
    raise exception 'invalid worker id';
  end if;

  select l.lease_until < now() into v_expired
    from public.backup_run_leases l where l.kind = p_kind;
  v_expired := coalesce(v_expired, false);

  insert into public.backup_run_leases (kind, lease_owner, lease_until, started_at, updated_at)
  values (p_kind, p_worker_id, now() + make_interval(secs => v_seconds), now(), now())
  on conflict (kind) do update
     set lease_owner = excluded.lease_owner,
         lease_until = excluded.lease_until,
         started_at  = excluded.started_at,
         updated_at  = now()
   where public.backup_run_leases.lease_until < now()
      or public.backup_run_leases.lease_owner = excluded.lease_owner
  returning true into v_acquired;

  v_acquired := coalesce(v_acquired, false);
  if v_acquired then
    -- Taking over an expired lease means no live run exists for this kind, so
    -- every `running` job is orphaned. Otherwise only genuinely ancient ones
    -- are recovered (a live run owns its own fresh `running` jobs).
    update public.backup_jobs j
       set status = 'pending', last_error = null, updated_at = now()
     where j.kind = p_kind
       and j.status = 'running'
       and (v_expired or j.updated_at < now() - interval '10 minutes');
  end if;
  return v_acquired;
end $$;

/** Release only our own lease. An expired lease is harmless if never released. */
create or replace function public.backup_release_run_lease(p_kind text, p_worker_id text)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_trusted_writer() then
    raise exception 'backup_release_run_lease is worker-only' using errcode = '42501';
  end if;
  -- `now()` is the transaction-start timestamp, so setting it to exactly now()
  -- would leave `lease_until < now()` false inside the same transaction. Use a
  -- definitely-past value: the lease is over, and any waiting run may take it.
  update public.backup_run_leases
     set lease_until = now() - interval '1 second', updated_at = now()
   where kind = p_kind and lease_owner = p_worker_id;
end $$;

-- -----------------------------------------------------------------------------
-- 3. Admin-visible job state + audited run log
-- -----------------------------------------------------------------------------

create or replace function public.backup_admin_state()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_result jsonb;
begin
  if not public.has_permission('manage_backups') then
    raise exception 'You do not have permission to view backup job state.' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'jobs', (
      select jsonb_build_object(
        'queued',     count(*) filter (where j.status = 'pending'),
        'processing', count(*) filter (where j.status = 'running'),
        'verified',   count(*) filter (where j.status = 'done'),
        'failed',     count(*) filter (where j.status = 'failed')
      ) from public.backup_jobs j
    ),
    'jobs_by_kind', coalesce((
      select jsonb_object_agg(s.kind, s.counts) from (
        select j.kind,
               jsonb_build_object(
                 'queued',     count(*) filter (where j.status = 'pending'),
                 'processing', count(*) filter (where j.status = 'running'),
                 'verified',   count(*) filter (where j.status = 'done'),
                 'failed',     count(*) filter (where j.status = 'failed')
               ) as counts
        from public.backup_jobs j group by j.kind
      ) s
    ), '{}'::jsonb),
    'recent_jobs', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', j.id, 'kind', j.kind, 'status', j.status,
        'note', j.note, 'last_error', left(j.last_error, 300),
        'created_at', j.created_at, 'updated_at', j.updated_at, 'completed_at', j.completed_at
      ) order by j.created_at desc)
      from (select * from public.backup_jobs order by created_at desc limit 16) j
    ), '[]'::jsonb),
    'batches', jsonb_build_object(
      'uploading',     (select count(*) from public.backup_batches where status = 'uploading'),
      'pending',       (select count(*) from public.backup_batches where status = 'pending'),
      'failed',        (select count(*) from public.backup_batches where status = 'failed'),
      'verified',      (select count(*) from public.backup_batches where status = 'verified'),
      'retry_waiting', (select count(*) from public.backup_batches where status = 'failed' and next_attempt_at > now()),
      'next_retry_at', (select min(next_attempt_at) from public.backup_batches where status = 'failed' and next_attempt_at > now())
    ),
    'snapshots', jsonb_build_object(
      'running',    (select count(*) from public.backup_snapshots where status in ('pending', 'uploading')),
      'failed',     (select count(*) from public.backup_snapshots where status = 'failed'),
      'last_error', (select left(last_error, 300) from public.backup_snapshots where status = 'failed' order by updated_at desc limit 1)
    ),
    'leases', coalesce((
      select jsonb_agg(jsonb_build_object(
        'kind', l.kind, 'active', l.lease_until > now(),
        'started_at', l.started_at, 'lease_until', l.lease_until
      ) order by l.kind) from public.backup_run_leases l
    ), '[]'::jsonb),
    'active', exists (select 1 from public.backup_run_leases l where l.lease_until > now()),
    'last_runs', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id, 'kind', r.kind, 'status', r.status,
        'record', r.summary, 'created_at', r.created_at
      ) order by r.created_at desc)
      from (select * from public.backup_run_log order by created_at desc limit 8) r
    ), '[]'::jsonb)
  ) into v_result;
  return v_result;
end $$;

/**
 * Persist a secret-free run summary and write an audit entry. Called with the
 * ADMIN'S OWN RLS-scoped client so `current_profile_id()` is the real actor
 * and `manage_backups` is re-checked here, not just in the server action.
 */
create or replace function public.backup_record_run(
  p_kind   text,
  p_status text,
  p_record jsonb default '{}'::jsonb
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id     uuid;
  v_status text := coalesce(p_status, 'failed');
  v_record jsonb := coalesce(p_record, '{}'::jsonb);
begin
  if not public.has_permission('manage_backups') then
    raise exception 'You do not have permission to run backups.' using errcode = '42501';
  end if;
  if p_kind not in ('incremental', 'snapshot') then
    raise exception 'unknown backup kind';
  end if;
  if v_status not in ('verified', 'drained', 'idle', 'busy', 'failed', 'not_configured') then
    v_status := 'failed';
  end if;
  -- Defence in depth: a client (or a future code change) must never be able
  -- to smuggle a credential into the admin-visible log.
  if v_record::text ~* '(client_secret|refresh_token|credential_ciphertext|bearer |postgresql://|password|BEGIN [A-Z ]*PRIVATE KEY)' then
    v_record := jsonb_build_object('status', v_status, 'redacted', true);
  elsif length(v_record::text) > 3500 then
    v_record := jsonb_build_object('status', v_status, 'truncated', true);
  end if;

  insert into public.backup_run_log (kind, status, summary, actor)
  values (p_kind, v_status, v_record, public.current_profile_id())
  returning id into v_id;

  perform public.log_audit(
    'backup.process', 'backup_run', v_id::text,
    jsonb_build_object('kind', p_kind, 'status', v_status, 'verified', coalesce((v_record->>'verified')::int, 0)),
    false, null, 'admin'::public.moderation_visibility
  );
  return v_id;
end $$;

-- -----------------------------------------------------------------------------
-- 4. Grants — mirror migration 027's explicit, closed-by-default surface
-- -----------------------------------------------------------------------------

do $$
declare
  v_fn text;
begin
  foreach v_fn in array array[
    'backup_acquire_run_lease(text, text, integer)',
    'backup_release_run_lease(text, text)'
  ] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', v_fn);
    execute format('grant execute on function public.%s to service_role', v_fn);
  end loop;

  foreach v_fn in array array[
    'backup_admin_state()',
    'backup_record_run(text, text, jsonb)'
  ] loop
    execute format('revoke all on function public.%s from public, anon', v_fn);
    execute format('grant execute on function public.%s to authenticated, service_role', v_fn);
  end loop;
end $$;

comment on function public.backup_admin_state() is
  'Admin-only backup job state: queued/processing/verified/failed counts, batch retry state, active leases and recent run summaries. Never returns credentials or row images.';
comment on function public.backup_record_run(text, text, jsonb) is
  'Audited, permission-checked, secret-free log of an admin-triggered backup run.';

-- ==========================================================================
-- FILE 29/79  20261026000001_029_feed_realtime_delivery.sql
-- ==========================================================================

-- =============================================================================
-- Campus+ migration 029 — live delivery of new posts to already-open feeds
-- =============================================================================
-- Problem this fixes (no change to any row, policy or column):
--   A post was written and published correctly, but a feed that was already open
--   could not find out about it. Two configurations were missing, and only two:
--
--     1. `public.posts` was not a member of the `supabase_realtime` publication.
--        Realtime only ever *reads* the logical replication stream for tables in
--        that publication, so no Postgres Changes event for a post can exist
--        regardless of what any client subscribes to or what RLS allows. This was
--        deliberate once (migration 014 published only the messaging tables and
--        `notifications`) and simply never revisited when the feed grew a
--        client-side surface.
--     2. A private channel on a `feed:<profile id>` topic had no matching branch in
--        the `realtime.messages` read policy from migration 014, whose `case`
--        expression ends in `else false`. Every other branch there is for chat or
--        for the per-user fan-out channel the shell already owns.
--
-- What lands here:
--   1. `public.posts` is added to the publication — one table, the one the feed
--      needs. `comments`, `reactions`, `poll_votes`, `mentions` and every private
--      table stay out of the stream, so this does not widen what Realtime can read
--      beyond "a post row changed".
--   2. `campus_channels_read` gains a `feed` branch: the subscriber may receive
--      events on their own `feed:<uuid>` topic and nobody else's. The
--      `campus_channels_write` policy is left exactly as it is, so nothing can
--      broadcast on a feed topic at all.
--
-- What this does NOT do (and deliberately must not):
--   * It does not change row visibility. Delivery is authorised per subscriber by
--     the existing `posts` SELECT policies — `posts_select_visible` (published,
--     not deleted, active author, not blocked, not muted, community membership via
--     `can_view_community()`), `posts_select_author` and `posts_select_staff`. A
--     student therefore cannot receive a post they could not already fetch with the
--     same publishable key. Private channels additionally honour column-level
--     SELECT grants, and `public.posts` restricts no column from `authenticated`
--     beyond what those policies already expose.
--   * It adds no trigger, no outbox, no queue and no polling endpoint. The
--     application side of this change only *invalidates* a rendered feed and lets
--     the existing read path (`campus_feed()` and its hydration) decide what shows;
--     no payload generated here is ever rendered directly.
--   * It grants nothing new to `anon` (migration 014 revokes all of it) and no
--     service-role key is involved anywhere: Postgres Changes over a browser
--     channel with the publishable key is the whole mechanism.
--
-- Style: identical to migration 014 — guarded so it applies cleanly on plain
-- PostgreSQL where neither the publication nor `realtime.messages` exists, and
-- idempotent on re-apply.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- 1. Publication membership: posts rows are now on the stream
-- ----------------------------------------------------------------------------

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    begin
      alter publication supabase_realtime add table public.posts;
    exception
      when duplicate_object then null;
      -- The role applying migrations is not the table owner on every hosting
      -- topology. Say so, and say what to run, rather than aborting a deployment
      -- over a delivery optimisation the app degrades away from safely.
      when insufficient_privilege then
        raise notice 'Campus+: % is not the owner of public.posts. As the table owner or super user run: alter publication supabase_realtime add table public.posts;', current_user;
    end;
  else
    raise notice 'Campus+: no supabase_realtime publication here — Postgres Changes for posts are unavailable until the hosting platform creates it.';
  end if;
end $$;

-- ----------------------------------------------------------------------------
-- 2. Private-channel authorization for the per-student feed topic
-- ----------------------------------------------------------------------------
-- Topics in use, all owned by the subscriber:
--   conversation:<uuid>  random:<uuid>  user:<profile uuid>   (014)
--   feed:<profile uuid>                                      (this migration)
--
-- The topic is the subscriber's own profile id, so the policy is a
-- "you may join your own channel" check; which *rows* arrive is the table's
-- SELECT policy's decision above.

do $$
begin
  if to_regclass('realtime.messages') is null then
    raise notice 'Campus+: realtime.messages not present (plain Postgres). Skipping channel policies.';
    return;
  end if;

  execute $policy$
    drop policy if exists campus_channels_read on realtime.messages;
  $policy$;
  execute $policy$
    create policy campus_channels_read on realtime.messages
      for select to authenticated
      using (
        case split_part(realtime.topic(), ':', 1)
          when 'conversation' then
            public.can_access_conversation(public.safe_uuid(split_part(realtime.topic(), ':', 2)))
          when 'random' then
            public.can_access_random_session(public.safe_uuid(split_part(realtime.topic(), ':', 2)))
          when 'user' then
            public.safe_uuid(split_part(realtime.topic(), ':', 2)) = public.current_profile_id()
          when 'feed' then
            public.safe_uuid(split_part(realtime.topic(), ':', 2)) = public.current_profile_id()
          else false
        end
      );
  $policy$;
end $$;

-- ==========================================================================
-- FILE 30/79  20261027000001_030_random_channel_authorization.sql
-- ==========================================================================

-- =============================================================================
-- Campus+ migration 030 — Realtime channel authorization must not depend on a
-- client-executable cross-user oracle (stops the `42501` flood, closes the oracle)
-- =============================================================================
-- The symptom, from the production Postgres log: 815 of 1 000 exported entries are
--   `permission denied for function can_access_random_session`  (SQLSTATE 42501)
-- arriving roughly every 15 seconds while the site is in use.
--
-- Why that happens, end to end:
--
--   1. Migration 014 gave `realtime.messages` two private-channel policies whose
--      `case` expression includes a `random` branch:
--          when 'random' then public.can_access_random_session(<uuid from the topic>)
--      Realtime evaluates that expression as the subscribing role to decide whether
--      a `random:<session uuid>` channel may be joined or broadcast on.
--   2. `can_access_random_session(p_session, p_user)` was written in migration 010 as
--      an *internal* helper: SECURITY DEFINER, and with an **optional second
--      argument** so the Random RPCs could ask about somebody else. Its second
--      parameter makes it a session-membership oracle in the wrong hands — it answers
--      "is *this other profile* in *that private session*", and the base tables
--      deliberately have no participant policies (migration 022), so the function is
--      the only thing standing between a caller and that answer.
--   3. The Random Chat UI was retired in migration 023 — there is no `/random` route,
--      no nav entry, no `random:` subscription anywhere in the application any more
--      (verified: the only `.channel(` call sites are `conversation:`, `user:` and,
--      since 029, `feed:`). But a tab that was open before the retirement, a stale
--      Router/prefetch cache, or any other long-lived client keeps trying to *rejoin*
--      the private channel it already had. Realtime re-checks the policy on every
--      (re)subscribe, and the client reconnects on its own backoff — which is the
--      ~15-second cadence, and why it only appears in active periods.
--   4. On this project, the role evaluating the policy does not have EXECUTE on that
--      helper, so each check raises 42501 instead of returning `false`. The two are
--      worlds apart: a denial is an answer, an error is a log line, a failed
--      subscription, a retried socket, and — for the connection pool — churn. The
--      `08P01 unexpected EOF on standby connection` entries line up with the same
--      loop: a Realtime socket that never reaches SUBSCRIBED is torn down while its
--      replication connection is still being set up.
--
--      Why the grant is missing in production but present in the repository's history
--      is not something this file can settle: migration 018 explicitly grants EXECUTE
--      on every public function to `authenticated`, so a fresh database built from
--      these migrations does *not* reproduce the error. Migration 022 documents an
--      earlier change made directly against the live project, outside the migration
--      history, with exactly this signature. This migration therefore stops depending
--      on that grant either way, rather than re-asserting it.
--
-- What lands here, in order of consequence:
--
--   A. `can_access_own_random_session(p_session)` — a new, deliberately narrow
--      predicate for policy use: one argument, no way to ask about anybody but the
--      caller (`public.current_profile_id()` inside), SECURITY DEFINER because the
--      base tables have no participant policies, and `false` for a session that is no
--      longer active. Granted to `authenticated` and `service_role` explicitly, so a
--      channel check can never again fail on a missing grant for the retired topic.
--   B. Both `realtime.messages` policies now call A for the `random` branch. Nothing
--      else in them changes — the `conversation`, `user` and `feed` branches are
--      carried over verbatim from 014 and 029, including the `else false` fallback.
--   C. The oracle is closed: EXECUTE on `can_access_random_session(uuid, uuid)` is
--      revoked from `public` and `anon` and `authenticated`, and kept for
--      `service_role`. Internal callers are unaffected — every one of them is a
--      SECURITY DEFINER Random RPC (`end_random_session`, `random_session_state`,
--      `send_random_message`, `report_random_session`, and the retention pair
--      `purge_random_data` / `sweep_random_state`) running as the function owner, and
--      migration 010 wrote them that way precisely so the cross-user question could
--      stay server-side. Every one of those six was verified to be SECURITY DEFINER
--      before this revoke was written. The
--      application's own `lib/actions/random.js` never calls it (it reads the two
--      participant-safe views), which was verified before this revoke was written.
--
-- This migration grants nothing on any table, changes no policy on `random_*`
-- tables, does not delete retired data, and does not touch messaging, notifications
-- or the feed channel authorization from 029 beyond carrying its branch forward.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- A. The current-user-only predicate the policies may safely call
-- ----------------------------------------------------------------------------

create or replace function public.can_access_own_random_session(p_session uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
      from public.random_session_participants rp
      join public.random_sessions rs on rs.id = rp.session_id
     where rp.session_id = p_session
       and rp.user_id = public.current_profile_id()
       and rp.left_at is null
       and rs.status = 'active'
  );
$$;

comment on function public.can_access_own_random_session is
  'Realtime channel predicate for a random session: does the *calling* student still '
  'belong to this session. One argument by design — the two-argument '
  'can_access_random_session(p_session, p_user) can answer that question about any '
  'profile, so it stays an internal helper of the SECURITY DEFINER Random RPCs and is '
  'not executable by API roles. Returns false once the session is no longer active, '
  'which is also the point of the retired feature: no new channel access.';

-- Explicit, not inherited: the whole problem was a policy that depended on a grant
-- nobody owned. `anon` is excluded, as everywhere else in this schema.
revoke all on function public.can_access_own_random_session(uuid) from public, anon;
grant execute on function public.can_access_own_random_session(uuid) to authenticated, service_role;

-- Where a hosting platform authorizes private channels through its own role, that
-- role needs the *narrow* predicate and nothing else. Guarded, because it does not
-- exist on a plain Postgres install (and must not be created here).
do $$
begin
  if to_regrole('supabase_realtime') is not null then
    execute 'grant execute on function public.can_access_own_random_session(uuid) to supabase_realtime';
  end if;
end $$;

-- ----------------------------------------------------------------------------
-- B + C. The policies use A; the oracle stops being client-callable
-- ----------------------------------------------------------------------------

do $$
begin
  if to_regclass('realtime.messages') is null then
    raise notice 'Campus+: realtime.messages not present (plain Postgres). Skipping channel policies.';
    return;
  end if;

  -- Read (subscribe/receive). Identical to migration 029's except for the `random`
  -- branch, which now asks the current-user-only predicate.
  execute $policy$
    drop policy if exists campus_channels_read on realtime.messages;
  $policy$;
  execute $policy$
    create policy campus_channels_read on realtime.messages
      for select to authenticated
      using (
        case split_part(realtime.topic(), ':', 1)
          when 'conversation' then
            public.can_access_conversation(public.safe_uuid(split_part(realtime.topic(), ':', 2)))
          when 'random' then
            public.can_access_own_random_session(public.safe_uuid(split_part(realtime.topic(), ':', 2)))
          when 'user' then
            public.safe_uuid(split_part(realtime.topic(), ':', 2)) = public.current_profile_id()
          when 'feed' then
            public.safe_uuid(split_part(realtime.topic(), ':', 2)) = public.current_profile_id()
          else false
        end
      );
  $policy$;

  -- Write (broadcast/send). Same substitution; the policy is still insert-only for
  -- `authenticated`, so a feed or channel change remains a database fact rather than
  -- something a client asserts.
  execute $policy$
    drop policy if exists campus_channels_write on realtime.messages;
  $policy$;
  execute $policy$
    create policy campus_channels_write on realtime.messages
      for insert to authenticated
      with check (
        case split_part(realtime.topic(), ':', 1)
          when 'conversation' then
            public.can_access_conversation(public.safe_uuid(split_part(realtime.topic(), ':', 2)))
          when 'random' then
            public.can_access_own_random_session(public.safe_uuid(split_part(realtime.topic(), ':', 2)))
          when 'user' then
            public.safe_uuid(split_part(realtime.topic(), ':', 2)) = public.current_profile_id()
          else false
        end
      );
  $policy$;
end $$;

-- The oracle, off the RPC surface. PostgREST exposes every executable public function
-- to the roles that can execute it, so "not executable by `authenticated`" is what
-- makes it internal again; the Random RPCs call it as the function owner and are
-- unchanged.
revoke all on function public.can_access_random_session(uuid, uuid) from public, anon, authenticated;
grant execute on function public.can_access_random_session(uuid, uuid) to service_role;

comment on function public.can_access_random_session is
  'Internal: may be asked about any profile, which is exactly why it is not executable '
  'by API roles (migration 030). Callers are the SECURITY DEFINER Random RPCs in '
  'migration 010 and the service role. A policy or a client predicate must use '
  'can_access_own_random_session(uuid) instead.';

-- ==========================================================================
-- FILE 31/79  20261028000001_031_club_governance.sql
-- ==========================================================================

-- Campus+ migration 031 — club governance, requests and scoped management
-- =============================================================================
-- Clubs remain communities (kind = 'club'). This migration adds the directory
-- metadata and protected workflows the club screens use; it does not create a
-- parallel membership or permission system.
--
-- The important authority boundaries are:
--   * ordinary students can REQUEST a club, never INSERT one;
--   * platform staff with manage_clubs review requests and choose an active
--     initial administrator by username;
--   * approval is one transaction and one retry-safe RPC;
--   * club owners/moderators are authoritative only for their own club;
--   * imported clubs may have no administrator until a real account is assigned.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- Directory metadata on the existing communities table
-- ---------------------------------------------------------------------------

alter table public.communities
  add column organization_type text,
  add column verification_status text not null default 'pending',
  add column source_label text,
  add column source_url text,
  add column directory_aliases text not null default '',
  add column catalogue_key text,
  add column admin_assigned boolean not null default false;

alter table public.communities alter column created_by drop not null;

alter table public.communities
  add constraint communities_creator_required_for_groups
    check (kind = 'club' or created_by is not null),
  add constraint communities_organization_type_check
    check (
      organization_type is null
      or (
        kind = 'club'
        and organization_type in (
          'collegiate_team', 'technical_club', 'computing_community',
          'department_association', 'professional_chapter', 'creative_group',
          'service_organization', 'sports_group', 'platform_community'
        )
      )
    ),
  add constraint communities_verification_status_check
    check (verification_status in ('pending', 'source_checked')),
  add constraint communities_source_label_check
    check (source_label is null or length(source_label) <= 160),
  add constraint communities_source_url_check
    check (source_url is null or source_url ~ '^https?://'),
  add constraint communities_directory_aliases_check
    check (length(directory_aliases) <= 800),
  add constraint communities_catalogue_key_check
    check (catalogue_key is null or catalogue_key ~ '^[a-z0-9-]{3,80}$');

create unique index communities_catalogue_key_idx
  on public.communities (catalogue_key) where catalogue_key is not null;
create index communities_organization_type_idx
  on public.communities (organization_type, status) where kind = 'club';
create index communities_admin_assignment_idx
  on public.communities (admin_assigned) where kind = 'club';

comment on column public.communities.organization_type is
  'Controlled organization taxonomy for clubs. Independent of the original six discovery categories.';
comment on column public.communities.verification_status is
  'Directory-source state only. source_checked means a cited source lists the organization, not institutional endorsement of this page.';
comment on column public.communities.admin_assigned is
  'Derived from an active owner membership. False is an explicit admin-assignment-needed state, never a fabricated owner.';

-- Existing owner rows are real assignments. Imported rows are backfilled from
-- those rows rather than from created_by, which is provenance, not a club role.
update public.communities c
   set admin_assigned = exists (
     select 1 from public.community_members m
      where m.community_id = c.id and m.role = 'owner' and m.status = 'active'
   )
 where c.kind = 'club';

-- The creator trigger still serves ordinary communities and study groups. A
-- null-creator imported club, or a club created inside the protected workflow,
-- gets its owner from the explicit assignment step instead.
create or replace function public.add_community_owner()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if new.created_by is not null
     and not (new.kind = 'club' and public.in_system_context()) then
    insert into public.community_members (community_id, user_id, role, status)
    values (new.id, new.created_by, 'owner', 'active')
    on conflict (community_id, user_id) do update set role = 'owner', status = 'active';
  end if;
  return new;
end;
$$;

create or replace function public.sync_club_admin_assignment()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_community uuid := coalesce(new.community_id, old.community_id);
begin
  update public.communities c
     set admin_assigned = exists (
       select 1 from public.community_members m
        where m.community_id = c.id and m.role = 'owner' and m.status = 'active'
     )
   where c.id = v_community and c.kind = 'club';
  return coalesce(new, old);
end;
$$;

create trigger community_members_sync_club_admin
  after insert or update or delete on public.community_members
  for each row execute function public.sync_club_admin_assignment();

-- Extend the original counter/ownership guard to the new governance fields.
-- Club managers may edit their public profile, but cannot self-verify a source,
-- rewrite catalogue provenance, or toggle the derived administrator flag.
create or replace function public.guard_community_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_trusted_writer() then
    new.member_count := (
      select count(*) from public.community_members m
      where m.community_id = old.id and m.status = 'active'
    );
    new.post_count := (
      select count(*) from public.posts p
      where p.community_id = old.id and p.status = 'published' and p.deleted_at is null
    );
    new.created_by := old.created_by;
    new.kind := old.kind;
    new.is_official := old.is_official;
    new.approved_by := old.approved_by;
    new.approved_at := old.approved_at;
    new.admin_assigned := exists (
      select 1 from public.community_members m
      where m.community_id = old.id and m.role = 'owner' and m.status = 'active'
    );
    if not (old.kind = 'club' and public.has_permission('manage_clubs')) then
      new.verification_status := old.verification_status;
      new.source_label := old.source_label;
      new.source_url := old.source_url;
      new.directory_aliases := old.directory_aliases;
      new.catalogue_key := old.catalogue_key;
    end if;
  end if;
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- One scoped predicate, built from the existing membership/global permissions
-- ---------------------------------------------------------------------------

create or replace function public.can_manage_club(p_club uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.communities c
     where c.id = p_club
       and c.kind = 'club'
       and (
         public.is_community_moderator(c.id)
         or public.has_permission('manage_clubs')
         or public.has_permission('moderate_communities')
         or public.has_permission('moderate_all')
       )
  );
$$;

comment on function public.can_manage_club(uuid) is
  'Current actor may manage this specific club through its owner/moderator membership or an explicit global club/community permission.';

-- ---------------------------------------------------------------------------
-- Student club-creation requests (not clubs, not memberships)
-- ---------------------------------------------------------------------------

create table public.club_creation_requests (
  id                       uuid primary key default gen_random_uuid(),
  requester_id             uuid not null references public.profiles (id) on delete cascade,
  name                     text not null check (length(btrim(name)) between 3 and 80),
  slug                     text not null check (slug ~ '^[a-z0-9-]{3,60}$'),
  description              text not null check (length(description) between 10 and 1000),
  subject                  text check (subject is null or length(subject) <= 120),
  club_category            text not null check (club_category in ('Technical', 'Cultural', 'Sports', 'Arts', 'Entrepreneurship', 'Social')),
  organization_type        text not null check (organization_type in (
                             'collegiate_team', 'technical_club', 'computing_community',
                             'department_association', 'professional_chapter', 'creative_group',
                             'service_organization', 'sports_group', 'platform_community')),
  recruitment_info         text check (recruitment_info is null or length(recruitment_info) <= 1000),
  meeting_info             text check (meeting_info is null or length(meeting_info) <= 200),
  contact_info             text check (contact_info is null or length(contact_info) <= 200),
  external_url             text check (external_url is null or external_url ~ '^https?://'),
  source_label             text check (source_label is null or length(source_label) <= 160),
  source_url               text check (source_url is null or source_url ~ '^https?://'),
  proposed_admin_username  text check (proposed_admin_username is null or proposed_admin_username ~ '^[a-z0-9_]{3,24}$'),
  status                   text not null default 'pending' check (status in ('pending', 'approved', 'rejected', 'withdrawn')),
  reviewed_by              uuid references public.profiles (id) on delete set null,
  reviewed_at              timestamptz,
  review_note              text check (review_note is null or length(review_note) <= 1000),
  community_id             uuid unique references public.communities (id) on delete set null,
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now()
);

create index club_creation_requests_queue_idx
  on public.club_creation_requests (status, created_at);
create index club_creation_requests_requester_idx
  on public.club_creation_requests (requester_id, created_at desc);
create unique index club_creation_requests_one_pending_slug_idx
  on public.club_creation_requests (slug) where status = 'pending';

create trigger club_creation_requests_touch before update on public.club_creation_requests
  for each row execute function public.touch_updated_at();

alter table public.club_creation_requests enable row level security;

create policy club_creation_requests_select_own on public.club_creation_requests
  for select to authenticated using (requester_id = public.current_profile_id());
create policy club_creation_requests_select_admin on public.club_creation_requests
  for select to authenticated using (public.has_permission('manage_clubs'));
create policy club_creation_requests_insert_own on public.club_creation_requests
  for insert to authenticated with check (
    requester_id = public.current_profile_id()
    and public.is_active_user()
    and status = 'pending'
    and reviewed_by is null
    and reviewed_at is null
    and community_id is null
  );
-- No client UPDATE policy: withdrawal and review are protected RPCs below.

create or replace function public.guard_club_creation_request_insert()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  new.slug := lower(btrim(new.slug));
  new.proposed_admin_username := nullif(lower(btrim(coalesce(new.proposed_admin_username, ''))), '');
  if not public.is_trusted_writer() then
    new.requester_id := public.current_profile_id();
    new.status := 'pending';
    new.reviewed_by := null;
    new.reviewed_at := null;
    new.community_id := null;
  end if;
  if exists (select 1 from public.communities c where c.slug = new.slug) then
    raise exception 'A community or club already uses that link.' using errcode = '22023';
  end if;
  return new;
end;
$$;

create trigger club_creation_requests_guard_insert
  before insert on public.club_creation_requests
  for each row execute function public.guard_club_creation_request_insert();

-- Notify every distinct active manage_clubs holder. No email, push or private
-- message is created; this is the existing notifications table.
create or replace function public.notify_club_request_admins()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_admin uuid;
begin
  for v_admin in
    select distinct ur.user_id
      from public.user_roles ur
      join public.role_permissions rp on rp.role_key = ur.role_key
     where rp.permission_key = 'manage_clubs'
       and public.is_active_profile(ur.user_id)
  loop
    perform public.notify_user(
      v_admin, 'club_activity', 'Club request: ' || new.name,
      'Review the request and choose an initial club administrator.',
      'club_request', new.id::text, '/admin?tab=clubs'
    );
  end loop;
  return new;
end;
$$;

create trigger club_creation_requests_notify_admin
  after insert on public.club_creation_requests
  for each row execute function public.notify_club_request_admins();

-- ---------------------------------------------------------------------------
-- Resolve and validate an initial administrator
-- ---------------------------------------------------------------------------

create or replace function public.resolve_club_admin(p_username text)
returns uuid
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
begin
  select p.id into v_id
    from public.profiles p
   where p.username = lower(btrim(coalesce(p_username, '')))
     and public.account_status_of(p.id) = 'active'::public.account_status;
  if v_id is null then
    raise exception 'Choose an active Campus+ username for the initial club administrator.' using errcode = '22023';
  end if;
  if public.role_rank(v_id) >= 10 or exists (
    select 1 from public.user_roles ur
    join public.role_permissions rp on rp.role_key = ur.role_key
    where ur.user_id = v_id
      and (ur.expires_at is null or ur.expires_at > now())
      and rp.permission_key in (
        'manage_clubs', 'moderate_all', 'manage_users', 'assign_roles',
        'manage_roles', 'manage_permissions', 'manage_role_authority', 'manage_backups'
      )
  ) then
    raise exception 'Choose an active student account without platform-wide administrative privileges.' using errcode = '22023';
  end if;
  return v_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Protected club creation and request approval
-- ---------------------------------------------------------------------------

create or replace function public.create_club_with_admin(
  p_admin_username text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_admin uuid;
  v_club uuid;
  v_slug text;
begin
  if not public.has_permission('manage_clubs') then
    raise exception 'Only Campus+ club administrators can create a club.' using errcode = '42501';
  end if;
  v_admin := public.resolve_club_admin(p_admin_username);
  v_slug := lower(btrim(coalesce(p_payload->>'slug', '')));
  perform set_config('campus.system_context', 'on', true);

  insert into public.communities (
    kind, name, slug, description, subject, club_category, organization_type,
    recruitment_info, meeting_info, contact_info, external_url, visibility,
    join_policy, status, is_official, created_by, approved_by, approved_at,
    member_count, verification_status, source_label, source_url
  ) values (
    'club', p_payload->>'name', v_slug, p_payload->>'description',
    nullif(p_payload->>'subject', ''), p_payload->>'club_category', p_payload->>'organization_type',
    nullif(p_payload->>'recruitment_info', ''), nullif(p_payload->>'meeting_info', ''),
    nullif(p_payload->>'contact_info', ''), nullif(p_payload->>'external_url', ''),
    coalesce(p_payload->>'visibility', 'campus')::public.visibility_level,
    coalesce(p_payload->>'join_policy', 'request'),
    'published', true, v_actor, v_actor, now(), 0,
    case when p_payload->>'verification_status' = 'source_checked' then 'source_checked' else 'pending' end,
    nullif(p_payload->>'source_label', ''), nullif(p_payload->>'source_url', '')
  ) returning id into v_club;

  insert into public.community_members (community_id, user_id, role, status)
  values (v_club, v_admin, 'owner', 'active');

  perform public.log_audit('club.created', 'club', v_club::text,
    jsonb_build_object('admin_username', lower(btrim(p_admin_username))), true, null, 'admin');
  perform public.notify_user(v_admin, 'club_activity', 'You are now a club administrator',
    'Open the club management workspace to review its details and membership.',
    'club', v_club::text, '/clubs/' || v_club::text || '/manage');

  return jsonb_build_object('ok', true, 'id', v_club, 'slug', v_slug, 'admin_id', v_admin);
end;
$$;

create or replace function public.approve_club_request(
  p_request uuid,
  p_admin_username text,
  p_review_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_request public.club_creation_requests;
  v_admin uuid;
  v_club uuid;
begin
  if not public.has_permission('manage_clubs') then
    raise exception 'Only Campus+ club administrators can review club requests.' using errcode = '42501';
  end if;

  select * into v_request from public.club_creation_requests where id = p_request for update;
  if v_request.id is null then
    raise exception 'That club request could not be found.' using errcode = '22023';
  end if;
  -- A retry after a committed approval returns the same club and does not
  -- insert another community, membership, notification or audit row.
  if v_request.status = 'approved' and v_request.community_id is not null then
    return jsonb_build_object('ok', true, 'id', v_request.community_id, 'slug',
      (select slug from public.communities where id = v_request.community_id), 'idempotent', true);
  end if;
  if v_request.status <> 'pending' then
    raise exception 'That club request has already been reviewed.' using errcode = '22023';
  end if;

  v_admin := public.resolve_club_admin(p_admin_username);
  perform set_config('campus.system_context', 'on', true);

  insert into public.communities (
    kind, name, slug, description, subject, club_category, organization_type,
    recruitment_info, meeting_info, contact_info, external_url, visibility,
    join_policy, status, is_official, created_by, approved_by, approved_at,
    member_count, verification_status, source_label, source_url
  ) values (
    'club', v_request.name, v_request.slug, v_request.description, v_request.subject,
    v_request.club_category, v_request.organization_type, v_request.recruitment_info,
    v_request.meeting_info, v_request.contact_info, v_request.external_url,
    'campus', 'request', 'published', true, v_actor, v_actor, now(), 0,
    'pending', v_request.source_label, v_request.source_url
  ) returning id into v_club;

  insert into public.community_members (community_id, user_id, role, status)
  values (v_club, v_admin, 'owner', 'active');

  update public.club_creation_requests
     set status = 'approved', reviewed_by = v_actor, reviewed_at = now(),
         review_note = left(nullif(btrim(coalesce(p_review_note, '')), ''), 1000),
         community_id = v_club
   where id = v_request.id;

  perform public.log_audit('club.request_approved', 'club', v_club::text,
    jsonb_build_object('request_id', v_request.id, 'requester_id', v_request.requester_id,
                       'admin_username', lower(btrim(p_admin_username))), true,
    nullif(btrim(coalesce(p_review_note, '')), ''), 'admin');
  perform public.notify_user(v_request.requester_id, 'club_activity',
    'Your club request was approved', v_request.name || ' now has a club page.',
    'club', v_club::text, '/clubs/' || v_club::text);
  perform public.notify_user(v_admin, 'club_activity', 'You are now a club administrator',
    v_request.name || ' was assigned to you by a Campus+ club administrator.',
    'club', v_club::text, '/clubs/' || v_club::text || '/manage');

  return jsonb_build_object('ok', true, 'id', v_club, 'slug', v_request.slug, 'admin_id', v_admin);
end;
$$;

create or replace function public.reject_club_request(
  p_request uuid,
  p_review_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_request public.club_creation_requests;
begin
  if not public.has_permission('manage_clubs') then
    raise exception 'Only Campus+ club administrators can review club requests.' using errcode = '42501';
  end if;
  select * into v_request from public.club_creation_requests where id = p_request for update;
  if v_request.id is null then
    raise exception 'That club request could not be found.' using errcode = '22023';
  end if;
  if v_request.status = 'rejected' then
    return jsonb_build_object('ok', true, 'status', 'rejected', 'idempotent', true);
  end if;
  if v_request.status <> 'pending' then
    raise exception 'That club request has already been reviewed.' using errcode = '22023';
  end if;

  update public.club_creation_requests
     set status = 'rejected', reviewed_by = v_actor, reviewed_at = now(),
         review_note = left(nullif(btrim(coalesce(p_review_note, '')), ''), 1000)
   where id = v_request.id;

  perform public.log_audit('club.request_rejected', 'club_request', v_request.id::text,
    jsonb_build_object('requester_id', v_request.requester_id), true,
    nullif(btrim(coalesce(p_review_note, '')), ''), 'admin');
  perform public.notify_user(v_request.requester_id, 'club_activity',
    'Your club request was not approved',
    coalesce(nullif(btrim(coalesce(p_review_note, '')), ''), 'You can withdraw the request and submit a revised proposal.'),
    'club_request', v_request.id::text, '/clubs/request');

  return jsonb_build_object('ok', true, 'status', 'rejected');
end;
$$;

create or replace function public.withdraw_club_request(p_request uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_request public.club_creation_requests;
begin
  select * into v_request from public.club_creation_requests where id = p_request for update;
  if v_request.id is null or v_request.requester_id <> public.current_profile_id() then
    raise exception 'That club request could not be found.' using errcode = '42501';
  end if;
  if v_request.status = 'withdrawn' then
    return jsonb_build_object('ok', true, 'status', 'withdrawn', 'idempotent', true);
  end if;
  if v_request.status <> 'pending' then
    raise exception 'Only a pending club request can be withdrawn.' using errcode = '22023';
  end if;
  update public.club_creation_requests set status = 'withdrawn', reviewed_at = now() where id = v_request.id;
  return jsonb_build_object('ok', true, 'status', 'withdrawn');
end;
$$;

-- ---------------------------------------------------------------------------
-- Initial admin assignment for imported/unassigned clubs
-- ---------------------------------------------------------------------------

create or replace function public.assign_club_admin(p_club uuid, p_admin_username text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_admin uuid;
  v_name text;
begin
  if not public.has_permission('manage_clubs') then
    raise exception 'Only Campus+ club administrators can assign an initial club admin.' using errcode = '42501';
  end if;
  select name into v_name from public.communities where id = p_club and kind = 'club';
  if v_name is null then
    raise exception 'That club could not be found.' using errcode = '22023';
  end if;
  if exists (
    select 1 from public.community_members
     where community_id = p_club and role = 'owner' and status = 'active'
  ) then
    raise exception 'This club already has an administrator.' using errcode = '22023';
  end if;

  v_admin := public.resolve_club_admin(p_admin_username);
  insert into public.community_members (community_id, user_id, role, status)
  values (p_club, v_admin, 'owner', 'active')
  on conflict (community_id, user_id) do update set role = 'owner', status = 'active';

  perform public.log_audit('club.admin_assigned', 'club', p_club::text,
    jsonb_build_object('admin_username', lower(btrim(p_admin_username))), true, null, 'admin');
  perform public.notify_user(v_admin, 'club_activity', 'You are now a club administrator',
    v_name || ' was assigned to you by a Campus+ club administrator.',
    'club', p_club::text, '/clubs/' || p_club::text || '/manage');
  return jsonb_build_object('ok', true, 'id', p_club, 'admin_id', v_admin);
end;
$$;

-- ---------------------------------------------------------------------------
-- Membership request and decision workflow (one row path, atomic decisions)
-- ---------------------------------------------------------------------------

create or replace function public.join_community(p_community uuid, p_message text default null)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_community public.communities;
  v_existing public.community_members;
  v_request public.community_join_requests;
  v_manager uuid;
begin
  if not public.is_active_profile(v_actor) then
    raise exception 'Your account cannot join communities right now.' using errcode = '42501';
  end if;
  select * into v_community from public.communities where id = p_community and status = 'published';
  if v_community.id is null or not public.can_view_community(p_community) then
    raise exception 'That community could not be found.' using errcode = '22023';
  end if;
  if v_community.kind = 'club' and not v_community.admin_assigned then
    raise exception 'Membership opens after a club administrator is assigned.' using errcode = '22023';
  end if;

  select * into v_existing from public.community_members
   where community_id = p_community and user_id = v_actor;
  if v_existing.id is not null and v_existing.status = 'active' then
    return jsonb_build_object('ok', true, 'status', 'active', 'idempotent', true);
  end if;

  select * into v_request from public.community_join_requests
   where community_id = p_community and user_id = v_actor;
  if v_request.id is not null and v_request.status = 'pending' then
    return jsonb_build_object('ok', true, 'status', 'pending', 'idempotent', true);
  end if;

  if v_community.join_policy = 'open' then
    insert into public.community_members (community_id, user_id, role, status)
    values (p_community, v_actor, 'member', 'active')
    on conflict (community_id, user_id) do update set status = 'active';
    return jsonb_build_object('ok', true, 'status', 'active');
  end if;
  if v_community.join_policy <> 'request' then
    raise exception 'This community is invite only.' using errcode = '42501';
  end if;

  insert into public.community_join_requests (community_id, user_id, message, status)
  values (p_community, v_actor, left(nullif(btrim(coalesce(p_message, '')), ''), 300), 'pending')
  on conflict (community_id, user_id) do update
    set message = excluded.message, status = 'pending', decided_by = null, decided_at = null, created_at = now();
  delete from public.community_members
   where community_id = p_community and user_id = v_actor and status = 'pending';

  for v_manager in
    select user_id from public.community_members
     where community_id = p_community and status = 'active' and role in ('owner', 'moderator')
  loop
    perform public.notify_user(v_manager,
      (case when v_community.kind = 'club' then 'club_activity' else 'community_activity' end)::public.notification_type,
      'New join request for ' || v_community.name,
      'Open the membership workspace to review the request.',
      case when v_community.kind = 'club' then 'club' else 'community' end,
      p_community::text,
      case when v_community.kind = 'club' then '/clubs/' || p_community::text || '/manage?view=members'
           else '/communities/' || v_community.slug end);
  end loop;
  return jsonb_build_object('ok', true, 'status', 'pending');
end;
$$;

create or replace function public.decide_community_join_request(p_request uuid, p_decision text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_request public.community_join_requests;
  v_kind public.community_kind;
  v_slug text;
begin
  if p_decision not in ('approved', 'rejected') then
    raise exception 'Choose approve or reject.' using errcode = '22023';
  end if;
  select * into v_request from public.community_join_requests where id = p_request for update;
  if v_request.id is null then
    raise exception 'That join request could not be found.' using errcode = '22023';
  end if;
  select kind, slug into v_kind, v_slug from public.communities where id = v_request.community_id;
  if not (
    public.is_community_moderator(v_request.community_id)
    or public.has_permission('manage_clubs') and v_kind = 'club'
    or public.has_permission('moderate_communities')
    or public.has_permission('moderate_all')
  ) then
    raise exception 'Only this community''s managers can decide its requests.' using errcode = '42501';
  end if;
  if v_request.status = p_decision::public.join_request_status then
    return jsonb_build_object('ok', true, 'status', v_request.status, 'idempotent', true);
  end if;
  if v_request.status <> 'pending' then
    raise exception 'That join request has already been decided.' using errcode = '22023';
  end if;

  update public.community_join_requests
     set status = p_decision::public.join_request_status, decided_by = v_actor, decided_at = now()
   where id = v_request.id;
  if p_decision = 'approved' then
    insert into public.community_members (community_id, user_id, role, status)
    values (v_request.community_id, v_request.user_id, 'member', 'active')
    on conflict (community_id, user_id) do update set status = 'active';
  else
    delete from public.community_members
     where community_id = v_request.community_id and user_id = v_request.user_id and status = 'pending';
  end if;

  perform public.notify_user(v_request.user_id,
    (case when v_kind = 'club' then 'club_activity' else 'community_activity' end)::public.notification_type,
    'Your join request was ' || p_decision,
    case when p_decision = 'approved' then 'You can now open the community feed.' else 'The club or community manager reviewed your request.' end,
    case when v_kind = 'club' then 'club' else 'community' end,
    v_request.community_id::text,
    case when v_kind = 'club' then '/clubs/' || v_request.community_id::text else '/communities/' || v_slug end);

  if v_kind = 'club' then
    perform public.log_audit('club.join_request_' || p_decision, 'club', v_request.community_id::text,
      jsonb_build_object('request_id', v_request.id, 'member_id', v_request.user_id), false, null, 'private');
  end if;
  return jsonb_build_object('ok', true, 'status', p_decision);
end;
$$;

-- Decisions go through the atomic RPC, not a client update followed by a second
-- membership write. Existing SELECT and cancellation policies remain intact.
drop policy if exists community_join_requests_decide on public.community_join_requests;
revoke update on public.community_join_requests from authenticated, anon;

create or replace function public.set_community_member_role(
  p_community uuid, p_member uuid, p_role public.community_role
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_old public.community_role;
  v_kind public.community_kind;
begin
  if p_role not in ('member', 'moderator') or p_member = v_actor then
    raise exception 'Choose another member and a valid club role.' using errcode = '22023';
  end if;
  select kind into v_kind from public.communities where id = p_community;
  if not (
    public.has_permission('manage_clubs') and v_kind = 'club'
    or exists (
      select 1 from public.community_members m
       where m.community_id = p_community and m.user_id = v_actor
         and m.role = 'owner' and m.status = 'active'
    )
  ) then
    raise exception 'Only the owner can change member roles.' using errcode = '42501';
  end if;

  update public.community_members set role = p_role
   where community_id = p_community and user_id = p_member and status = 'active' and role <> 'owner'
  returning role into v_old;
  if not found then
    raise exception 'That membership could not be found or is the owner.' using errcode = '22023';
  end if;
  if v_kind = 'club' then
    perform public.log_audit('club.member_role_changed', 'club', p_community::text,
      jsonb_build_object('member_id', p_member, 'role', p_role), false, null, 'private');
    perform public.notify_user(p_member, 'club_activity', 'Your club role changed',
      'A club owner changed your role to ' || p_role || '.', 'club', p_community::text,
      '/clubs/' || p_community::text || '/manage');
  end if;
  return jsonb_build_object('ok', true, 'role', p_role);
end;
$$;

create or replace function public.remove_community_member(p_community uuid, p_member uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_kind public.community_kind;
begin
  if p_member = public.current_profile_id() then
    raise exception 'Use Leave to leave this community.' using errcode = '22023';
  end if;
  select kind into v_kind from public.communities where id = p_community;
  if not (
    public.is_community_moderator(p_community)
    or public.has_permission('manage_clubs') and v_kind = 'club'
    or public.has_permission('moderate_communities')
    or public.has_permission('moderate_all')
  ) then
    raise exception 'Only this community''s managers can remove members.' using errcode = '42501';
  end if;
  delete from public.community_members
   where community_id = p_community and user_id = p_member and role <> 'owner';
  if not found then
    raise exception 'That member could not be found, or owners cannot be removed.' using errcode = '22023';
  end if;
  if v_kind = 'club' then
    perform public.log_audit('club.member_removed', 'club', p_community::text,
      jsonb_build_object('member_id', p_member), false, null, 'private');
  end if;
  return jsonb_build_object('ok', true);
end;
$$;

-- Direct database writes get the same owner protections as the RPCs. A
-- moderator must never demote/delete an owner or move a membership to a club.
create or replace function public.guard_community_membership_write()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if public.is_trusted_writer() then
    return coalesce(new, old);
  end if;
  if tg_op = 'DELETE' then
    if old.role = 'owner' and public.community_kind_of(old.community_id) = 'club' then
      raise exception 'A club owner membership cannot be removed directly.' using errcode = '42501';
    end if;
    return old;
  end if;
  new.community_id := old.community_id;
  new.user_id := old.user_id;
  new.joined_at := old.joined_at;
  if old.role = 'owner' and new.role <> 'owner'
     and public.community_kind_of(old.community_id) = 'club' then
    raise exception 'A club owner cannot be demoted directly.' using errcode = '42501';
  end if;
  return new;
end;
$$;

create trigger community_members_guard_write
  before update or delete on public.community_members
  for each row execute function public.guard_community_membership_write();

-- Replace the original role guard with the same check plus owner protection;
-- the write guard above runs first, then this validates who may grant roles.
create or replace function public.guard_community_role_change()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if public.is_trusted_writer() then return new; end if;
  if new.role is distinct from old.role then
    if not public.is_community_moderator(new.community_id)
       and not (public.has_permission('manage_clubs') and public.community_kind_of(new.community_id) = 'club') then
      raise exception 'Only community owners and moderators can change member roles.' using errcode = '42501';
    end if;
    if new.role = 'owner' and not exists (
      select 1 from public.community_members m
       where m.community_id = new.community_id and m.user_id = public.current_profile_id()
         and m.role = 'owner' and m.status = 'active'
    ) and not (public.has_permission('manage_clubs') and public.community_kind_of(new.community_id) = 'club') then
      raise exception 'Only an owner can transfer ownership.' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

-- Club inserts use create_club_with_admin / approve_club_request. Ordinary
-- communities and study groups keep the existing self-creation path.
drop policy if exists communities_insert_own on public.communities;
create policy communities_insert_own on public.communities
  for insert to authenticated with check (
    public.is_active_user()
    and created_by = public.current_profile_id()
    and kind in ('community', 'study_group')
    and public.has_permission('create_communities')
  );

-- ---------------------------------------------------------------------------
-- Club profile update through one scoped, audited RPC
-- ---------------------------------------------------------------------------

create or replace function public.update_club_profile(p_club uuid, p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.can_manage_club(p_club) then
    raise exception 'Only this club''s managers can edit it.' using errcode = '42501';
  end if;
  update public.communities set
    name = p_payload->>'name', description = p_payload->>'description',
    subject = nullif(p_payload->>'subject', ''), club_category = p_payload->>'club_category',
    organization_type = p_payload->>'organization_type',
    recruitment_info = nullif(p_payload->>'recruitment_info', ''),
    meeting_info = nullif(p_payload->>'meeting_info', ''),
    contact_info = nullif(p_payload->>'contact_info', ''),
    external_url = nullif(p_payload->>'external_url', ''),
    visibility = coalesce(p_payload->>'visibility', 'campus')::public.visibility_level,
    join_policy = coalesce(p_payload->>'join_policy', 'request')
   where id = p_club and kind = 'club';
  if not found then raise exception 'That club could not be found.' using errcode = '22023'; end if;
  perform public.log_audit('club.profile_updated', 'club', p_club::text, '{}'::jsonb, false, null, 'private');
  return jsonb_build_object('ok', true, 'id', p_club);
end;
$$;

-- Club-scoped audit entries are readable by that club's managers and global
-- staff, never by unrelated members. No direct-message data is involved.
create policy audit_logs_select_club_managers on public.audit_logs
  for select to authenticated
  using (target_type = 'club' and target_id is not null and public.can_manage_club(target_id));

-- Extend the existing audit writer only for scoped club lifecycle entries.
create or replace function public.log_audit(
  p_action text, p_target_type text default null, p_target_id text default null,
  p_metadata jsonb default null, p_also_moderation boolean default false,
  p_reason text default null, p_visibility public.moderation_visibility default 'staff'
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_id uuid;
  v_is_staff boolean;
  v_is_club_action boolean := false;
begin
  if v_actor is null and not public.is_trusted_writer() then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  v_is_staff := public.is_staff() or public.is_trusted_writer();
  if p_target_type = 'club' and p_target_id ~ '^[0-9a-f-]{36}$'
     and p_action in ('club.join_request_approved', 'club.join_request_rejected',
                      'club.member_role_changed', 'club.member_removed', 'club.profile_updated') then
    v_is_club_action := public.can_manage_club(p_target_id::uuid);
  end if;

  if not v_is_staff and not v_is_club_action
     and p_action not like 'account.%' and p_action not like 'user.%'
     and p_action not like 'content.self_%'
     and p_action <> 'marketplace.completed' then
    raise exception 'You do not have permission to write audit entries.' using errcode = '42501';
  end if;

  insert into public.audit_logs (actor_user_id, action, target_type, target_id, metadata, visibility)
  values (
    v_actor, left(p_action, 80), left(p_target_type, 60),
    case when p_target_id ~ '^[0-9a-f-]{36}$' then p_target_id::uuid else null end,
    coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object(
      'reason', p_reason, 'actor_username', (select username from public.profiles where id = v_actor)),
    case when v_is_staff then p_visibility else 'private'::public.moderation_visibility end
  ) returning id into v_id;

  if p_also_moderation and v_is_staff then
    insert into public.moderation_actions (moderator_id, report_id, action, target_type, target_id, note)
    values (v_actor, nullif(p_metadata->>'report_id', '')::uuid, left(p_action, 60),
      left(p_target_type, 60),
      case when p_target_id ~ '^[0-9a-f-]{36}$' then p_target_id::uuid else null end,
      left(p_reason, 1000));
  end if;
  return v_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Club-linked events and opportunities verify the SPECIFIC club
-- ---------------------------------------------------------------------------

alter table public.opportunities add column club_id uuid references public.communities (id) on delete set null;
create index opportunities_club_idx on public.opportunities (club_id);

create or replace function public.guard_club_linked_content()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if public.is_trusted_writer() or new.club_id is null then return new; end if;
  if not exists (select 1 from public.communities c where c.id = new.club_id and c.kind = 'club') then
    raise exception 'Content can only be linked to a club.' using errcode = '22023';
  end if;
  if tg_table_name = 'events'
     and (public.has_permission('manage_events') or public.has_permission('moderate_all')) then return new; end if;
  if tg_table_name = 'opportunities'
     and (public.has_permission('manage_official_content') or public.has_permission('moderate_all')) then return new; end if;
  if not public.can_manage_club(new.club_id) then
    raise exception 'Only this club''s managers can link content to it.' using errcode = '42501';
  end if;
  return new;
end;
$$;

create trigger events_guard_club_link before insert or update on public.events
  for each row execute function public.guard_club_linked_content();
create trigger opportunities_guard_club_link before insert or update on public.opportunities
  for each row execute function public.guard_club_linked_content();

-- Managers can see their club's submitted drafts even when another manager
-- authored them. Ordinary viewers keep the existing published/author policies.
create policy events_select_club_managers on public.events
  for select to authenticated
  using (club_id is not null and public.can_manage_club(club_id));
create policy opportunities_select_club_managers on public.opportunities
  for select to authenticated
  using (club_id is not null and public.can_manage_club(club_id));

-- ---------------------------------------------------------------------------
-- Grants: metadata verification is staff-only; lifecycle RPCs are executable
-- by authenticated users because every function checks its own authority.
-- ---------------------------------------------------------------------------

grant update (organization_type) on public.communities to authenticated;
grant update (club_id) on public.opportunities to authenticated;
revoke update on public.club_creation_requests from authenticated, anon;

revoke all on function public.can_manage_club(uuid) from public, anon;
revoke all on function public.resolve_club_admin(text) from public, anon;
grant execute on function public.can_manage_club(uuid) to authenticated, service_role;
grant execute on function public.resolve_club_admin(text) to service_role;

-- Migration 018's default grants cover the other new functions. Make the
-- anonymous boundary explicit for the state-changing entry points as well.
revoke all on function public.create_club_with_admin(text, jsonb) from public, anon;
revoke all on function public.approve_club_request(uuid, text, text) from public, anon;
revoke all on function public.reject_club_request(uuid, text) from public, anon;
revoke all on function public.withdraw_club_request(uuid) from public, anon;
revoke all on function public.assign_club_admin(uuid, text) from public, anon;
revoke all on function public.join_community(uuid, text) from public, anon;
revoke all on function public.decide_community_join_request(uuid, text) from public, anon;
revoke all on function public.set_community_member_role(uuid, uuid, public.community_role) from public, anon;
revoke all on function public.remove_community_member(uuid, uuid) from public, anon;
revoke all on function public.update_club_profile(uuid, jsonb) from public, anon;

grant execute on function public.create_club_with_admin(text, jsonb) to authenticated, service_role;
grant execute on function public.approve_club_request(uuid, text, text) to authenticated, service_role;
grant execute on function public.reject_club_request(uuid, text) to authenticated, service_role;
grant execute on function public.withdraw_club_request(uuid) to authenticated, service_role;
grant execute on function public.assign_club_admin(uuid, text) to authenticated, service_role;
grant execute on function public.join_community(uuid, text) to authenticated, service_role;
grant execute on function public.decide_community_join_request(uuid, text) to authenticated, service_role;
grant execute on function public.set_community_member_role(uuid, uuid, public.community_role) to authenticated, service_role;
grant execute on function public.remove_community_member(uuid, uuid) to authenticated, service_role;
grant execute on function public.update_club_profile(uuid, jsonb) to authenticated, service_role;

