 '', null, null, 'pending'),

-- Campus+'s own club. Platform identity is not an external endorsement claim.
('campus-plus', 'Campus+ Club', 'campus-plus', 'Social', 'platform_community',
 'The Campus+ club for directory feedback, product updates, and student community coordination. Membership and activities will be managed here once an administrator is assigned.',
 'Campus+|Campus Plus|Campus Plus Club', 'Campus+ platform directory', null, 'source_checked');

-- Reconcile in one migration transaction. Existing rows are matched by their
-- catalogue key, stable slug, exact name, then a known alias (GDSC/GDG, OWASP).
-- Only provenance fields are enriched; administrator edits remain authoritative.
do $$
declare
  v_seed club_catalogue_seed%rowtype;
  v_id uuid;
begin
  perform set_config('campus.system_context', 'on', true);
  for v_seed in select * from club_catalogue_seed order by catalogue_key loop
    v_id := null;
    select c.id into v_id from public.communities c
     where c.catalogue_key = v_seed.catalogue_key and c.kind = 'club' limit 1;
    if v_id is null then
      select c.id into v_id from public.communities c
       where c.slug = v_seed.slug and c.kind = 'club' limit 1;
    end if;
    if v_id is null then
      select c.id into v_id from public.communities c
       where lower(c.name) = lower(v_seed.name) and c.kind = 'club' limit 1;
    end if;
    if v_id is null and v_seed.aliases <> '' then
      select c.id into v_id from public.communities c
       where c.kind = 'club'
         and lower(c.name) in (select lower(trim(a)) from unnest(string_to_array(v_seed.aliases, '|')) a)
       order by c.created_at, c.id limit 1;
    end if;

    if v_id is null then
      insert into public.communities (
        kind, name, slug, description, club_category, organization_type,
        visibility, join_policy, status, is_official, created_by, approved_by,
        approved_at, member_count, admin_assigned, verification_status,
        source_label, source_url, directory_aliases, catalogue_key
      ) values (
        'club', v_seed.name, v_seed.slug, v_seed.description, v_seed.club_category,
        v_seed.organization_type, 'campus', 'request', 'published', false, null,
        null, null, 0, false, v_seed.verification_status, v_seed.source_label,
        v_seed.source_url, replace(v_seed.aliases, '|', ', '), v_seed.catalogue_key
      );
    else
      update public.communities c set
        catalogue_key = coalesce(c.catalogue_key, v_seed.catalogue_key),
        organization_type = coalesce(c.organization_type, v_seed.organization_type),
        verification_status = case
          when c.verification_status = 'pending' then v_seed.verification_status
          else c.verification_status end,
        source_label = coalesce(c.source_label, v_seed.source_label),
        source_url = coalesce(c.source_url, v_seed.source_url),
        directory_aliases = case when c.directory_aliases = ''
          then replace(v_seed.aliases, '|', ', ') else c.directory_aliases end
       where c.id = v_id;
    end if;
  end loop;
end;
$$;

-- A migration-time assertion prevents accidental extra rows being invented to
-- match the incorrect roster count in the request.
do $$
begin
  if (select count(*) from club_catalogue_seed) <> 35 then
    raise exception 'The reconciled source roster must contain exactly 35 unique entries.';
  end if;
end;
$$;

-- ==========================================================================
-- FILE 33/79  20261029000001_033_unread_count_lookup.sql
-- ==========================================================================

-- =============================================================================
-- Campus+ migration 033 — bounded authorization for the shell unread snapshot
-- =============================================================================
-- The navigation snapshot previously re-entered conversation/member/message RLS
-- for every message in every one of the caller's conversations. The function's
-- result is already scoped to the current profile's active memberships, so that
-- repeated work is unnecessary. Keep the exact same boundary explicitly:
--   * public.current_profile_id() comes from the verified JWT;
--   * membership must belong to that profile and be active;
--   * the conversation must be published (the membership policy's condition);
--   * only incoming messages after that membership's read position are counted.
--
-- There is no conversation argument, no message body/member projection and no
-- staff/non-member branch. A non-member therefore receives no row to filter.
-- The existing exact-count, read-receipt and foreign-thread SQL tests remain
-- authoritative. SECURITY DEFINER only avoids re-running equivalent RLS checks;
-- it does not broaden the rows or fields this function can return.
-- =============================================================================

create or replace function public.messaging_unread_counts()
returns table (
  conversation_id uuid,
  last_read_at    timestamptz,
  unread_count    integer
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select
    mine.conversation_id,
    mine.last_read_at,
    (
      select count(*)::integer
      from public.messages msg
      where msg.conversation_id = mine.conversation_id
        and msg.sender_id <> public.current_profile_id()
        and (mine.last_read_at is null or msg.created_at > mine.last_read_at)
    ) as unread_count
  from public.conversation_members mine
  join public.conversations c on c.id = mine.conversation_id
  where mine.user_id = public.current_profile_id()
    and mine.status = 'active'
    and c.status = 'published'
  order by mine.conversation_id;
$$;

comment on function public.messaging_unread_counts() is
  'Exact incoming unread counts for the JWT profile only, bounded to active memberships in published conversations; no message content or arbitrary conversation input.';

revoke all on function public.messaging_unread_counts() from public, anon;
grant execute on function public.messaging_unread_counts() to authenticated, service_role;

-- ==========================================================================
-- FILE 34/79  20261029000002_034_inbox_membership_lookup.sql
-- ==========================================================================

-- =============================================================================
-- Campus+ migration 034 — bounded authorization for conversation inbox
-- =============================================================================
-- The inbox has the same member-only boundary as messaging_unread_counts(), but
-- also returns each visible conversation's latest preview. Keep every field and
-- predicate while making the boundary explicit once per inbox query instead of
-- re-entering member/message RLS for every message considered by the aggregates
-- and latest-message lookups.
--
-- There is still no arbitrary conversation argument. Rows require the verified
-- JWT profile, active membership and a published conversation; a non-member gets
-- no row and therefore no preview. Only that member's own read position/mute
-- state is returned. The exact unread and latest-message calculations, ordering
-- and p_limit behavior are unchanged. Database suite 12's recipient, non-member,
-- overflow-count and read-receipt tests cover this contract.
-- =============================================================================

create or replace function public.conversation_inbox(p_limit integer default 30)
returns table (
  id                      uuid,
  kind                    public.conversation_kind,
  title                   text,
  community_id            uuid,
  status                  public.content_status,
  last_message_at         timestamptz,
  created_at              timestamptz,
  is_muted                boolean,
  last_read_at            timestamptz,
  unread                  integer,
  last_message_id         uuid,
  last_message_sender_id  uuid,
  last_message_body       text,
  last_message_gif        jsonb,
  last_message_created_at timestamptz
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with mine as (
    select m.conversation_id, m.is_muted, m.last_read_at
    from public.conversation_members m
    where m.user_id = public.current_profile_id()
      and m.status = 'active'
  )
  select
    c.id,
    c.kind,
    c.title,
    c.community_id,
    c.status,
    c.last_message_at,
    c.created_at,
    mine.is_muted,
    mine.last_read_at,
    (
      select count(*)::integer
      from public.messages msg
      where msg.conversation_id = c.id
        and msg.sender_id <> public.current_profile_id()
        and (mine.last_read_at is null or msg.created_at > mine.last_read_at)
    ) as unread,
    latest.id,
    latest.sender_id,
    latest.body,
    latest.gif,
    latest.created_at
  from public.conversations c
  join mine on mine.conversation_id = c.id
  left join lateral (
    select msg.id, msg.sender_id, msg.body, msg.gif, msg.created_at
    from public.messages msg
    where msg.conversation_id = c.id
    order by msg.created_at desc
    limit 1
  ) latest on true
  where c.status = 'published'
  order by c.last_message_at desc
  limit coalesce(p_limit, 30);
$$;

comment on function public.conversation_inbox(integer) is
  'Member-only inbox with exact unread counts and latest previews for the JWT profile; active membership in a published conversation is required for every row.';

revoke all on function public.conversation_inbox(integer) from public, anon;
grant execute on function public.conversation_inbox(integer) to authenticated, service_role;

-- ==========================================================================
-- FILE 35/79  20261029000003_035_feed_visibility_reconciliation.sql
-- ==========================================================================

-- =============================================================================
-- Campus+ migration 035 — bounded visibility reconciliation for loaded feed posts
-- =============================================================================
-- A newest-page response cannot say why an already-loaded post is absent: newer
-- rows may have pushed it to page two, or moderation/RLS may have made it
-- ineligible. This IDs-only lookup answers that separate question for the bounded
-- set of rows a Home reader already holds. It returns no body, author, status or
-- other record content, and absence is indistinguishable from an unknown id.
--
-- SECURITY INVOKER is intentional. The same posts RLS policies that guard
-- campus_feed() still decide active-author, block/mute, membership and viewer
-- visibility. The explicit campus predicates match campus_feed()'s post branch,
-- so posts_select_author does not put an author's hidden/pending row back into the
-- shared Home feed. The feature flag is matched as well.
--
-- 510 IDs covers the supported 500-entry pagination depth plus one page of
-- accepted writes. The API applies the same bound and reports exactly which IDs
-- were checked; an unchecked ID is never treated as removed by the client.
-- =============================================================================

create or replace function public.campus_feed_post_visibility(
  p_post_ids uuid[] default '{}'::uuid[]
)
returns table (id uuid)
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with requested as (
    select input.id, min(input.ordinality) as position
    from unnest(coalesce(p_post_ids, '{}'::uuid[])) with ordinality as input(id, ordinality)
    group by input.id
    order by position
    limit 510
  )
  select requested.id
  from requested
  join public.posts p on p.id = requested.id
  where p.community_id is null
    and p.status = 'published'
    and p.deleted_at is null
    and public.feature_enabled('feed')
  order by requested.position;
$$;

comment on function public.campus_feed_post_visibility(uuid[]) is
  'IDs-only visibility reconciliation for at most 510 loaded Home post IDs; invoker RLS plus campus_feed post predicates, with no record content returned.';

revoke all on function public.campus_feed_post_visibility(uuid[]) from public, anon;
grant execute on function public.campus_feed_post_visibility(uuid[]) to authenticated, service_role;

-- ==========================================================================
-- FILE 36/79  20261029000004_036_admin_dashboard_counts.sql
-- ==========================================================================

-- Campus+ 036: one authorized, RLS-scoped Admin count snapshot
--
-- The count tab previously made twelve operational HEAD/count requests and four
-- overview HEAD/count requests. This additive function keeps every predicate and
-- every caller-visible row boundary, but evaluates them in one database call.
-- SECURITY INVOKER is intentional: count(*) sees exactly the rows the calling
-- admin could count through PostgREST, rather than bypassing RLS as the function
-- owner. The explicit permission check also makes direct RPC access safe.

create or replace function public.campus_admin_dashboard_counts()
returns json
language plpgsql
stable
security invoker
set search_path = public, pg_temp
as $$
begin
  if not public.has_permission('view_admin_overview') then
    raise exception 'view_admin_overview permission required'
      using errcode = '42501';
  end if;

  -- json, rather than jsonb, retains the operational counter order used by the
  -- existing Admin UI. Every count is exact; no estimate or reltuples value is
  -- used. All scalar subqueries share this function call's stable snapshot.
  return json_build_object(
    'counts', json_build_object(
      'profiles', (select count(*) from public.profiles),
      'posts', (select count(*) from public.posts),
      'comments', (select count(*) from public.comments),
      'reactions', (select count(*) from public.reactions),
      'communities', (select count(*) from public.communities),
      'marketplace_listings', (select count(*) from public.marketplace_listings),
      'gigs', (select count(*) from public.gigs),
      'events', (select count(*) from public.events),
      'notices', (select count(*) from public.notices),
      'reports', (select count(*) from public.reports),
      'messages', (select count(*) from public.messages),
      'random_sessions', (select count(*) from public.random_sessions)
    ),
    -- Campus+ has no presence/analytics source for this value. Preserve the
    -- existing explicit null instead of inventing a daily-active-user metric.
    'activeUsers24h', null,
    'overview', json_build_object(
      'pendingReports', (select count(*) from public.reports where status = 'pending'),
      'pendingListings', (select count(*) from public.marketplace_listings where status = 'pending'),
      'suspended', (select count(*) from public.profile_private where account_status = 'suspended'),
      'disabledFlags', (select count(*) from public.feature_flags where enabled = false)
    )
  );
end;
$$;

comment on function public.campus_admin_dashboard_counts() is
  'Exact Admin operational/overview counts for view_admin_overview callers; security invoker keeps every count under caller RLS.';

revoke all on function public.campus_admin_dashboard_counts() from public;
revoke all on function public.campus_admin_dashboard_counts() from anon;
grant execute on function public.campus_admin_dashboard_counts() to authenticated;

-- ==========================================================================
-- FILE 37/79  20261029000005_037_realtime_authorization_grants.sql
-- ==========================================================================

-- Campus+ migration 037 — reassert least-privilege Realtime function grants
-- =============================================================================
-- Migration 030 is the policy fix: realtime.messages uses the one-argument,
-- current-user-only predicate and never calls the two-argument membership
-- oracle. Production logs that still name can_access_random_session therefore
-- need the ordered migrations applied; this file must not be used as a shortcut
-- around 030.
--
-- This small, idempotent drift repair reasserts only the final grant contract.
-- `authenticated` is the role named by the private-channel policies. Supabase's
-- optional supabase_realtime database role receives the same narrow predicate
-- when that role exists. Neither role needs the cross-user oracle.
-- =============================================================================

revoke all on function public.can_access_own_random_session(uuid) from public, anon;
grant execute on function public.can_access_own_random_session(uuid) to authenticated, service_role;

-- Close the internal oracle to API roles even if a previous manual workaround
-- granted it back. Random's SECURITY DEFINER RPCs and the service role retain
-- their intended internal path; browser roles receive no cross-user membership
-- visibility.
revoke all on function public.can_access_random_session(uuid, uuid) from public, anon, authenticated;
grant execute on function public.can_access_random_session(uuid, uuid) to service_role;

do $$
begin
  if to_regrole('supabase_realtime') is not null then
    execute 'revoke all on function public.can_access_random_session(uuid, uuid) from supabase_realtime';
    execute 'grant execute on function public.can_access_own_random_session(uuid) to supabase_realtime';
  end if;
end $$;

-- ==========================================================================
-- FILE 38/79  20261101000001_038_post_pin_ordering.sql
-- ==========================================================================

-- =============================================================================
-- Campus+ migration 038 — durable post pin ordering and live pin changes
-- =============================================================================
-- The posts.pinned column already exists and is staff-controlled. This migration
-- does not add a pin timestamp or rewrite rows: existing pinned rows participate
-- in the corrected order as soon as campus_feed() is replaced.
--
-- Three contracts change together:
--   1. campus_feed() gives pinned entries priority, then retains the established
--      chronological/trending order and adds deterministic pagination tie-breaks.
--   2. moderate_content() adds audited pin/unpin actions for existing post
--      moderators. It grants no direct column update and no student permission.
--   3. posts uses a narrow replica-identity index (id, pinned, status), allowing
--      the existing Realtime UPDATE binding to discard counter-only updates while
--      still detecting a pin transition. Old post bodies are not added to WAL or
--      Realtime payloads, and RLS/publication membership are unchanged.
-- =============================================================================

create or replace function public.campus_feed(
  p_limit integer default 20,
  p_offset integer default 0,
  p_sort text default 'newest'
)
returns table (
  item_type text,
  id uuid,
  title text,
  body text,
  gif jsonb,
  author_username text,
  author_display_name text,
  is_official boolean,
  community_slug text,
  meta jsonb,
  created_at timestamptz,
  sort_at timestamptz
)
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with items as (
    -- student posts and discussions
    select
      case when p.kind = 'discussion' then 'discussion' else 'post' end as item_type,
      p.id,
      p.title,
      p.body,
      p.gif,
      pr.username as author_username,
      pr.display_name as author_display_name,
      p.is_official,
      c.slug as community_slug,
      jsonb_build_object(
        'kind', p.kind,
        'reaction_count', p.reaction_count,
        'comment_count', p.comment_count,
        'pinned', p.pinned
      ) as meta,
      p.created_at,
      p.created_at as sort_at
    from public.posts p
    join public.profiles pr on pr.id = p.author_id
    left join public.communities c on c.id = p.community_id
    where p.community_id is null
      and p.status = 'published'
      and p.deleted_at is null
      and public.feature_enabled('feed')

    union all

    -- official notices
    select
      'notice',
      n.id,
      n.title,
      n.body,
      null,
      null,
      null,
      true,
      null,
      jsonb_build_object('category', n.category, 'importance', n.importance, 'pinned', n.pinned),
      coalesce(n.published_at, n.created_at),
      case when n.pinned then now() + interval '1 day' else coalesce(n.published_at, n.created_at) end
    from public.notices n
    where n.status = 'published'
      and (n.expires_at is null or n.expires_at > now())
      and public.feature_enabled('noticeboard')

    union all

    -- upcoming events
    select
      'event',
      e.id,
      e.title,
      e.description,
      null,
      null,
      null,
      true,
      null,
      jsonb_build_object('starts_on', e.starts_on, 'start_time', e.start_time, 'location', e.location, 'organizer', e.organizer),
      e.created_at,
      case when e.starts_on <= current_date then now() else (e.starts_on::timestamptz) end
    from public.events e
    where e.status = 'published'
      and (e.ends_on is null or e.ends_on >= current_date)
      and public.feature_enabled('events')

    union all

    -- published opportunities
    select
      'opportunity',
      o.id,
      o.title,
      o.description,
      null,
      null,
      null,
      o.source = 'official',
      null,
      jsonb_build_object('organization', o.organization, 'deadline', o.deadline, 'source', o.source),
      o.created_at,
      o.created_at
    from public.opportunities o
    where o.status = 'published'
      and public.feature_enabled('opportunities')

    union all

    -- active marketplace highlights
    select
      'listing',
      l.id,
      l.title,
      l.description,
      null,
      pr.username,
      pr.display_name,
      false,
      null,
      jsonb_build_object('price', l.price, 'is_free', l.is_free, 'condition', l.condition),
      l.created_at,
      l.created_at
    from public.marketplace_listings l
    join public.profiles pr on pr.id = l.seller_id
    where l.status = 'active'
      and public.feature_enabled('marketplace')
      and public.setting('feed_marketplace_highlights', 'true'::jsonb) = 'true'::jsonb
  )
  select *
  from items
  order by
    -- A pin is a moderation decision, not a fabricated timestamp. Keep the
    -- existing pinned-notice behaviour in the same priority group, then use
    -- each entry's established ordering inside that group.
    case when coalesce((meta->>'pinned')::boolean, false) then 1 else 0 end desc,
    case when p_sort = 'trending' then null else sort_at end desc nulls last,
    -- deterministic secondary signal for trending: engagement density
    case when p_sort = 'trending'
      then coalesce((meta->>'reaction_count')::int, 0) * 2 + coalesce((meta->>'comment_count')::int, 0) * 3
      else 0 end desc,
    -- Offset pages must not reshuffle rows with equal sort keys.
    item_type asc,
    id asc
  limit least(greatest(coalesce(p_limit, 20), 1), 50)
  offset greatest(coalesce(p_offset, 0), 0);
$$;

comment on function public.campus_feed(integer, integer, text) is
  'Unified home feed. Pinned entries lead; otherwise newest by timestamp or trending by the documented engagement formula, with deterministic page tie-breaks.';

create or replace function public.moderate_content(
  p_target_type text,
  p_target_id uuid,
  p_action text,
  p_reason text default null,
  p_report_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_permission text;
  v_new_status text;
  v_author uuid;
  v_pinned boolean;
  v_label text;
begin
  v_permission := public.content_moderation_permission(p_target_type);
  if v_permission is null then
    raise exception 'That content type cannot be moderated.' using errcode = '22023';
  end if;

  if not public.is_trusted_writer() then
    if not public.is_active_profile(public.current_profile_id()) then
      raise exception 'Your account cannot moderate content.' using errcode = '42501';
    end if;
    if not (public.has_permission(v_permission) or public.has_permission('moderate_all')) then
      raise exception 'You do not have permission to moderate this content.' using errcode = '42501';
    end if;
  end if;

  v_new_status := case p_action
    when 'hide' then 'hidden'
    when 'remove' then 'removed'
    when 'restore' then 'published'
    when 'approve' then 'published'
    when 'reject' then 'removed'
    else null
  end;

  if p_action in ('pin', 'unpin') and p_target_type <> 'post' then
    raise exception 'Only posts can be pinned or unpinned.' using errcode = '22023';
  end if;
  if p_target_type in ('post', 'comment', 'marketplace_listing', 'gig', 'community', 'club',
                       'project', 'lost_found', 'housing_post', 'ride_post')
     and v_new_status is null
     and not (p_target_type = 'post' and p_action in ('pin', 'unpin')) then
    raise exception 'Unsupported action for this content type.' using errcode = '22023';
  end if;
  if p_target_type = 'marketplace_listing' and p_action = 'approve' then
    v_new_status := 'active';
  end if;

  if p_target_type = 'post' then
    update public.posts
       set status = coalesce(v_new_status::public.content_status, status),
           pinned = case p_action when 'pin' then true when 'unpin' then false else pinned end,
           moderated_by = public.current_profile_id(),
           moderated_at = now(), moderation_reason = left(p_reason, 500)
     where id = p_target_id
       and (p_action <> 'pin' or status = 'published')
     returning author_id, pinned into v_author, v_pinned;
    if p_action in ('pin', 'unpin') and not found then
      raise exception 'The post could not be found or is not published.' using errcode = '22023';
    end if;
  elsif p_target_type = 'comment' then
    update public.comments
       set status = v_new_status::public.content_status, moderated_by = public.current_profile_id(),
           moderated_at = now(), moderation_reason = left(p_reason, 500)
     where id = p_target_id
     returning author_id into v_author;
  elsif p_target_type = 'marketplace_listing' then
    update public.marketplace_listings
       set status = v_new_status::public.listing_status, moderated_by = public.current_profile_id(),
           moderated_at = now(), moderation_reason = left(p_reason, 500)
     where id = p_target_id
     returning seller_id into v_author;
  elsif p_target_type = 'gig' then
    update public.gigs
       set status = v_new_status::public.content_status, moderated_by = public.current_profile_id(),
           moderated_at = now(), moderation_reason = left(p_reason, 500)
     where id = p_target_id
     returning creator_id into v_author;
  elsif p_target_type in ('community', 'club') then
    update public.communities
       set status = v_new_status::public.content_status
     where id = p_target_id
     returning created_by into v_author;
  elsif p_target_type = 'project' then
    update public.projects
       set status = v_new_status::public.content_status, moderated_by = public.current_profile_id(),
           moderated_at = now(), moderation_reason = left(p_reason, 500)
     where id = p_target_id
     returning creator_id into v_author;
  elsif p_target_type = 'lost_found' then
    update public.lost_found set status = v_new_status::public.content_status
     where id = p_target_id returning creator_id into v_author;
  elsif p_target_type = 'housing_post' then
    update public.housing_posts set status = v_new_status::public.content_status
     where id = p_target_id returning creator_id into v_author;
  elsif p_target_type = 'ride_post' then
    update public.ride_posts set status = v_new_status::public.content_status
     where id = p_target_id returning creator_id into v_author;
  elsif p_target_type in ('notice', 'event', 'resource', 'opportunity', 'deal') then
    -- Official content: staff already own these rows through RLS-managed updates.
    update public.audit_logs set id = id where false;  -- no-op keeps the branch explicit
    v_author := null;
  end if;

  perform public.log_audit('moderation.content_' || p_action, p_target_type, p_target_id::text,
    jsonb_build_object('report_id', p_report_id, 'status', v_new_status, 'pinned', v_pinned), true, p_reason, 'staff');

  if v_author is not null and p_action in ('hide', 'remove', 'reject') then
    v_label := replace(p_target_type, '_', ' ');
    perform public.notify_user(v_author, 'moderation_notice',
      'Your ' || v_label || ' was ' || case when p_action = 'hide' then 'hidden' else 'removed' end,
      coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'Review the Campus+ rules and post again.'),
      p_target_type, p_target_id::text, null);
  end if;

  return jsonb_build_object('ok', true, 'status', v_new_status, 'pinned', v_pinned);
end;
$$;

comment on function public.moderate_content is
  'Single moderation action path: permission check → status or post-pin change → audit log → author notification where applicable.';

-- Postgres includes replica-identity key columns in an UPDATE old tuple. Using
-- this narrow index avoids REPLICA IDENTITY FULL and its old-content exposure.
create unique index posts_feed_replica_identity_idx
  on public.posts (id, pinned, status);
alter table public.posts replica identity using index posts_feed_replica_identity_idx;

comment on index public.posts_feed_replica_identity_idx is
  'Realtime update identity: old id/pin/status only, so pin transitions are distinguishable from counter-only writes without full-row replica identity.';

-- ==========================================================================
-- FILE 39/79  20261102000001_039_poll_author_may_vote.sql
-- ==========================================================================

-- =============================================================================
-- Campus+ migration 039 — let a poll's author vote in their own poll
-- =============================================================================
-- The poll_votes_insert_self policy carried `p.author_id <> current_profile_id()`,
-- which silently rejected the poll creator's own vote. That is not an intentional
-- product rule: the one-vote-per-user unique constraint, the active-account check,
-- the published-and-open poll check and the block check all stay in force. Only the
-- author-specific exclusion is removed, so the creator participates like any other
-- eligible student.
--
-- No table shape changes; only the insert policy is recreated. Delete/select
-- policies, triggers and grants are untouched.
-- =============================================================================

drop policy if exists poll_votes_insert_self on public.poll_votes;

create policy poll_votes_insert_self on public.poll_votes
  for insert to authenticated
  with check (
    user_id = public.current_profile_id()
    and public.is_active_user()
    and exists (
      select 1 from public.posts p
      where p.id = post_id
        and p.kind = 'poll'
        and p.status = 'published'
        and (p.poll_closes_at is null or p.poll_closes_at > now())
    )
    and not exists (
      select 1 from public.posts p2
      where p2.id = post_id and public.is_blocked_with_current(p2.author_id)
    )
  );

comment on policy poll_votes_insert_self on public.poll_votes is
  'Any active student may vote once in an open published poll, including the poll author; duplicates remain blocked by the unique (post_id, user_id) constraint.';

-- ==========================================================================
-- FILE 40/79  20261102000002_040_busiest_trending.sql
-- ==========================================================================

-- =============================================================================
-- Campus+ migration 040 — "Busiest right now": real, recent engagement
-- =============================================================================
-- The Home rail's bars were normalized against the highest counter in the three
-- rows on screen (lib/social/activity-scale.js), so two likes filled the track.
-- The bar is now normalized against a fixed benchmark, but a fixed benchmark is
-- only honest if the number behind it is a real trending score and not a
-- lifetime total from whichever posts happen to be on page one.
--
-- `public.trending_posts(integer, integer)` already exists (migration 011) and
-- is the RPC Explore uses. It is repaired here rather than replaced: the output
-- contract, the invoker-security RLS boundary and the grants are untouched.
--
--   score = ( Σ likes·decay(age) + comment_weight·Σ comments·decay(age) )
--           × ( post_floor + (1 - post_floor)·2^(-postAge / postHalfLife) )
--
--   decay(age) = (2^(-age / halfLife) - 2^(-window / halfLife))
--                / (1 - 2^(-window / halfLife))        for 0 <= age <= window
--              = 0                                    outside the window
--
--   window      = p_hours (48 h by default; 24–48 h is the intended range)
--   halfLife    = setting_int('trending_half_life_hours', 12)
--   commentWeight = setting_int('trending_comment_weight', 2)
--   postHalfLife  = setting_int('trending_post_age_half_life_hours', 72)
--   post_floor  = 0.5 (a genuinely active old post is never worth zero)
--
-- Those numbers are published in lib/constants.js (TRENDING_*) and pinned by
-- tests/trending.test.js. The half-life weights are read from the existing
-- platform_settings table through setting_int(), so the campus can recalibrate
-- without another migration; no new table, column or function is introduced.
--
-- What changes in behaviour:
--   * Only engagement inside the window counts. A post with 100 accumulated
--     likes and no recent activity scores 0; 12 fresh likes outrank it.
--   * A like is one `reactions` row. The existing
--     reactions_unique_per_item(user_id, target_type, target_id) constraint
--     makes that one per student, so duplicate likes cannot inflate the score
--     and no per-user/per-post N+1 read is needed.
--   * The unbounded `count(distinct commenters)` scan over ALL comments is
--     replaced by two windowed aggregations using the partial indexes below.
--   * Candidates are posts with recent engagement plus posts published inside
--     the window. If neither exists, the newest campus posts are returned with
--     score 0 so a quiet campus still sees real (unexaggerated) discussions.
--   * Ordering is score desc, created_at desc, id asc — deterministic even when
--     every score is zero. No random tie-break, no fabricated engagement.
--   * `security invoker` + the published/not-deleted/campus-only predicates
--     keep deleted, hidden, blocked and community-scoped rows out.
-- =============================================================================

-- Windowed engagement reads. Both partial indexes match the CTE predicates, so
-- a growing reactions/comments table is not scanned in full on every refresh.
create index if not exists reactions_recent_post_idx
  on public.reactions (created_at desc)
  where target_type = 'post';

create index if not exists comments_recent_published_idx
  on public.comments (created_at desc)
  where status = 'published' and deleted_at is null;

create or replace function public.trending_posts(
  p_limit integer default 20,
  p_hours integer default 48
)
returns table (
  id uuid,
  author_id uuid,
  username text,
  display_name text,
  title text,
  body text,
  kind public.post_kind,
  gif jsonb,
  reaction_count integer,
  comment_count integer,
  participant_count integer,
  created_at timestamptz,
  score real
)
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with tuning as (
    select
      greatest(coalesce(p_hours, 48), 1)::numeric as window_hours,
      least(greatest(coalesce(p_limit, 20), 1), 50)::integer as lim,
      greatest(public.setting_int('trending_half_life_hours', 12), 1)::numeric as half_life,
      greatest(public.setting_int('trending_post_age_half_life_hours', 72), 1)::numeric as post_half_life,
      greatest(public.setting_int('trending_comment_weight', 2), 0)::numeric as comment_weight,
      0.5::numeric as post_floor
  ),
  params as (
    select
      t.*,
      power(0.5::numeric, t.window_hours / t.half_life) as edge,
      now() - make_interval(hours => t.window_hours::integer) as since
    from tuning t
  ),
  -- One row per (student, post) because of reactions_unique_per_item. The decay
  -- reaches 0 exactly at the window edge, so an old like cannot trickle in.
  recent_likes as (
    select
      r.target_id as post_id,
      count(*)::integer as recent_count,
      coalesce(sum(
        greatest(
          (
            power(0.5::numeric,
              greatest(extract(epoch from (now() - r.created_at)) / 3600.0, 0)::numeric
              / (select half_life from params))
            - (select edge from params)
          ) / nullif(1 - (select edge from params), 0),
          0::numeric
        )
      ), 0::numeric) as weighted
    from public.reactions r
    where r.target_type = 'post'
      and r.created_at > (select since from params)
    group by r.target_id
  ),
  recent_comments as (
    select
      c.post_id,
      count(*)::integer as recent_count,
      count(distinct c.author_id)::integer as participants,
      coalesce(sum(
        greatest(
          (
            power(0.5::numeric,
              greatest(extract(epoch from (now() - c.created_at)) / 3600.0, 0)::numeric
              / (select half_life from params))
            - (select edge from params)
          ) / nullif(1 - (select edge from params), 0),
          0::numeric
        )
      ), 0::numeric) as weighted
    from public.comments c
    where c.status = 'published'
      and c.deleted_at is null
      and c.created_at > (select since from params)
    group by c.post_id
  ),
  active_ids as (
    select post_id from recent_likes
    union
    select post_id from recent_comments
  ),
  -- A new discussion with no engagement yet still belongs in the list, at 0%.
  fresh_posts as (
    select p.id as post_id
    from public.posts p
    where p.status = 'published'
      and p.deleted_at is null
      and p.community_id is null
      and p.created_at > (select since from params)
  ),
  candidate_ids as (
    select post_id from active_ids
    union
    select post_id from fresh_posts
  ),
  -- Only when the window is completely quiet: the newest real posts, score 0.
  fallback_ids as (
    select p.id as post_id
    from public.posts p
    where p.status = 'published'
      and p.deleted_at is null
      and p.community_id is null
      and not exists (select 1 from candidate_ids)
    -- posts_feed_idx serves this order; no window over the whole posts table.
    order by p.created_at desc, p.id asc
    limit (select lim from params)
  ),
  ids as (
    select post_id from candidate_ids
    union all
    select post_id from fallback_ids
  )
  select
    p.id,
    p.author_id,
    pr.username,
    pr.display_name,
    p.title,
    p.body,
    p.kind,
    p.gif,
    p.reaction_count,
    p.comment_count,
    coalesce(rc.participants, 0)::integer as participant_count,
    p.created_at,
    (
      (
        coalesce(rl.weighted, 0::numeric)
        + (select comment_weight from params) * coalesce(rc.weighted, 0::numeric)
      )
      * (
          (select post_floor from params)
          + (1 - (select post_floor from params))
            * power(0.5::numeric,
                greatest(extract(epoch from (now() - p.created_at)) / 3600.0, 0)::numeric
                / (select post_half_life from params))
        )
    )::real as score
  from ids i
  join public.posts p on p.id = i.post_id
  join public.profiles pr on pr.id = p.author_id
  left join recent_likes rl on rl.post_id = p.id
  left join recent_comments rc on rc.post_id = p.id
  where p.status = 'published'
    and p.deleted_at is null
    and p.community_id is null
  order by score desc, p.created_at desc, p.id asc
  limit (select lim from params);
$$;

comment on function public.trending_posts(integer, integer) is
  'Deterministic recent-engagement trending score. Formula and defaults are published in lib/constants.js#TRENDING_FORMULA; bar normalization lives in lib/social/activity-scale.js. SECURITY INVOKER so RLS still decides visibility.';

-- ==========================================================================
-- FILE 41/79  20261103000001_041_public_discovery.sql
-- ==========================================================================

-- Campus+ migration 041 — public discovery: clubs by slug, public events
-- =============================================================================
-- Product rule: public discovery, private student data, authenticated
-- participation, controlled administration. This migration opens *reads* for
-- three very narrow projections and opens no writes at all.
--
-- ── The visibility decision (explicit, not silent) ─────────────────────────
-- Migration 032 imported 35 published catalogue clubs with
-- `visibility = 'campus'`. In the existing model `campus` means "readable by
-- signed-in campus accounts"; `public` means "readable by everyone on Campus+";
-- `community` / `private` are member-only. Making every `campus` row visible to
-- the anonymous key would also expose private study groups and unrelated
-- communities, so that is NOT what this migration does.
--
-- Instead, the 35 source-roster catalogue entries are *explicitly* moved from
-- `campus` to `public`, and the anonymous SELECT policy below additionally
-- requires `kind = 'club'` and `status = 'published'`. For clubs, `public` now
-- also means "listed on the open web" (the club settings form says so). Every
-- other `campus`, `community` and `private` row keeps its existing boundary:
-- anon has no policy that can return it. Published/unpublished status stays
-- authoritative too — a club that is hidden, removed or archived drops out of
-- the public directory immediately.
--
-- Affected records: exactly the 35 `catalogue_key` values seeded by migration
-- 032, listed in the UPDATE below. Clubs created through the staff workflow or
-- an approved request keep their `campus` default until a manager explicitly
-- chooses "Public on the web"; that is a deliberate, auditable choice, not a
-- side effect of creating a club. Nothing else is rewritten.
--
-- ── Column projections ─────────────────────────────────────────────────────
-- Migration 014/018 revoke ALL table privileges from `anon`. This migration
-- grants SELECT on named columns only (never `select *`), so even a mistake in
-- a public page cannot read an administrator's profile id, a moderation note,
-- an author id or an attendee row. `information_schema.role_table_grants` stays
-- empty for anon; the audit script checks `column_privileges` explicitly.
--
-- ── Mutations ──────────────────────────────────────────────────────────────
-- No INSERT/UPDATE/DELETE policy is created for anon, no write column is
-- granted, and no function EXECUTE is granted (migration 018's blanket revoke
-- stays in force). RLS therefore denies every anonymous mutation, including
-- join requests, memberships, RSVPs, event/club writes and management RPCs.
-- =============================================================================

-- Snapshot the effective anon EXECUTE surface BEFORE this migration changes
-- anything, so section 5 can prove the migration added no new callable
-- function. Earlier migrations left a few SECURITY DEFINER *trigger* functions
-- reachable through PUBLIC's default EXECUTE; those are pre-existing, are not
-- RPCs (they need a NEW/OLD row and are only invoked by triggers), and are
-- deliberately left untouched here. What matters is that public discovery does
-- not widen that surface by a single function.
create temp table __anon_exec_before_041 as
select p.oid
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
 where n.nspname = 'public'
   and has_function_privilege('anon', p.oid, 'EXECUTE');

-- ---------------------------------------------------------------------------
-- 1. Documented visibility change for the published club catalogue
-- ---------------------------------------------------------------------------

update public.communities
   set visibility = 'public'
 where kind = 'club'
   and status = 'published'
   and visibility = 'campus'
   and catalogue_key in (
     'team-red-baron', 'team-kratos-racing-electric', 'team-solarium',
     'team-ambush', 'team-automatons', 'team-maverick-india', 'team-anantam',
     'coding-club', 'devcorps', 'cybsec', 'foss', 'gdg-campus',
     'cesa', 'mesa', 'etsa', 'ciesa', 'itsa', 'aimsa', 'cresa', 'mcasa',
     'acm-pccoe', 'acm-w-pccoe', 'csi-pccoe', 'iet-pccoe', 'iste-pccoe',
     'codechef-pccoe', 'owasp-pccoe', 'ieee-pccoe', 'iete-pccoe',
     'swaad', 'pac', 'nss', 'games-and-sports', 'samvaad', 'campus-plus'
   );

comment on column public.communities.visibility is
  'public = listed on the open web (clubs only for anon, see migration 041); '
  'campus = signed-in campus accounts; community/private = member-only. '
  'The anonymous policy additionally requires kind = club and status = published.';

-- ---------------------------------------------------------------------------
-- 2. Column-level anonymous reads — explicit allow-lists, never whole tables
-- ---------------------------------------------------------------------------

-- Clubs: public profile fields only. No created_by / approved_by / approved_at
-- (administrator identity), no catalogue_key (internal import provenance), no
-- study-group fields. `id` is needed to associate published events with a club;
-- it is not used as a public URL identifier (the slug is).
grant select (
  id, kind, name, slug, description, club_category, organization_type,
  meeting_info, recruitment_info, contact_info, external_url, visibility,
  join_policy, status, is_official, verification_status, source_label,
  source_url, directory_aliases, admin_assigned, member_count, post_count,
  created_at, updated_at
) on public.communities to anon;

-- Events: public listing/detail fields only. No created_by / updated_by /
-- updated_at / discussion_post_id / search_vector. `registration_info` and
-- `registration_url` are intentionally public fields (migration 009) and are
-- rendered as plain text/external links on a published event page.
grant select (
  id, title, description, starts_on, ends_on, start_time, end_time, location,
  organizer, registration_info, registration_url, capacity, show_attendees,
  club_id, category, status, is_official, published_at, created_at
) on public.events to anon;

-- Posts: only the columns needed to show a public club announcement. No
-- author_id, no moderation columns, no poll/vote state, no gif payload.
-- `deleted_at`, `visibility`, `status`, `community_id`, `kind` and
-- `is_official` are needed by the policy/predicate below, not by the page.
grant select (
  id, community_id, title, body, kind, visibility, status, is_official,
  created_at, deleted_at
) on public.posts to anon;

-- ---------------------------------------------------------------------------
-- 3. Narrow anonymous SELECT policies
-- ---------------------------------------------------------------------------

create policy communities_select_public_club on public.communities
  for select to anon
  using (
    kind = 'club'
    and status = 'published'
    and visibility = 'public'
  );

comment on policy communities_select_public_club on public.communities is
  'Anonymous catalogue reads only. Private, campus-only, unpublished, removed '
  'and non-club communities are excluded; see migration 041.';

create policy events_select_public_published on public.events
  for select to anon
  using (status = 'published');

comment on policy events_select_public_published on public.events is
  'Anonymous reads are limited to published events. Drafts, cancelled, '
  'rejected, review notes and attendee rows have no anonymous policy.';

create policy posts_select_public_club_announcement on public.posts
  for select to anon
  using (
    status = 'published'
    and deleted_at is null
    and visibility = 'public'
    and community_id is not null
    and exists (
      select 1 from public.communities c
       where c.id = community_id
         and c.kind = 'club'
         and c.status = 'published'
         and c.visibility = 'public'
    )
  );

comment on policy posts_select_public_club_announcement on public.posts is
  'A public club does not make every post public. Only a published, explicitly '
  'public, undeleted announcement in a published publicly listed club is '
  'readable anonymously. No author identity is projected.';

-- ---------------------------------------------------------------------------
-- 4. Search results link to the canonical slug URL
-- ---------------------------------------------------------------------------
-- `global_search()` (migration 024, replacing 011) still builds the pre-section
-- `/campus/clubs/<uuid>` address. That address redirects twice today; rewrite
-- the single expression in the current function definition instead of copying
-- 280 lines of SQL. `pg_get_functiondef` returns a runnable CREATE OR REPLACE
-- statement, so the function body, grants, volatility and SECURITY INVOKER
-- behaviour are all preserved. If a deployment has a custom definition that no
-- longer contains the exact expression, leave it alone and warn: the legacy
-- URL still resolves through the permanent redirect in app/(public)/clubs/[id].
-- Distinct dollar-quote tags: the inner literals contain SQL string quotes, so
-- nesting the same tag inside the outer block would terminate it early.
do $patch_search$
declare
  v_def text;
  v_new text;
begin
  select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'global_search';

  v_new := replace(v_def, $old_url$'/campus/clubs/' || c.id::text$old_url$, $new_url$'/c/' || c.slug$new_url$);
  if v_def is null or v_new = v_def then
    raise notice 'global_search club URL expression not found; legacy redirect remains in place.';
  else
    execute v_new;
  end if;
end $patch_search$;

-- `create or replace function` keeps the old ACL, but make the existing
-- contract explicit anyway: the search RPC is authenticated-only.
revoke all on function public.global_search(text, text, integer, integer) from public, anon;
grant execute on function public.global_search(text, text, integer, integer) to authenticated, service_role;

-- Migration 031 created five SECURITY DEFINER trigger functions *after* 018 had
-- revoked PUBLIC's default EXECUTE, so they reappeared with PUBLIC EXECUTE and
-- `anon` inherited it. They are trigger functions rather than RPCs, but an
-- anonymous visitor has no reason to hold EXECUTE on any definer function.
-- EXECUTE on a trigger function is checked when the trigger is created (all
-- five triggers already exist), and the bodies run with the owner's privileges,
-- so this revoke does not change any application behaviour.
revoke all on function public.guard_club_creation_request_insert() from public, anon;
revoke all on function public.notify_club_request_admins() from public, anon;
revoke all on function public.sync_club_admin_assignment() from public, anon;
revoke all on function public.guard_community_membership_write() from public, anon;
revoke all on function public.guard_club_linked_content() from public, anon;
grant execute on function public.guard_club_creation_request_insert() to authenticated, service_role;
grant execute on function public.notify_club_request_admins() to authenticated, service_role;
