grant execute on function public.space_claim_draft(uuid,uuid,uuid[]) to authenticated;
-- Allow client-provided UUIDs for idempotent invoker-RLS publication.
grant insert (id) on public.communities to authenticated;
create function public.publish_space_with_draft(p_draft uuid,p_id uuid,p_post jsonb,p_files uuid[]) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare actor uuid:=public.current_profile_id(); previous uuid;
begin
  if actor is null or not public.is_active_user() then raise exception 'Not permitted' using errcode='42501'; end if;
  previous:=public.space_draft_post(p_draft);
  if previous is not null then return (select jsonb_build_object('id',id,'slug',slug) from public.communities where id=previous); end if;
  if p_post->>'kind' not in ('community','study_group') then raise exception 'Not permitted' using errcode='42501'; end if;
  insert into public.communities(id,kind,name,slug,description,subject,branch,year,meeting_info,contact_info,external_url,visibility,join_policy,status,is_official,created_by)
  values(p_id,(p_post->>'kind')::public.community_kind,p_post->>'name',p_post->>'slug',p_post->>'description',nullif(p_post->>'subject',''),nullif(p_post->>'branch',''),nullif(p_post->>'year',''),nullif(p_post->>'meeting_info',''),nullif(p_post->>'contact_info',''),nullif(p_post->>'external_url',''),(p_post->>'visibility')::public.visibility_level,p_post->>'join_policy','published',false,actor);
  perform public.space_claim_draft(p_draft,p_id,p_files);
  return jsonb_build_object('id',p_id,'slug',p_post->>'slug');
end $$;
revoke all on function public.publish_space_with_draft(uuid,uuid,jsonb,uuid[]) from public,anon;
grant execute on function public.publish_space_with_draft(uuid,uuid,jsonb,uuid[]) to authenticated;
create function public.publish_club_with_draft(p_draft uuid,p_admin_username text,p_post jsonb,p_files uuid[]) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare previous uuid; result jsonb; club_id uuid;
begin
  if not public.is_active_user() or not public.has_permission('manage_clubs') then raise exception 'Not permitted' using errcode='42501'; end if;
  previous:=public.space_draft_post(p_draft);
  if previous is not null then return (select jsonb_build_object('id',id,'slug',slug) from public.communities where id=previous and kind='club'); end if;
  result:=public.create_club_with_admin(p_admin_username,p_post);
  club_id:=(result->>'id')::uuid;
  perform public.space_claim_draft(p_draft,club_id,p_files);
  return result;
end $$;
revoke all on function public.publish_club_with_draft(uuid,text,jsonb,uuid[]) from public,anon;
grant execute on function public.publish_club_with_draft(uuid,text,jsonb,uuid[]) to authenticated;
create function public.space_retire_attachment(p_post uuid,p_file uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$
begin
  if not public.is_active_user() or not public.feature_enabled('space_attachments') then raise exception 'Not permitted' using errcode='42501'; end if;
  perform 1 from public.communities where id=p_post and public.can_manage_space(p_post) for update;
  if not found then raise exception 'Not permitted' using errcode='42501'; end if;
  update public.storage_files f set status='delete_pending' from public.space_attachment_links l where l.post_id=p_post and l.file_id=p_file and f.id=l.file_id and f.resource_type='space_attachment' and f.status='ready';
  if not found then raise exception 'Attachment unavailable' using errcode='42501'; end if;
end $$;
revoke all on function public.space_retire_attachment(uuid,uuid) from public,anon;
grant execute on function public.space_retire_attachment(uuid,uuid) to authenticated;
create function public.space_retire_deleted() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
  update public.storage_files f set status='delete_pending' from public.space_attachment_links l where l.post_id=old.id and l.file_id=f.id and f.resource_type='space_attachment' and f.status in ('reserved','ready');
  return old;
end $$;
revoke all on function public.space_retire_deleted() from public,anon,authenticated;
create trigger space_retire_deleted before delete on public.communities for each row execute function public.space_retire_deleted();
create function public.storage_complete_space_attachment_delete(p_file uuid) returns void language sql security definer set search_path=public,pg_temp as $$
  update public.storage_files set status='deleted',deleted_at=now() where id=p_file and resource_type='space_attachment' and status='delete_pending';
$$;
revoke all on function public.storage_complete_space_attachment_delete(uuid) from public,anon,authenticated;
grant execute on function public.storage_complete_space_attachment_delete(uuid) to service_role;
select public.backup_sync_triggers();

-- ==========================================================================
-- FILE 72/79  20261112000026_072_notice_archive.sql
-- ==========================================================================

-- Campus+ migration 072 — noticeboard archive
-- =============================================================================
-- A historical noticeboard record is an ordinary row in public.notices with
-- status = 'archived'. That status already keeps it out of every "current"
-- surface: the noticeboard list, the Campus hub, the Home feed and
-- campus_feed() all pin status = 'published'.
--
-- Two things were missing, and this migration adds exactly those two:
--
--   notice_archive_entries   where an archive record came from: a
--                            deterministic source key, its noticeboard section,
--                            the organisation it is attributed to, the category
--                            label used by the source, the period it refers to
--                            and what the source did not preserve, plus a
--                            checksum of the supplied text. public.notices has
--                            no column for any of this, and events /
--                            achievements are the wrong home for a record with
--                            no date or venue.
--
--   notices_select_archive   until now status = 'archived' was readable by
--                            staff only. Students may now read an archived
--                            notice, but only when it is registered in
--                            notice_archive_entries. A notice that staff
--                            archive by hand stays staff-only, as before.
--
-- No existing policy, grant, trigger, column or row is changed.
-- =============================================================================

create table public.notice_archive_entries (
  -- <batch>/<section>/<slug>. The import matches on this key, so re-running an
  -- import can never create a second copy of a record.
  source_key      text primary key
                  check (source_key ~ '^[a-z0-9]+(-[a-z0-9]+)*(/[a-z0-9]+(-[a-z0-9]+)*){2}$'),
  -- SET NULL rather than CASCADE: when staff delete an archive record the key
  -- stays registered, so a later re-run does not quietly bring the record back.
  notice_id       uuid unique references public.notices (id) on delete set null,
  section_key     text not null check (section_key ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  section_label   text not null check (length(btrim(section_label)) between 2 and 120),
  -- Attribution as text. It is always present; community_id is set only when
  -- the organisation already exists in the club catalogue. `attribution` says
  -- whether the name is a student organisation or cell, or the institution.
  organization    text not null check (length(btrim(organization)) between 2 and 120),
  attribution     text not null check (attribution in ('organization', 'institution')),
  community_id    uuid references public.communities (id) on delete set null,
  -- The category wording of the source, kept verbatim. notices.category holds
  -- the nearest value of the notice_category enum.
  source_category text not null check (length(btrim(source_category)) between 2 and 60),
  -- The year or academic year the record refers to, only where its own text
  -- gives one ('2025', 'AY 2022–23'). A label, deliberately not a date: no
  -- record in the archive has a day, and none may be implied.
  period          text check (period is null or length(btrim(period)) between 2 and 40),
  -- What the source did not preserve (names, figures, dates), in its own words.
  source_note     text check (source_note is null or length(btrim(source_note)) between 5 and 400),
  sort_order      integer not null check (sort_order > 0),
  -- md5(title || E'\n' || body) of the text as supplied. Comparing it with the
  -- live notice shows whether a record still carries its source wording.
  source_checksum text not null check (source_checksum ~ '^[0-9a-f]{32}$'),
  created_at      timestamptz not null default now()
);

create index notice_archive_entries_community_idx on public.notice_archive_entries (community_id);
create index notice_archive_entries_section_idx on public.notice_archive_entries (section_key, sort_order);

comment on table public.notice_archive_entries is
  'Provenance for imported noticeboard archive records. One row per source key; written by migrations only.';

alter table public.notice_archive_entries enable row level security;

-- SECURITY DEFINER because the notices policy below must not depend on the
-- caller's own view of notice_archive_entries: that table's policy looks at
-- notices, and two policies that read each other recurse.
create function public.notice_archive_listed(p_notice_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.notice_archive_entries e where e.notice_id = p_notice_id
  );
$$;

comment on function public.notice_archive_listed(uuid) is
  'TRUE when the notice is a registered archive record. Used by notices_select_archive.';

revoke all on function public.notice_archive_listed(uuid) from public, anon;
grant execute on function public.notice_archive_listed(uuid) to authenticated, service_role;

-- Additive: the published and staff policies are untouched, so nothing that was
-- hidden before becomes visible except registered archive records.
create policy notices_select_archive on public.notices
  for select to authenticated
  using (status = 'archived' and public.notice_archive_listed(id));

-- A provenance row is readable exactly when its notice is readable (the
-- sub-select runs under the caller's RLS on notices). Rows whose notice was
-- deleted have no notice to show and are visible to noticeboard staff only.
create policy notice_archive_entries_select on public.notice_archive_entries
  for select to authenticated
  using (
    public.has_permission('manage_notices')
    or exists (select 1 from public.notices n where n.id = notice_archive_entries.notice_id)
  );

-- Read-only for clients: there is no INSERT, UPDATE or DELETE policy and no
-- write grant. Archive records are registered by migrations.
revoke all on public.notice_archive_entries from public, anon, authenticated;
grant select on public.notice_archive_entries to authenticated;
grant all on public.notice_archive_entries to service_role;

-- Attach transactional backup capture to the new table before any row exists.
select public.backup_sync_triggers();

-- ==========================================================================
-- FILE 73/79  20261112000027_073_pccoe_noticeboard_archive.sql
-- ==========================================================================

-- Campus+ migration 073 — PCCOE noticeboard archive (batch pccoe-noticeboard-2026-11)
-- =============================================================================
-- Imports the 64 supplied noticeboard entries as archive records:
--
--   public.notices                 title and description exactly as supplied,
--                                  status = 'archived', published by the import
--                                  profile
--   public.notice_archive_entries  source key, section, organisation
--                                  attribution, source category, period and
--                                  source note where given, order, checksum
--
-- Nothing is written to public.events or public.academic_calendar: no entry in
-- the batch carries a date or a venue, and both tables require them. No
-- organisation is created; a section is linked to a club only when that club
-- already exists in the catalogue, and is otherwise attributed by name.
--
-- The descriptions are written summaries of noticeboard displays, not
-- transcriptions of the posters. They are stored exactly as supplied: every
-- section and entry carries a digest of its own fields, and the import refuses
-- to run if any of them no longer matches.
--
-- Re-running is safe. A source key that is already registered is skipped, so
-- an existing record is never duplicated or overwritten, including one that
-- staff have since edited or deleted.
--
-- notices.created_by must reference a real profile, so the import needs the
-- publisher profile below. In a database without it (a fresh local or CI
-- database) the import says so and writes nothing.
-- =============================================================================

do $import$
declare
  c_batch        constant text := 'pccoe-noticeboard-2026-11';
  c_publisher    constant uuid := 'fc79f76a-3355-4788-bbf8-3e6d529ff957';

  -- Sections in display order, each with its entries in display order.
  --   attribution      'organization' (a student body or cell) or 'institution'
  --   match_keys       compared with communities.catalogue_key and slug
  --   match_names      compared with the lower-cased club name and aliases
  --   source_category  the wording of the source
  --   category         the nearest notice_category value
  --   period           the year the entry's own text gives, where it gives one
  --   note             what the source did not preserve, where it says so
  --   digest           md5 of the fields, joined by chr(31):
  --                      section  key, label, organization, attribution,
  --                               keys, names (each '|'-joined)
  --                      entry    section key, slug, title, source_category,
  --                               category, period, note, body ('' when absent)
  c_manifest     constant jsonb := $json$[
    {"key":"itsa","label":"ITSA — Information Technology Student Association","organization":"ITSA","attribution":"organization","match_keys":["itsa"],"match_names":["itsa","information technology student association","information technology students association"],"digest":"5ed88bdf75c7b26b759cb43f7e8532b7",
     "entries":[
      {"slug":"ai-workshop","title":"AI Workshop","source_category":"Technical / Workshop","category":"event","digest":"d51795a3621734bf4c316b600bea9a39",
       "body":"An ITSA learning initiative focused on Artificial Intelligence and its growing role in technology. The workshop introduces students to the field of AI, its fundamental concepts and its relevance to modern computing. It provides an opportunity for students to develop awareness of AI and explore its applications."},
      {"slug":"induction-25","title":"Induction '25","source_category":"Club / Cultural","category":"event","period":"2025","digest":"80a5cd6588b6d93ec3abbe310cc85b45",
       "body":"The ITSA induction programme for the 2025 student intake. An introductory initiative intended to welcome students into the Information Technology student community, familiarise them with the association and introduce the activities, participation opportunities and student engagement associated with ITSA."},
      {"slug":"techpulse-2k25","title":"TechPulse-2K25","source_category":"Technical","category":"event","period":"2025","digest":"3827796f50f8fb749551277bb84a1f1f",
       "body":"A named ITSA technical programme from 2025, included in the association's campus activity archive. Preserve the original title and present it as part of ITSA's record of student-focused technical activities and engagement."},
      {"slug":"techroom-2-0","title":"TechRoom 2.0","source_category":"Technical / Workshop","category":"event","digest":"4c7ed1e9ce00ed67e7508d797fdc37c9",
       "body":"The second-edition TechRoom programme associated with ITSA. It forms part of the association's technical activity and student learning initiatives, providing a space for students to engage with technology-focused activities and knowledge sharing."},
      {"slug":"teachers-day","title":"Teacher's Day","source_category":"Cultural","category":"event","digest":"d00d2723c46bb88e0b1a65bbcc554cf4",
       "body":"An ITSA-organised Teacher's Day celebration recognising the contribution of faculty members to student learning and development. The programme represents a student-led gesture of appreciation and respect for teachers."},
      {"slug":"swc-meditation","title":"SWC Meditation","source_category":"Other","category":"general","digest":"c1a6b8f442ec5bb622c4181043a2ea3b",
       "body":"A meditation and well-being activity identified under the title SWC Meditation. The initiative focuses on encouraging mindfulness, mental relaxation and personal well-being among students through meditation-related engagement. Retain the abbreviation SWC without expanding it."},
