     "entries":[
      {"slug":"teaching-and-learning-activities","title":"Teaching and Learning Activities","source_category":"Academic","category":"academic","digest":"93541e90d08084b9d50de5a1ec2224f7",
       "body":"A record of departmental teaching and learning activities displayed on the institutional noticeboards. This category captures academic initiatives and learning-related activities that form part of the department's educational environment."},
      {"slug":"student-projects","title":"Student Projects","source_category":"Academic","category":"academic","digest":"bc8a1192ec7c8f187ece0ae8b7ce1470",
       "body":"A collection of departmental student project displays highlighting project-based learning and student engagement with practical academic work. Preserve the category as institutional academic information without fabricating project names or authors."},
      {"slug":"pedagogy-and-academic-practices","title":"Pedagogy and Academic Practices","source_category":"Academic","category":"academic","digest":"d0659eb0eaafd521c0f557c6953767d1",
       "body":"Departmental information concerning teaching approaches, pedagogy and academic practices. This entry represents the academic initiatives and educational methods presented through the departmental displays."},
      {"slug":"departmental-academic-showcase","title":"Departmental Academic Showcase","source_category":"Academic","category":"academic","digest":"315d732981920d3757a9b416a31a2705",
       "body":"A general archive entry for departmental academic displays and educational information presented on the noticeboards. Preserve it as an institutional information category rather than inventing individual programmes."}
    ]}
  ]$json$;

  v_section      record;
  v_entry        record;
  v_sections     integer;
  v_entries      integer;
  v_keys         integer;
  v_problem      text;
  v_key          text;
  v_notice_id    uuid;
  v_community_id uuid;
  v_imported     integer := 0;
  v_present      integer := 0;
begin
  -- The whole manifest is checked before anything is written.
  select string_agg(s.value ->> 'key', ', ' order by s.ordinality)
    into v_problem
  from jsonb_array_elements(c_manifest) with ordinality as s(value, ordinality)
  where md5(concat_ws(chr(31),
          s.value ->> 'key', s.value ->> 'label', s.value ->> 'organization', s.value ->> 'attribution',
          array_to_string(array(select jsonb_array_elements_text(s.value -> 'match_keys')), '|'),
          array_to_string(array(select jsonb_array_elements_text(s.value -> 'match_names')), '|')
        )) is distinct from s.value ->> 'digest';
  if v_problem is not null then
    raise exception 'Noticeboard archive section does not match its digest: %', v_problem;
  end if;

  select
    count(distinct s.value ->> 'key'),
    count(*),
    count(distinct (s.value ->> 'key') || '/' || (e.value ->> 'slug')),
    string_agg((s.value ->> 'key') || '/' || (e.value ->> 'slug'), ', ' order by s.ordinality, e.ordinality)
      filter (where md5(concat_ws(chr(31),
                s.value ->> 'key', e.value ->> 'slug', e.value ->> 'title',
                e.value ->> 'source_category', e.value ->> 'category',
                coalesce(e.value ->> 'period', ''), coalesce(e.value ->> 'note', ''), e.value ->> 'body'
              )) is distinct from e.value ->> 'digest')
    into v_sections, v_entries, v_keys, v_problem
  from jsonb_array_elements(c_manifest) with ordinality as s(value, ordinality)
  cross join lateral jsonb_array_elements(s.value -> 'entries') with ordinality as e(value, ordinality);
  if v_problem is not null then
    raise exception 'Noticeboard archive entry does not match its digest: %', v_problem;
  end if;
  if jsonb_array_length(c_manifest) <> 11 or v_sections <> 11 or v_entries <> 64 or v_keys <> 64 then
    raise exception 'The noticeboard archive manifest must hold 11 sections and 64 uniquely keyed entries.';
  end if;

  if not exists (select 1 from public.profiles where id = c_publisher) then
    raise notice 'Noticeboard archive % not imported: publisher profile % does not exist in this database.',
      c_batch, c_publisher;
    return;
  end if;

  for v_section in
    select
      s.ordinality as section_order,
      s.value ->> 'key' as key,
      s.value ->> 'label' as label,
      s.value ->> 'organization' as organization,
      s.value ->> 'attribution' as attribution,
      array(select jsonb_array_elements_text(s.value -> 'match_keys')) as match_keys,
      array(select jsonb_array_elements_text(s.value -> 'match_names')) as match_names,
      s.value -> 'entries' as entries
    from jsonb_array_elements(c_manifest) with ordinality as s(value, ordinality)
    order by s.ordinality
  loop
    -- Link the section to an organisation only on one unambiguous match in the
    -- official club catalogue. No match, or more than one, leaves the entries
    -- attributed by name; an organisation is never created here. Sections
    -- attributed to the institution are never linked to a club.
    select case when count(*) = 1 then (array_agg(c.id))[1] end
      into v_community_id
    from public.communities c
    where v_section.attribution = 'organization'
      and c.kind = 'club'
      and c.status = 'published'
      and (
        c.catalogue_key = any (v_section.match_keys)
        or c.slug = any (v_section.match_keys)
        or lower(btrim(c.name)) = any (v_section.match_names)
        or exists (
          select 1
          from unnest(string_to_array(lower(coalesce(c.directory_aliases, '')), ',')) as alias(value)
          where btrim(alias.value) = any (v_section.match_names)
        )
      );

    for v_entry in
      select x.*
      from jsonb_array_elements(v_section.entries) with ordinality as e(value, ordinality)
      cross join lateral jsonb_to_record(e.value) as x(
        slug text, title text, source_category text, category text, period text, note text, body text
      )
      order by e.ordinality
    loop
      v_key := c_batch || '/' || v_section.key || '/' || v_entry.slug;

      if exists (select 1 from public.notice_archive_entries where source_key = v_key) then
        v_present := v_present + 1;
        continue;
      end if;

      insert into public.notices (title, body, category, importance, pinned, status, created_by)
      values (
        v_entry.title, v_entry.body, v_entry.category::public.notice_category,
        'normal', false, 'archived', c_publisher
      )
      returning id into v_notice_id;

      -- sort_order is the position of the entry in the manifest, 1 to 64.
      insert into public.notice_archive_entries (
        source_key, notice_id, section_key, section_label, organization, attribution, community_id,
        source_category, period, source_note, sort_order, source_checksum
      ) values (
        v_key, v_notice_id, v_section.key, v_section.label, v_section.organization, v_section.attribution,
        v_community_id, v_entry.source_category, v_entry.period, v_entry.note,
        v_imported + v_present + 1, md5(v_entry.title || chr(10) || v_entry.body)
      );

      v_imported := v_imported + 1;
    end loop;
  end loop;

  if (
    select count(*) from public.notice_archive_entries
    where source_key like c_batch || '/%'
  ) <> 64 then
    raise exception 'Noticeboard archive % must register exactly 64 source keys.', c_batch;
  end if;

  raise notice 'Noticeboard archive %: % imported, % already registered.', c_batch, v_imported, v_present;
end
$import$;

-- ==========================================================================
-- FILE 74/79  20261112000028_074_upload_access_default.sql
-- ==========================================================================

-- Give current active profiles upload access and enable it for new accounts.
-- Existing explicit administrator revocations remain effective after rollout.
alter table public.storage_accounts alter column upload_enabled set default true;

-- Account rows are created lazily by the reservation/draft RPCs. Until then,
-- availability must reflect the new default, while preserving explicit false.
create or replace function public.storage_account_usage(p_user uuid)
returns table(upload_enabled boolean, quota_bytes bigint, used_bytes bigint)
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare v_actor uuid := public.current_profile_id();
begin
  if v_actor is null or p_user is null or not public.is_active_profile(v_actor) or
     (p_user <> v_actor and not (public.has_permission('manage_users') and
       (public.has_role('admin') or public.has_role('super_admin')))) then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  return query select coalesce(a.upload_enabled, true), null::bigint,
    (select coalesce(sum(f.byte_size), 0)::bigint from public.storage_files f where f.owner_id = p_user and f.status in ('reserved', 'ready', 'delete_pending'))
    from (select p_user as profile_id) target left join public.storage_accounts a on a.profile_id = target.profile_id;
end $$;

-- Use the existing audited administrative path. Active/pending profiles only;
-- suspension and other authorization checks are unchanged. Already enabled
-- rows are left untouched, so reruns do not emit redundant audit events.
do $$
declare p record;
begin
  for p in select profiles.id from public.profiles profiles
    left join public.storage_accounts a on a.profile_id = profiles.id
    where public.is_active_profile(profiles.id) and coalesce(a.upload_enabled, false) = false
  loop
    perform public.admin_set_upload_enabled(p.id, true);
  end loop;
end $$;

-- ==========================================================================
-- FILE 75/79  20261112000029_075_return_pccoe_noticeboard_to_archive.sql
-- ==========================================================================

-- Campus+ migration 075 — return the PCCOE noticeboard batch to the archive
-- =============================================================================
-- The 64 records imported by migration 073 are historical. On the connected
-- project they were published as current notices on 12 November 2026 (history
-- entry 074_publish_pccoe_noticeboard, which has no file in this repository).
-- Published, they led the noticeboard, the latest-notice lists and the home
-- feed as if they were new announcements.
--
-- Every record of the batch that is still as that step left it (published, with
-- a publication time, never saved by staff) goes back to
--
--   status        'archived'
--   published_at  null
--
-- which is how migration 073 writes it. Nothing else is written: titles,
-- descriptions, categories and provenance are untouched.
--
-- A record that staff have saved since keeps the state staff gave it. Where the
-- batch was never published nothing matches, and a second run changes nothing.
-- =============================================================================

do $archive$
declare
  c_batch    constant text := 'pccoe-noticeboard-2026-11';
  v_returned integer;
begin
  update public.notices as n
     set status = 'archived',
         published_at = null
    from public.notice_archive_entries as e
   where e.notice_id = n.id
     and e.source_key like c_batch || '/%'
     and n.status = 'published'
     and n.published_at is not null
     and n.updated_by is null;
  get diagnostics v_returned = row_count;

  raise notice 'Noticeboard batch %: % records returned to the archive.', c_batch, v_returned;
end
$archive$;

-- ==========================================================================
-- FILE 76/79  20261112000030_076_notice_archive_dates.sql
-- ==========================================================================

-- Campus+ migration 076 — dates for noticeboard archive records
-- =============================================================================
-- An archive record describes something that happened in the past, and its
-- source, a poster on a noticeboard, often says when. Four columns on
-- notice_archive_entries hold that:
--
--   occurred_on          the day it happened, or its first day
--   occurred_until       its last day, when it ran for more than one
--   date_is_approximate  true when only the year is known. occurred_on is then
--                        1 January of that year: a placeholder that keeps the
--                        year in a date column, not a day on which anything
--                        happened. It is shown as the year alone.
--   date_note            where the date comes from, when that needs saying
--                        (a year taken from an edition title, for example)
--
-- A record with no recoverable date leaves all four empty. The period column
-- keeps the labels that are not calendar dates, such as an academic year.
--
-- Nothing reads these columns to decide what is current. Archive records are
-- archived notices, which no latest list, feed, event calendar or notification
-- includes; the date is provenance, shown beside the record.
--
-- No policy, grant or trigger changes. The table stays read-only for clients,
-- and backup capture records whole rows, so the new columns are captured.
-- =============================================================================

alter table public.notice_archive_entries
  add column occurred_on         date,
  add column occurred_until      date,
  add column date_is_approximate boolean not null default false,
  add column date_note           text;

alter table public.notice_archive_entries
  -- A last day needs a first day before it.
  add constraint notice_archive_entries_date_range_check
    check (occurred_until is null or (occurred_on is not null and occurred_until > occurred_on)),
  -- A placeholder is 1 January of the known year and nothing more precise.
  add constraint notice_archive_entries_date_placeholder_check
    check (
      not date_is_approximate
      or (
        occurred_on is not null
        and occurred_until is null
        and extract(month from occurred_on) = 1
        and extract(day from occurred_on) = 1
      )
    ),
  add constraint notice_archive_entries_date_note_check
    check (date_note is null or length(btrim(date_note)) between 5 and 400);

comment on column public.notice_archive_entries.occurred_on is
  'Day the recorded activity happened (its first day). When date_is_approximate is true this is 1 January of the known year: a placeholder, never a real day.';
comment on column public.notice_archive_entries.occurred_until is
  'Last day of an activity that ran for more than one day. Exact dates only.';
comment on column public.notice_archive_entries.date_is_approximate is
  'True when only the year is known. occurred_on then holds 1 January of that year and must be shown as the year alone.';
comment on column public.notice_archive_entries.date_note is
  'Where the date comes from, when that needs saying.';

-- ==========================================================================
-- FILE 77/79  20261112000031_077_pccoe_noticeboard_dates.sql
-- ==========================================================================

-- Campus+ migration 077 — dates of the PCCOE noticeboard batch
-- =============================================================================
-- Dates read from the original noticeboard posters, for the records imported by
-- migration 073. Each line of the manifest names one record by its source key
-- (<section>/<slug> inside the batch) and gives what the poster gives:
--
--   day, last_day   an exact date, or the first and last day of an activity
--   year            the year alone. Stored as 1 January of that year with
--                   date_is_approximate = true: a placeholder, never the day
--   period          a label that is not a calendar date (an academic year, a
--                   span of years). Stored as text; no date is derived from it
--   note            where the date comes from, when that needs saying
--
-- Rules the manifest follows:
--   * a date is recorded only where the poster states it;
--   * a year is never turned into a day, and no date is inferred from a title,
--     from another record or from the current year;
--   * an academic-year label is not a date;
--   * a record that is not listed keeps no date. It stays in the archive in
--     full, as undated material. 27 records are not listed.
--
-- One date on the boards is not recorded: a framed webinar record of the
-- Entrepreneurship & Innovation Cell dated 13 October 2023 could not be matched
-- to any one of that section's seven records.
--
-- Only records that carry no date yet are written, so a date that is already
-- there is never changed and a second run writes nothing. Titles, descriptions,
-- categories, organisations and notices are not touched. Where the batch is not
-- registered, nothing is written.
-- =============================================================================

do $dates$
declare
  c_batch constant text := 'pccoe-noticeboard-2026-11';
  c_dates constant jsonb := $json$[
    {"key": "itsa/ai-workshop", "day": "2025-07-21"},
    {"key": "itsa/induction-25", "day": "2025-07-30"},
    {"key": "itsa/techpulse-2k25", "day": "2025-07-30"},
    {"key": "itsa/techroom-2-0", "day": "2025-08-18"},
    {"key": "itsa/teachers-day", "day": "2025-09-09"},
    {"key": "itsa/swc-meditation", "day": "2025-09-12"},
    {"key": "itsa/abhidnya-2-0-bruteforge", "day": "2025-09-16", "last_day": "2025-09-17"},
    {"key": "itsa/akshardhara", "day": "2025-10-13"},
    {"key": "itsa/praxis", "day": "2026-01-23", "last_day": "2026-01-24"},
    {"key": "itsa/innoveda-24", "day": "2024-10-22", "last_day": "2024-10-23"},
    {"key": "itsa/farewell-25", "day": "2025-04-17", "note": "The day and month are from the poster; the year comes from the edition title."},
    {"key": "itsa/induction-24", "day": "2024-08-29"},

    {"key": "mlsc/techroom", "day": "2025-08-25"},
    {"key": "mlsc/aiquest", "day": "2025-09-17"},
    {"key": "mlsc/project-development", "day": "2025-11-11"},
    {"key": "mlsc/bluebit-4-0", "day": "2026-03-16"},

    {"key": "higher-studies/gre-readiness", "day": "2025-08-05"},
    {"key": "higher-studies/mock-gate", "day": "2025-09-17"},
    {"key": "higher-studies/higher-education-lecture-on-ai", "day": "2025-09-20"},

    {"key": "ieee/invent-pitch", "day": "2025-08-07"},
    {"key": "ieee/iot-workshop", "day": "2025-01-22", "note": "The day and month are from the poster; the year comes from the edition title, IoT Workshop '25."},
    {"key": "ieee/membership-drive", "day": "2025-09-24"},
    {"key": "ieee/resume-building-interview-skills", "day": "2026-02-16"},
    {"key": "ieee/ieee-awards-and-achievements", "period": "2022–2025", "note": "Award years: Nupur Kulkarni — 2022; Rakshit Jain — 2024; Disha Kamalskar — 2024; Vaishnavi Nimse — 2025; Darrel Chong Student Activity Award — 2025."},

    {"key": "nss-isr/energy-conservation", "day": "2025-08-13"},
    {"key": "nss-isr/donation-initiatives", "day": "2025-08-24", "note": "Date of the Community Donation & E-Waste Collection Drive."},
    {"key": "nss-isr/e-waste-collection", "day": "2025-08-24", "note": "Date of the Community Donation & E-Waste Collection Drive."},
    {"key": "nss-isr/road-safety-awareness", "day": "2025-08-24"},

    {"key": "art-circle/firodiya-karandak-2024", "year": 2024},
    {"key": "art-circle/vinodattam", "year": 2024},
    {"key": "art-circle/akshardhara", "year": 2025},
    {"key": "art-circle/social-activity-workshop", "year": 2025},
    {"key": "art-circle/firodiya-karandak-2026", "year": 2026},
    {"key": "art-circle/diya-painting", "period": "AY 2025–26"},
    {"key": "art-circle/digital-poster-drawing-competition", "period": "AY 2025–26"},
    {"key": "art-circle/kavi-sammelan", "year": 2026},
    {"key": "art-circle/swartarang", "year": 2026}
  ]$json$::jsonb;
  v_registered integer;
  v_written    integer;
begin
  -- The manifest is checked as a whole before anything is written.
  if exists (
    select 1
    from jsonb_to_recordset(c_dates) as d(key text, day date, last_day date, year integer, period text, note text)
    where d.key is null
       or d.key !~ '^[a-z0-9]+(-[a-z0-9]+)*/[a-z0-9]+(-[a-z0-9]+)*$'
       -- a day or a year, never both
       or (d.day is not null and d.year is not null)
       or (d.last_day is not null and (d.day is null or d.last_day <= d.day))
       or (d.year is not null and d.year not between 1990 and 2100)
       -- a line that says nothing
       or (d.day is null and d.year is null and d.period is null and d.note is null)
  ) then
    raise exception 'The noticeboard date manifest is malformed.';
  end if;

  if (select count(*) <> count(distinct d.key) from jsonb_to_recordset(c_dates) as d(key text)) then
    raise exception 'The noticeboard date manifest names a record twice.';
  end if;

  select count(*) into v_registered
  from public.notice_archive_entries
  where source_key like c_batch || '/%';

  if v_registered = 0 then
    raise notice 'Noticeboard batch % is not registered here: no dates recorded.', c_batch;
    return;
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(c_dates) as d(key text)
    where not exists (
      select 1 from public.notice_archive_entries e where e.source_key = c_batch || '/' || d.key
    )
  ) then
    raise exception 'The noticeboard date manifest names a record that is not registered.';
  end if;

  update public.notice_archive_entries as e
     set occurred_on = coalesce(d.day, make_date(d.year, 1, 1)),
         occurred_until = d.last_day,
         date_is_approximate = d.year is not null,
         period = coalesce(e.period, d.period),
         date_note = d.note
    from jsonb_to_recordset(c_dates) as d(key text, day date, last_day date, year integer, period text, note text)
   where e.source_key = c_batch || '/' || d.key
     -- only a record that carries no date yet
     and e.occurred_on is null
     and e.occurred_until is null
     and not e.date_is_approximate
     and e.date_note is null
     -- and only when there is something to write
     and (d.day is not null or d.year is not null or d.note is not null or e.period is null);
  get diagnostics v_written = row_count;

  raise notice 'Noticeboard batch %: dates recorded for % of % registered records.',
    c_batch, v_written, v_registered;
end
$dates$;

-- ==========================================================================
-- FILE 78/79  20261112000032_078_klipy_gif_references.sql
-- ==========================================================================

-- Add KLIPY GIF references without modifying existing rows, RLS or grants.
-- Deploy only with explicit production approval after testing the client and CDN.
-- Retain the legacy GIPHY expression and also match its intended literal-dot
-- host pattern, which the historical expression double-escaped.

alter table public.posts
  drop constraint posts_gif_provider,
  drop constraint posts_gif_url_host,
  add constraint posts_gif_provider check (
    gif is null or (gif->>'provider') in ('giphy', 'klipy')
  ),
  add constraint posts_gif_url_host check (
    gif is null or case gif->>'provider'
      when 'giphy' then ((gif->>'url') ~ '^https://(media[0-9]?\\.)?giphy\\.com/'
                         or (gif->>'url') ~ '^https://(media[0-9]?[.])?giphy[.]com/')
      when 'klipy' then coalesce((gif->>'url') ~ '^https://static[12]?[.]klipy[.]com/', false)
      else false
    end
  );

alter table public.comments
  drop constraint comments_gif_provider,
  drop constraint comments_gif_url_host,
  add constraint comments_gif_provider check (
    gif is null or (gif->>'provider') in ('giphy', 'klipy')
  ),
  add constraint comments_gif_url_host check (
    gif is null or case gif->>'provider'
      when 'giphy' then ((gif->>'url') ~ '^https://(media[0-9]?\\.)?giphy\\.com/'
                         or (gif->>'url') ~ '^https://(media[0-9]?[.])?giphy[.]com/')
      when 'klipy' then coalesce((gif->>'url') ~ '^https://static[12]?[.]klipy[.]com/', false)
      else false
    end
  );

alter table public.messages
  drop constraint messages_gif_provider,
  drop constraint messages_gif_url_host,
  add constraint messages_gif_provider check (
    gif is null or (gif->>'provider') in ('giphy', 'klipy')
  ),
  add constraint messages_gif_url_host check (
    gif is null or case gif->>'provider'
      when 'giphy' then ((gif->>'url') ~ '^https://(media[0-9]?\\.)?giphy\\.com/'
                         or (gif->>'url') ~ '^https://(media[0-9]?[.])?giphy[.]com/')
      when 'klipy' then coalesce((gif->>'url') ~ '^https://static[12]?[.]klipy[.]com/', false)
      else false
    end
  );

alter table public.random_messages
  drop constraint random_messages_gif_provider,
  drop constraint random_messages_gif_url_host,
  add constraint random_messages_gif_provider check (
    gif is null or (gif->>'provider') in ('giphy', 'klipy')
  ),
  add constraint random_messages_gif_url_host check (
    gif is null or case gif->>'provider'
      when 'giphy' then ((gif->>'url') ~ '^https://(media[0-9]?\\.)?giphy\\.com/'
                         or (gif->>'url') ~ '^https://(media[0-9]?[.])?giphy[.]com/')
      when 'klipy' then coalesce((gif->>'url') ~ '^https://static[12]?[.]klipy[.]com/', false)
      else false
    end
  );

-- Preserve the deployed function body and privileges, replacing only its
-- provider guard. Fail atomically if its body differs from the audited version.
do $migration$
declare
  definition text;
  old_guard constant text := $$coalesce(p_gif->>'provider', '') <> 'giphy'$$;
  new_guard constant text := $$coalesce(p_gif->>'provider', '') not in ('giphy', 'klipy')$$;
begin
  select pg_get_functiondef('public.send_random_message(uuid,text,jsonb)'::regprocedure)
    into definition;
  if (length(definition) - length(replace(definition, old_guard, ''))) / length(old_guard) <> 1 then
    raise exception 'send_random_message provider guard differs from audited definition';
  end if;
  execute replace(definition, old_guard, new_guard);
end
$migration$;

-- ==========================================================================
-- FILE 79/79  20261112000033_079_user_follows.sql
-- ==========================================================================

-- Private, directional follow relationships between existing Campus+ profiles.
-- No counters or public follower lists are exposed.
create table public.user_follows (
  follower_id uuid not null references public.profiles(id) on delete cascade,
  followed_id uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (follower_id, followed_id),
  constraint user_follows_no_self check (follower_id <> followed_id)
);

create index user_follows_followed_idx on public.user_follows (followed_id, follower_id);
create index posts_following_feed_idx on public.posts (author_id, created_at desc, id desc)
  where status = 'published' and deleted_at is null;

alter table public.user_follows enable row level security;
revoke all on public.user_follows from public, anon, authenticated;
grant select, insert, delete on public.user_follows to authenticated;
grant all on public.user_follows to service_role;

create policy user_follows_select_own on public.user_follows
  for select to authenticated using (follower_id = public.current_profile_id());
create policy user_follows_insert_own on public.user_follows
  for insert to authenticated with check (
    follower_id = public.current_profile_id()
    and public.is_active_user()
    and public.is_active_profile(followed_id)
    and not public.is_blocked_with_current(followed_id)
  );
create policy user_follows_delete_own on public.user_follows
  for delete to authenticated using (follower_id = public.current_profile_id());

-- Preserve the existing snapshot and change-capture contract for new tables.
select public.backup_sync_triggers();

-- Invoker RLS is retained. Explicit predicates also prevent a moderator's
-- broader post policy from widening the ordinary Following feed.
create function public.following_feed(p_limit integer default 10, p_offset integer default 0)
returns setof public.posts
language sql stable security invoker
set search_path = public, pg_temp
as $$
  select p.*
  from public.user_follows f
  join public.posts p on p.author_id = f.followed_id
  where f.follower_id = public.current_profile_id()
    and public.is_active_user()
    and public.feature_enabled('feed')
    and p.status = 'published'
    and p.deleted_at is null
    and public.is_active_profile(p.author_id)
    and not public.is_blocked_with_current(p.author_id)
    and not public.is_muted_by_current(p.author_id)
    and ((p.community_id is null and p.visibility in ('public', 'campus'))
      or (p.community_id is not null and public.can_view_community(p.community_id)))
  order by p.created_at desc, p.id desc
  limit greatest(1, least(coalesce(p_limit, 10), 50))
  offset greatest(0, least(coalesce(p_offset, 0), 500));
$$;
revoke all on function public.following_feed(integer, integer) from public, anon;
grant execute on function public.following_feed(integer, integer) to authenticated, service_role;

-- ==========================================================================
-- VERIFICATION — reports whether the install is complete (no changes made)
-- ==========================================================================

do $$
declare
  v_auth_triggers integer;
  v_rls integer;
begin
  select count(*) into v_auth_triggers
    from pg_trigger
   where tgname in ('on_auth_user_created', 'enforce_institutional_domain_trigger')
     and not tgisinternal;

  select count(*) into v_rls
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and c.relkind = 'r' and c.relrowsecurity;

  if v_auth_triggers < 2 then
    raise warning 'Campus+ install incomplete: only % of 2 auth.users triggers exist. Sign-in cannot provision accounts until both are created — re-run the section headed "auth hooks" (file 12) from this script.', v_auth_triggers;
  end if;
  if v_rls < 30 then
    raise warning 'Campus+ install incomplete: only % tables in schema public have row level security. Re-run the migration files in order.', v_rls;
  end if;
end $$;

select
  (select count(*) from public.roles)                 as roles,
  (select count(*) from public.permissions)           as permissions,
  (select count(*) from public.role_permissions)      as role_permissions,
  (select count(*) from public.colleges)              as colleges,
  (select count(*) from public.marketplace_categories) as categories,
  (select count(*) from public.feature_flags)         as feature_flags,
  (select count(*) from public.platform_settings)     as platform_settings,
  (select count(*) from pg_class c
     join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind = 'r' and c.relrowsecurity) as tables_with_rls,
  (select count(*) from pg_trigger
    where tgname in ('on_auth_user_created', 'enforce_institutional_domain_trigger')
      and not tgisinternal)                           as auth_triggers,
  (select count(*) from pg_proc p
     join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public')                       as public_functions,
  case
    when (select count(*) from public.roles) >= 4
     and (select count(*) from public.permissions) >= 40
     and (select count(*) from public.platform_settings) >= 10
     and (select count(*) from pg_trigger
           where tgname in ('on_auth_user_created', 'enforce_institutional_domain_trigger')
             and not tgisinternal) = 2
    then 'INSTALL OK — next: sign in once, then npm run role:grant -- --email you@pccoepune.org --role super_admin'
    else 'INCOMPLETE — read the warnings above and docs/DEPLOYMENT.md §3'
  end as verdict;
